import type { ModelGuideData, GuideBlock, GuideSection } from '../../components/model-guide/types';
import { ampPhotos as ph } from './fender-amp-photos';
import { ampPhotos2 as ph2 } from './fender-amp-photos-2';
import values from './fender-amps-values.json';
import { p, section, money } from './helpers';

const dark=(id:string,title:string,eyebrow:string,blocks:GuideBlock[])=>section(id,title,eyebrow,blocks,'dark');
const dating='/vintage-fender-amplifier-serial-numbers-how-to-find-the-year/';
const era='/post/fender-amp-eras-tweed-brownface-blackface-silverface/';
const comparison='/post/princeton-reverb-vs-deluxe-reverb-vs-twin-reverb/';
const link=(family:string,kind='authentication')=>`/post/fender-${family}-reverb-${kind}-guide/`;
const a=(href:string,text:string)=>`<a href="${href}">${text}</a>`;
const paras=(...text:string[])=>p(text.map(t=>`<p>${t}</p>`).join(''));
const list=(items:[string,string][]):GuideBlock=>({type:'checklist',items:items.map(([title,html])=>({title,html:`<p>${html}</p>`}))});
const columns=(items:[string,string][]):GuideBlock=>({type:'columns',items:items.map(([title,html])=>({title,html:`<p>${html}</p>`}))});
const price=(family:string,configuration='Blackface',model?:string)=>{const normalized=configuration==='Tweed, narrow panel, large cabinet'?'Narrow panel, large cabinet':configuration==='Silverface, logo with tail'?'Silverface, Fender logo with tail':configuration;const r=values.find(r=>r.family===`fender-${family}-reverb`&&r.configuration===normalized&&(!model||r.model===model));if(!r)throw new Error('Missing value '+family);return `${money(r.low)} to ${money(r.high)}`;};
const chart=(family:string):GuideBlock=>({type:'table',valueChart:true,caption:'Joe’s Estimated Values: Excellent, Original Amplifiers',columns:['Model','Years','Version','Estimated Value'],rows:values.filter(r=>r.family===`fender-${family}-reverb`).map(r=>[r.model,r.years,r.configuration,`${money(r.low)} to ${money(r.high)}`]),note:'U.S. dollars. Original cover where applicable. These estimates are starting points for an individual appraisal; condition, changed parts and required service affect the assessment. Overlapping year groups describe separate guide entries.'});
const cta=(title:string,html:string):GuideBlock=>({type:'cta',title,html:`<p>${html}</p>`,appraisalLabel:'Free Appraisal',sellLabel:'Sell My Amp',sellHref:'/sell-an-amplifier-or-effect/'});
const defaults={brand:'Fender' as const,date:'November 2, 2026',plainNumbers:true,sellLabel:'Sell My Amp',sellHref:'/sell-an-amplifier-or-effect/',authorBio:'Joe Dampt owns Joe’s Vintage Guitars in Mesa, Arizona. His amplifier archive includes tweed, brownface, blackface and silverface Fenders. The photographs in these guides come from that archive.'};
const valueBase=(family:string)=>({...defaults,slug:`fender-${family}-reverb-value-guide`,kind:'value' as const,closingTitle:'Get Your Amp Appraised',faqSubtitle:'Vintage Amp Values',secondaryActions:[{label:'View The Value Chart',href:'#values'},{label:'Identify Your Amp',href:link(family)}] as [{label:string;href:string},{label:string;href:string}]});

const twinValue:ModelGuideData={...valueBase('twin'),title:'Vintage Fender Twin And Twin Reverb Values',seoTitle:'Vintage Fender Twin Reverb Value Guide: Prices By Era',description:'Find vintage Fender Twin and Twin Reverb values by era, with original amp photos, speaker and transformer checks, and appraisal guidance from Joe.',eyebrow:'Tweed Twin To Silverface Twin Reverb',dek:'Estimated values for original Twins, with separate rows for the versions that collectors and players need to distinguish.',hero:ph.blondeFront,glanceTitle:'Twin Values At A Glance',glance:[['Blackface Twin Reverb',price('twin')],['1958 To 1959 Tweed Twin',price('twin','Tweed, 80 watts')],['1963 Blonde Twin',price('twin','Smooth white covering, gold grille')],['Coverage','Original models through 1980']],intro:{html:`<p>A vintage blackface Fender Twin Reverb is estimated at ${price('twin')} in excellent, original condition. The earlier Twin family reaches a different price level: the 1958 to 1959 tweed version is ${price('twin','Tweed, 80 watts')}. Find the correct model before comparing those figures. The ${a(link('twin'),'Twin identification guide')} separates the tweed and blonde Twin from the later Twin Reverb and its silverface revisions. Speakers, transformers, cabinet condition and service history then determine how closely your amp fits its row.</p>`,calloutTitle:'Choose The Matching Twin',callout:'A tweed Twin, a blonde Twin and a silverface Twin Reverb belong to different value groups. The name alone is too broad for an appraisal.'},sections:[
section('values','Twin Prices By Version','Excellent, Original Examples',[chart('twin'),paras('These estimates cover original vintage amps only; modern reissues and Tone Master models require separate appraisals. Fender introduced a factory master volume in 1972, while the chart’s master-volume group begins in 1973. A factory 1972 master-volume example needs an individual assessment rather than being forced into the no-master-volume row. A factory control that has been disconnected still forms part of the amp’s history. Photograph the panel and explain any modification before assigning a range.','The black-panel return around 1980 needs its own appraisal. Send identifying photographs of an amp from that transition, including its panel, chart and component stamps. A missing chart row doesn’t mean your amp has no value.')]),
section('early-twins','Why Tweed And Blonde Twins Need Separate Appraisals','Earlier Cabinets And Circuits',[columns([
['Tweed Twin Condition',`The early Twin rows cover visibly different cabinet generations and output versions. A narrow-panel cabinet alone doesn’t establish which electrical version it contains. The high-power tweed entry deserves close documentation of the chassis, transformer set and cabinet before its range is applied. Save any repair invoices or photographs taken before servicing. They can explain why an old amp contains newer parts without requiring an appraiser to guess what happened.`],
['Blonde Twin Completeness','The blonde Twin has its own market position. Look closely at the light covering, grille, handle and hardware as a group. Fresh white material can make a cabinet look attractive while changing its appeal to an originality-focused buyer. The same applies to a replaced grille that happens to resemble the correct pattern. A clear photograph of a worn original surface is more useful than a description such as “restored to mint.”']]),paras('Joe’s 1963 Twin photographs show the front, back and tube chart of one amp. They give an owner useful views to reproduce when requesting an appraisal. They don’t establish that every part in another blonde Twin is original. Each amp needs its own record, especially when an owner inherited it without service paperwork.','Keep the cover with the amplifier if it survives. Photograph its material, stitching, logo and damage separately. A newly purchased reproduction cover may protect the cabinet, but it should be described as a later accessory. The same disclosure applies to replacement tilt-back hardware or a handle fitted to make carrying the amp easier.')]),
{type:'photo-band',photos:[ph.blondeFront,ph.twinFront],quote:'1963 Fender Twin And 1966 Fender Twin Reverb'},
dark('black-and-silver','Blackface And Silverface Value Differences','Match The Control Panel',[paras(`The blackface Twin Reverb estimate is ${price('twin')}. Silverface examples occupy their own rows, including early versions without a master volume and later versions with additional controls. These groups give you a more useful comparison than a single price for all silverface amps. The ${a(era,'Fender amp eras article')} explains the appearance changes, while the identification page deals with the circuitry and date evidence.`, 'An early silverface grille surround can attract attention, but aluminum trim alone can’t establish the circuit or an exact year. A correct appraisal considers the chassis and its components alongside the outside appearance. If the cabinet and chassis came from different amps, disclose that before comparing your amplifier with an excellent original example.','Later high-power Twins also deserve an accurate description. Their intended use, controls and specifications differ from an earlier blackface amp. Calling one “basically the same” removes information that a player or collector needs. Describe the amp you have, including the rear-panel markings, instead of using the most desirable earlier version as the pricing reference.')]),
section('components','Speakers, Transformers And Cabinet Work','What Changes The Assessment',[columns([
['Both Speakers Need Documentation','A Twin has two speaker positions to account for. Photograph both baskets, labels and readable stamps, even when they appear to match. One original speaker and one replacement is a different condition report from a complete original pair. A period speaker installed later also needs that qualification. If a speaker was reconed, retain the invoice and identify which one received the work. A matching label doesn’t establish the condition of the cone.'],
['Transformer Replacements Need Context','A replaced output or power transformer affects how an originality-focused buyer evaluates the amp. The replacement’s brand, specification and installation should be recorded. A correct working replacement may make the amplifier useful to a player, but it doesn’t recreate the missing factory component. Keep a removed transformer if you still have it and describe why it was taken out. Its presence in a box doesn’t mean it remains usable.']]),paras('Cabinet work requires its own photographs. Recovering, a replacement baffle, added casters and repaired joints can be easy to miss in a straight-on view. Show the bottom, corners and inside surfaces where they’re safely accessible. Avoid assigning a fixed deduction to every alteration. Several changes can interact, and the starting version of the Twin still matters.','Reverb equipment is another part of the inventory. Include the tank, its bag, cables and footswitch on a Twin Reverb. If the tank was replaced, show the present label and any retained original. A working reverb control tells you something about operation; it doesn’t identify every component in the system. A non-reverb Twin shouldn’t be marked incomplete for lacking equipment it never had.')]),
section('service','How Service History Fits The Value','Record The Work',[paras('Old filter capacitors, worn tubes and a damaged power cord are service questions. An appraiser should know what was replaced, who did the work and whether the amp was checked afterward. An invoice that identifies the actual repair is more useful than “recently serviced.” It also keeps necessary maintenance from being confused with a wholesale rebuild.','Don’t postpone necessary safety work merely to preserve an “untouched” description. Have a qualified amp technician evaluate an amplifier with an unknown electrical history. If you’re selling an untested amp, describe it as untested rather than powering it up to produce a video. Inspection photographs can be supplied by the technician when chassis access is needed.','A service bill and an increase in resale value aren’t interchangeable figures. Some work restores normal operation, while other work changes the circuit to suit a particular player. Tell Joe which category applies and include before-and-after records if you have them. Avoid replacing speakers or recovering the cabinet solely to improve its appearance before asking for an appraisal.')]),
section('appraisal','Photos For A Twin Appraisal','Show The Whole Amplifier',[list([
['Front And Control Panel','Send a square view showing the full grille, cabinet edges, model name and every control. Include a closer picture of any master-volume or boost marking so the version can be matched accurately.'],
['Rear View And Back Panels','Show both speakers, the rear controls and the complete back opening. Add photographs of missing panels, added hardware or cabinet damage rather than cropping those areas out.'],
['Chassis And Tube Chart','Photograph the paper chart where it remains attached. Ask a qualified technician for chassis photographs; opening an amplifier can expose dangerous stored voltage even after it has been unplugged.'],
['Transformer Markings','Provide readable views of the power transformer, output transformer and choke. Retain the full stamped line and its location in the photograph so a part number isn’t mistaken for a date.'],
['Both Speaker Labels','Include each label, frame stamp and visible cone marking. State whether either speaker has been replaced or reconed, and attach repair paperwork if it survives.'],
['Reverb Tank And Accessories','For a Twin Reverb, add the tank label and footswitch. Show the cover, removed parts and documents separately, noting which accessories came with the amp and which were purchased later.']]),paras(`Use the ${a(dating+'#amp-decoder','tube-chart decoder')} when a clear date stamp survives. If it doesn’t, the ${a(dating+'#tc-9','transformer and speaker dating section')} explains the next evidence to collect. The ${a('/fender-pot-codes/','pot-code guide')} can help with readable control markings. Fender amp serial numbers don’t provide a reliable year, so a serial alone won’t settle the value group.`),cta('Send Your Twin Photos To Joe','Include what you know about ownership and repairs, even if the history is incomplete. Joe can review the photographs and discuss the amp’s present condition.')]),
],faqs:[{q:'Are Tweed Twins Priced Like Twin Reverbs?',a:'They have separate value groups. Match the cabinet generation and circuit before applying an estimate; the earlier Twin name covers several versions.'},{q:'Does A Replaced Speaker Make A Twin Worthless?',a:'No. Identify which speaker changed and whether the original survives. The resulting assessment depends on the amp’s version and the rest of its condition.'},{q:'Can I Use These Ranges For A Reissue?',a:'These figures cover original vintage amplifiers only. Modern reissues and Tone Master models need a separate appraisal.'}],closing:`<p>Start with the version, then document what remains and what has changed. Return to the ${a(link('twin'),'Twin and Twin Reverb identification page')} if the controls or cabinet leave the model uncertain. For a playing comparison, the ${a(comparison,'Princeton, Deluxe and Twin article')} explains the differences in size and output. You can ${a('/free-appraisal/','request a free appraisal')} with the photos you already have.</p>`};

const deluxeValue:ModelGuideData={...valueBase('deluxe'),title:'Vintage Fender Deluxe And Deluxe Reverb Values',seoTitle:'Vintage Fender Deluxe Reverb Value Guide: Era Prices',description:'Check vintage Fender Deluxe and Deluxe Reverb values, from tweed 5E3 amps to silverface models, with condition notes and original photos from Joe.',eyebrow:'Tweed Deluxe, Brownface And Reverb Models',dek:'Values for the Deluxe family, with the 5E3, brownface, non-reverb blackface and Deluxe Reverb kept in their own groups.',hero:ph.tweedFront,glanceTitle:'Deluxe Price Groups',glance:[['Blackface Deluxe Reverb',price('deluxe','Blackface','Deluxe Reverb')],['1956 To 1960 Tweed Deluxe',price('deluxe','Tweed, narrow panel, large cabinet')],['Condition Basis','Excellent and original'],['Modern Reissues','Excluded from these ranges']],intro:{html:`<p>A blackface Fender Deluxe Reverb is estimated at ${price('deluxe','Blackface','Deluxe Reverb')} in excellent, original condition. Tweed, brownface and non-reverb Deluxes have separate entries below. The ${a(link('deluxe'),'Deluxe identification guide')} helps establish which version you own before its condition is priced. A Deluxe nameplate or a single twelve-inch speaker doesn’t distinguish all these amps. The cabinet, controls and dated components need to support the description.</p>`,calloutTitle:'Confirm The Reverb Version',callout:'The Deluxe and Deluxe Reverb are separate models. Check the faceplate and control layout before choosing a chart row.'},sections:[
section('values','Deluxe Values From Tweed To Silverface','Original Vintage Amplifiers',[chart('deluxe'),paras('The chart separates the early cabinet styles and distinguishes the non-reverb Deluxe from the Deluxe Reverb. Read across the entire row, including its configuration. A year shared by two entries doesn’t make those amps interchangeable. If a cabinet has been replaced, the chassis may need a closer inspection before the original version can be established.','No estimate here covers a modern 5E3 kit or Fender reissue. A handwired circuit and aged tweed covering can resemble a vintage amp without providing vintage provenance. Likewise, a later black-panel reissue shouldn’t be placed in the original blackface row. Ask for identification help first if the seller’s description and the rear label disagree.')]),
section('tweed-value','Pricing A Tweed Deluxe With Its History Intact','Cabinet, Speaker And Circuit',[paras('The narrow-panel tweed Deluxe needs more than a tidy exterior to support an excellent-original estimate. Show the cabinet joints, covering seams, grille and rear panels as well as the control panel. A re-covered cabinet can retain its old chassis and still require a different condition assessment. Describe which parts were restored instead of applying the word “restored” to the entire amplifier.','Speaker condition deserves equal attention. An original frame with a replacement cone should be identified that way. A modern speaker installed for regular playing is another situation. If the older speaker survives, photograph it separately and state whether it worked when removed. The appraisal can then account for the amp’s current configuration and the parts accompanying it.','Joe’s 1957 Deluxe photographs include the paper 5E3 chart and an interior view showing service components. Those images illustrate the questions an appraiser needs to ask. An archive date doesn’t certify every capacitor, transformer or speaker in the amp. Use the same distinction when describing your own Deluxe: production identity and current originality are related but separate findings.','An earlier TV-front or wide-panel Deluxe must be matched with its corresponding entry. Borrowing a later narrow-panel value because both amps wear tweed overlooks the cabinet generation the chart is pricing. If family notes give only an approximate decade, send the front and control panel before trying to narrow the year yourself.')]),
{type:'photo-band',photos:[ph.tweedFront,ph.deluxeFront],quote:'1957 Fender Deluxe And 1967 Fender Deluxe Reverb'},
section('brown-black-silver','Brownface, Blackface And Silverface Price Groups','Model Changes Before Condition',[columns([
['Brownface And Non-Reverb Deluxe','The brownface Deluxe has its own row, as does the later blackface Deluxe without reverb. A buyer looking for one of those versions may care about details that don’t apply to a Deluxe Reverb. Photograph the exact model lettering and controls. Don’t describe the absence of a reverb tank as a missing part until the model itself has been established.'],
['Deluxe Reverb Through 1980','Original blackface and silverface Deluxe Reverbs are divided into their listed groups. An early silverface appearance needs date and circuit evidence before a narrower description is justified. Later control changes also belong in the condition record. A boost function that was disconnected during servicing should be disclosed even if the amp now sounds the way its owner prefers.']]),paras(`The ${a(era,'Fender eras comparison')} can help identify the broad visual period. For a purchase based on playing needs, read the ${a(comparison,'Princeton Reverb versus Deluxe Reverb versus Twin Reverb comparison')}. Neither the era nickname nor the wattage supplies a condition grade. Those details establish what you’re comparing; the inspection determines how well the individual amp fits its estimate.`, 'Some price references group the black-panel return with years beyond this page’s 1980 cutoff. This chart leaves those mixed-period entries out instead of splitting their figures. An original 1980 amp with that appearance can still be appraised individually. Send its rear markings, chart and dated parts, and avoid assigning it an earlier blackface identity from color alone.')]),
dark('condition','What Moves A Deluxe Away From Its Chart Range','Parts And Repairs',[columns([
['The Transformer Set','Document the power transformer, output transformer and any choke appropriate to the circuit. Their markings and installation help distinguish a retained factory part from a replacement. A technician’s invoice may explain a replacement made after a failure. Keep that explanation with the amp; an unsupported claim that every transformer is original can create a problem at inspection.'],
['The Cabinet And Grille','A Deluxe’s compact cabinet can hide substantial work in an attractive front photograph. Show replacement panels, repaired corners, a changed baffle or holes left by added hardware. Photograph the covering in natural light without a filter. The condition report should describe wear, repairs and replacement material clearly enough for a buyer to understand what survives.']]),paras('Small parts still belong in the inventory. A replacement handle, missing footswitch or later cover should be mentioned even when it isn’t the largest issue. On a Deluxe Reverb, identify the tank and its cables as well. Completeness helps explain the estimate, but there’s no useful universal deduction for every missing accessory across every Deluxe version.','Separate service from redesign. Filter capacitors and worn tubes can require attention during normal upkeep; altered circuitry, changed transformers or a replacement cabinet raise additional originality questions. List both kinds of work in plain terms. An amplifier can be serviced and well documented without being described as untouched. It can also be clean on the outside while needing electrical evaluation.','Keep any removed original parts with a note describing their condition. Don’t reinstall a failed part just to improve a sales description. A qualified technician should decide what’s safe to operate. If the amp hasn’t been inspected recently, an appraisal can begin with photographs and an accurate statement of what is known, without a power-on demonstration.')]),
section('selling','Prepare The Deluxe Before Asking For A Value','Preserve The Evidence',[paras('Gather the amp, cover, footswitch, repair receipts and any photographs from earlier ownership. Make a short list of changes you know about and mark uncertain items as uncertain. That’s more useful than guessing a year from the appearance of the tubes or relying on a seller’s old advertisement. Components can be changed many years after the cabinet was built.','Cleaning should preserve identifying marks. Don’t scrub a speaker stamp, tube-chart ink or transformer lettering to improve a photograph. Take several pictures in diffuse light and keep the originals at full resolution. If a mark is still unreadable, leave it unreadable in the description. A partial code is a reason for further inspection, not a reason to fill in the missing characters.','An asking price from another amp won’t show whether it sold or whether its parts match yours. Use the chart as a starting estimate and then document the individual differences. The purchase offer, if you choose to sell, follows an assessment of the actual amplifier and its present needs. Required work can affect that discussion even when the cosmetic condition looks strong.')]),
section('appraisal','Send These Deluxe Photographs','Views That Support An Appraisal',[list([
['The Full Front','Include all four cabinet edges and the complete faceplate. A close-up of the model lettering helps distinguish a Deluxe from a Deluxe Reverb without relying on a caption.'],
['The Back Opening','Show the speaker, back panels and rear chassis markings together. If a panel is absent, send the amp as it stands and mention any loose panel you still have.'],
['The Tube Chart And Chassis','Capture the chart in place and retain faint markings in the original image. Internal chassis pictures should come from a qualified technician because stored electrical charge can remain after unplugging.'],
['The Transformer Stamps','Include the full numbers on each accessible transformer and the mounting area. Ask the technician to photograph concealed markings during an inspection rather than opening the chassis yourself.'],
['The Speaker’s Identification','Show the label, basket code and any visible cone marks. Add a note about reconing or speaker substitution so the pictures and the repair history can be read together.'],
['Reverb Equipment And Cover','For the reverb model, include the tank label and footswitch. Lay out the cover and retained parts separately, with enough detail to see wear and later replacements.']]),paras(`Date evidence belongs with those pictures. Joe’s ${a(dating+'#amp-decoder','amp date-code decoder')} handles readable tube-chart stamps, and his ${a('/fender-pot-codes/','Fender pot-code guide')} addresses control codes. The chassis serial is a useful identifying record, but Fender amp serial numbers aren’t reliable for finding the year.`),cta('Ask Joe About Your Deluxe','Send the photos and a short repair history. Include any uncertainty about the model or date so it can be resolved before a value is assigned.')])],faqs:[{q:'Is A 5E3 Clone Included In This Chart?',a:'No. These estimates apply to original vintage Fender amplifiers. A clone or reissue needs its own identification and valuation.'},{q:'Should I Recover My Deluxe Before Selling?',a:'Ask for an assessment first. Recovering changes the originality record, and the work’s cost may not be recovered in a sale.'},{q:'Does A Service Invoice Add Its Full Cost To The Value?',a:'No automatic addition applies. The invoice explains what was done and helps establish present condition; the amplifier is appraised as a whole.'}],closing:`<p>A useful Deluxe estimate starts with the right version and a clear account of its components. Check the ${a(link('deluxe'),'Deluxe and Deluxe Reverb identification guide')} for the physical details, then ${a('/free-appraisal/','send Joe your appraisal photographs')}. If you’re ready to sell, the ${a('/sell-an-amplifier-or-effect/','amplifier buying page')} explains the next step.</p>`};

const princetonValue:ModelGuideData={...valueBase('princeton'),title:'Vintage Fender Princeton And Princeton Reverb Values',seoTitle:'Vintage Fender Princeton Reverb Value Guide: Prices',description:'See vintage Princeton and Princeton Reverb values by version, with photos of Joe’s amps, originality checks, repair notes and free appraisal help.',eyebrow:'Tweed Princeton Through Silverface Reverb',dek:'Separate estimates for the small tweed Princeton, the brownface and blackface non-reverb models, and the Princeton Reverb.',hero:ph.princetonFront,glanceTitle:'Princeton Values At A Glance',glance:[['Blackface Princeton Reverb',price('princeton','Blackface','Princeton Reverb')],['1968 To 1972 Reverb',price('princeton','Silverface, logo with tail','Princeton Reverb')],['Versions Covered','Reverb and non-reverb'],['Price Condition','Excellent and original']],intro:{html:`<p>A vintage blackface Princeton Reverb is estimated at ${price('princeton','Blackface','Princeton Reverb')} in excellent, original condition. Earlier Princetons and the non-reverb versions use different rows. Read the ${a(link('princeton'),'Princeton identification guide')} if the controls, cabinet or model lettering leave you unsure which amp you own. The name remained in use through substantial design changes, so an estimate needs the version as well as an approximate year. The chart below supplies that starting point.</p>`,calloutTitle:'Reverb Is A Model Distinction',callout:'A Princeton and a Princeton Reverb should be identified separately. A similar cabinet size doesn’t put them in the same price group.'},sections:[
section('values','Princeton Values By Model And Period','Find The Matching Row',[chart('princeton'),paras('Some non-reverb Princeton entries describe overlapping circuit and cosmetic groups. A 1974 amp with the listed AB1270 circuit and a tailed logo can match more than one entry. The chart preserves those source rows, so it doesn’t establish one unique estimate in that situation. Send Joe the specific amp for assessment instead of choosing whichever range is highest.','The chart ends with price groups that fit the vintage scope through 1980. A later black-panel return grouped with post-1980 production isn’t divided into invented single-year figures. Unlisted versions remain individual appraisal questions. Modern Princeton reissues, signature models and digital Tone Master amplifiers aren’t covered by these original-era estimates.')]),
section('early-princeton','Tweed And Brownface Princeton Values','Identify The Earlier Family',[columns([
['The Small Tweed Princeton','The earliest rows distinguish TV-front, wide-panel and narrow-panel cabinets. The narrow-panel entries also separate cabinet sizes. Those descriptions need to agree with the actual cabinet and chassis. A small tweed amplifier that looks like a Princeton in a photograph may need additional identification before any of these ranges applies. Send the panel lettering and a full rear view along with the front.'],
['The Brownface Princeton','A brownface Princeton has its own group in the table. Its covering, grille and controls should be documented together, particularly if an old repair changed its appearance. Joe’s 1963 Princeton provides a photographed example of that family. An owner’s description such as “brown Fender practice amp” is a useful starting clue, but it leaves the originality and exact identity unresolved.']]),paras('Cabinet condition can be especially easy to underdescribe on a small amp. Show both side panels, the handle mounting area and the bottom. A replacement back panel or baffle may be unobtrusive in a front photograph. If the cabinet has been re-covered, say so and include any older images that show it before the work.','Don’t assume a newer component makes the whole amp newer. A speaker or transformer can be replaced during service while the cabinet and chassis retain their vintage identity. The appraisal needs to distinguish those parts. The reverse also applies: an old speaker placed in a new cabinet doesn’t establish that the complete amplifier is an original Princeton.')]),
{type:'photo-band',photos:[ph.brownFront,ph.princetonFront],quote:'1963 Fender Princeton And 1966 Fender Princeton Reverb'},
section('reverb-values','How The Reverb Model Changes The Comparison','Controls And Completeness',[paras(`The blackface Princeton Reverb row is ${price('princeton','Blackface','Princeton Reverb')}. That range shouldn’t be applied to a blackface non-reverb Princeton just because the cabinets look related. Confirm the model name, control layout and reverb equipment. If the front panel has been changed, a technician’s inspection may be needed to establish what chassis is underneath it.`, 'Silverface Princeton Reverbs have their own entries, including the listed logo distinctions. Describe the existing logo and grille, but remember that both can be replaced. Date evidence from the chart and components should support a narrower period claim. An attractive reproduction logo doesn’t restore the originality of an amp that lost its factory one.','A working reverb system needs a separate condition description from the speaker and power section. Photograph the tank label, cables and footswitch where present. If reverb is intermittent or absent, include that information before seeking an offer. A repair estimate can then be discussed as part of the actual condition rather than appearing after the amplifier arrives.','The non-reverb Princeton’s value shouldn’t be presented as a defective Princeton Reverb value. It’s a separate model with its own features. For a player choosing between models, the absence of built-in reverb may be a preference question. For an appraisal, it first determines which original configuration and chart entry are being assessed.')]),
section('originality','Original Parts In A Compact Amp','What To Document',[columns([
['The Speaker And Baffle','A larger replacement speaker or a cut baffle changes the condition record. Show the mounting arrangement and any new screw holes. If the original baffle or speaker was retained, include those parts in separate photos. A reversible alteration still needs disclosure while it remains installed, and the ability to restore an amp should be evaluated rather than assumed.'],
['Transformers And Wiring','Record the transformer markings and known repairs. A modern replacement may have been selected to keep the amp in service, but a collector will still want to know what changed. Avoid treating all electrical work as one category. Replacing exhausted filter capacitors and replacing the output transformer raise different questions about originality and present operation.']]),paras('The paper tube chart can help tie the cabinet’s evidence to the model description. Photograph the whole label and its mounting surface. A torn or missing chart limits that evidence, though other component dates may still help. Don’t attach a reproduction label before requesting an appraisal; the original state is the useful record.','Cosmetic wear should be shown directly. Grille tears, stained covering, rust, missing feet and a replacement handle can all be documented without guessing a percentage deduction. A uniform discount applied to every worn Princeton ignores differences between versions and the extent of the damage. Joe needs to see what is actually affected.','Accessories complete the description. Include a surviving cover, manual, receipt or footswitch, while noting anything acquired later. Paperwork can connect an amplifier with earlier ownership, but it should be photographed alongside the amp’s own identifying details. A receipt for a Princeton doesn’t automatically establish that every component in the present cabinet dates from that purchase.')]),
dark('service-record','Describe Repairs Before Discussing A Sale','Operation And History',[paras('Write down what happens when the amplifier is used, if it is already known to be safe and working. Hum, a noisy control or a weak effect should be reported in ordinary language. You don’t need to diagnose the failed component yourself. An accurate symptom description is more useful than a confident but unsupported repair claim.','An amp that has sat unused should be evaluated by a qualified technician before it’s powered. For an initial appraisal, send exterior photographs and state that it hasn’t been tested. The technician can provide interior pictures as part of an inspection. Stored voltage makes chassis access unsuitable as a casual photography task.','Keep the distinction between a value estimate and a buying offer clear. The chart assumes a stated condition and configuration; an offer follows review of your amp. A clean exterior, a repair receipt and a working demonstration each supply different evidence. Together they help reduce uncertainty, but none replaces the rest of the inspection.','Before paying for cosmetic restoration, ask how the present condition affects the estimate. Cleaning away original markings or replacing an aged grille can remove information an appraiser needs. Collect the photographs first and preserve removed parts where practical. That leaves a better record for the next owner even when necessary service is carried out.')]),
section('appraisal','Princeton Appraisal Photo Checklist','Cabinet, Codes And Reverb Equipment',[list([
['Front View With Model Name','Frame the entire amp and take another photograph close enough to read the faceplate. Include every knob so the reverb and non-reverb layouts can be distinguished.'],
['Rear Panel And Speaker Opening','Show the back as a whole, including the speaker mount and any absent wood panels. Explain cabinet alterations that aren’t obvious from the front view.'],
['Paper Chart And Chassis Evidence','Send a legible image of the attached tube chart. Have internal chassis views taken by an amp technician, with the amplifier made safe for inspection.'],
['Transformer Identification','Keep the stamped characters sharp and include the surrounding component. A close-up without context can leave uncertainty about which transformer was photographed.'],
['Speaker Label And Frame Code','Capture both the label and the stamped frame markings. Note a recone, replacement speaker or changed baffle if any of those repairs is known.'],
['Tank Label, Footswitch And Cover','On a Princeton Reverb, include the reverb tank’s identification and associated accessories. Photograph a surviving cover and any old paperwork in the same submission.']]),paras(`For a readable two-letter chart stamp, use the ${a(dating+'#amp-decoder','Fender amp date decoder')}. Missing charts call for ${a(dating+'#tc-9','transformer and speaker evidence')}; readable control markings can be checked with the ${a('/fender-pot-codes/','pot-code reference')}. These details support the date more usefully than a chassis serial, which isn’t a dependable year lookup.`),cta('Get A Value For Your Princeton','Send Joe the model photographs and the repairs you know about. An uncertain date or missing label can be addressed during the review.')])],faqs:[{q:'Does A Princeton Reverb Have The Same Value As A Princeton?',a:'They have separate chart entries. Establish which model you own before comparing condition or applying an estimated range.'},{q:'What If My Princeton Has A Twelve-Inch Speaker?',a:'Document the speaker and baffle, and identify the model first. A speaker conversion or a modern version needs to be distinguished from an original vintage configuration.'},{q:'Can A Missing Tube Chart Be Worked Around?',a:'Other evidence may support the date. Send transformer and speaker markings with complete cabinet photographs, and disclose that the chart is missing.'}],closing:`<p>The ${a(link('princeton'),'Princeton and Princeton Reverb identification page')} covers the changes behind these value groups. The ${a(comparison,'vintage Princeton, Deluxe and Twin comparison')} can help if you’re also deciding which size suits your playing. For the amp in front of you, ${a('/free-appraisal/','send Joe a free appraisal request')} with clear photographs and the history you know.</p>`};

const fg=(slug:string)=>'https://mojotone.com/blogs/fender-field-guide/fender-'+slug;
const refs=(items:[string,string,string][]):GuideBlock=>({type:'sources',items:items.map(([title,href,note])=>({title,href,note}))});
const spec=(rows:string[][]):GuideBlock=>({type:'table',caption:'Documented Circuit Families And Visible Features',columns:['Version / Circuit','Output And Tubes','Rectifier / Speakers','Controls','Cabinet Details'],rows,note:'Ratings are nominal and depend on the documented version. 7025 is the low-noise 12AX7 family designation used on many original charts. Supply parts and transitional features require inspection of the individual amp.'});
const timeline=(items:[string,string,string][]):GuideBlock=>({type:'timeline',items:items.map(([date,title,html])=>({date,title,html:`<p>${html}</p>`}))});
const authBase=(family:string)=>({...defaults,slug:`fender-${family}-reverb-authentication-guide`,kind:'authentication' as const,closingTitle:'Identify The Amp Before Pricing It',faqSubtitle:'Fender Amp Identification',secondaryActions:[{label:'Read The Identification Checks',href:'#originality'},{label:'See Estimated Values',href:link(family,'value')}] as [{label:string;href:string},{label:string;href:string}]});

const twinAuth:ModelGuideData={...authBase('twin'),title:'Fender Twin And Twin Reverb Identification',seoTitle:'Fender Twin Reverb Guide: Blackface, Silverface And Dating',description:'Identify a vintage Fender Twin or Twin Reverb by its circuit, controls, speakers and date codes. Compare original amp photos and check reissue tells.',eyebrow:'Original Twin Family · 1952 Through 1980',dek:'Read the cabinet, circuit and component evidence together, from the first tweed Twins to the high-power silverface Twin Reverb.',hero:ph.blondeFront,glanceTitle:'Twin Identity At A Glance',glance:[['Period Covered','1952 through 1980'],['Nominal Output','25 watts initially; up to 135 watts'],['Speakers','Two twelve-inch speakers'],['Power Tubes','Two 6L6-family tubes early; four on later Twins']],intro:{html:`<p>Identify a Fender Twin by its generation before trying to date it. The tweed Twin, blonde Twin and Twin Reverb have distinct circuits and control layouts. The ${a(link('twin','value'),'Twin value guide')} prices those versions separately. Here, the photographs show what to inspect: model lettering, control arrangement, speaker complement, tube chart and transformer markings. A black or silver faceplate supplies a useful visual clue, while the chassis and dated parts establish a more complete description.</p>`,calloutTitle:'Serial Numbers Don’t Establish The Year',callout:'Fender amp serial numbers weren’t consistently sequential. Use the tube-chart stamp and original component dates, checked against the model’s physical features.'},sections:[
section('original-or-reissue','Original Or Reissue? Start At The Back','Modern Twins Can Look Familiar',[paras('The modern ’65 Twin Reverb uses PCB assemblies identified in Fender’s service manual. A technician can distinguish those boards from an original eyelet-board circuit. The ’68 Custom Twin Reverb has Custom and Vintage channel labels and two Celestion G12V-70 speakers in its standard configuration. Read the rear model identification and compare it with the correct Fender manual before treating the styling as age evidence. Modern production speakers and transformers need to be dated themselves; a period-looking label alone can’t authenticate the complete amp.','The ’57 Custom Twin-Amp is handwired and uses a tweed-covered pine cabinet with two twelve-inch Eminence speakers. That construction makes “handwired” an insufficient vintage test. Original and modern examples must be distinguished by the complete chassis, labels and component history. A technician can compare construction with the relevant factory drawing without relying on how old the covering looks.','A Tone Master Twin Reverb has digital electronics and rear features including a USB connection, balanced XLR output and selectable output power. Those controls identify a modern family immediately. It has no vintage tube complement to date. Later Twin designs, including the post-1980 redesigns, also fall outside this guide’s original-era coverage.'),{type:'callout',title:'Have Chassis Work Done By An Amp Technician',html:'<p>Stored electrical charge can remain after the amplifier is unplugged. Exterior photographs and rear labels are a safe starting point; leave internal inspection and component access to a qualified technician.</p>'}]),
section('timeline','Twin Changes From Tweed To High Power','Model History',[
timeline([
['1952 To 1959','Tweed Twin Development','Fender’s first Twin appeared in 1952. Wide-panel and narrow-panel cabinets accompanied several circuit revisions. The family progressed from the early 25-watt model through the 5E8-A and higher-powered 5F8-A designs. Those circuit names distinguish electrical versions that a front view alone can’t settle.'],
['1960 To 1963','Brown And Blonde Twin','The transitional Twin family moved into brown and blonde cosmetics. The 6G8 and 6G8-A circuits added the characteristic multi-control arrangement and tremolo, with four output tubes. Joe’s blonde 1963 example has white barrel knobs, a brown control panel and a 6G8-A paper chart.'],
['Late 1963','Twin Reverb Arrives','The blackface Twin Reverb introduced built-in spring reverb in the AB763 family. It has Normal and Vibrato channels, bright switches and separate tone controls. Its two-speaker format continued, while the reverb equipment and control layout distinguish it from the preceding blonde Twin.'],
['1967 To 1980','Silverface Changes In Stages','The silverface era begins in 1967. Early Twin Reverbs received a silver panel and aluminum grille surround before all electrical revisions occurred. Master volume arrived in 1972; subsequent versions added a pull function. The 135-watt ultralinear version followed in 1977. A late black-panel appearance requires component dating rather than an automatic earlier date.']])],'dark'),
section('specifications','Twin Circuit And Hardware Comparison','Match The Complete Configuration',[spec([
['Early Tweed / 5C8','About 25 W; two 6L6-family output tubes; three 6SC7 and one 6J5','5U4 rectifier; two 12-inch speakers','Normal and Bright volume; bass and treble','Tweed; wide panels; brown grille; chrome top panel; chicken-head knobs; leather handle'],
['Narrow Tweed / 5E8-A, 5F8-A','About 50 W, then 80 to 100 W; two then four 6L6-family output tubes. 5E8-A: three 12AY7 plus one 12AX7; 5F8-A: one 12AY7 plus two 12AX7','5E8-A: two 5U4; 5F8-A: GZ34; two 12-inch speakers','Two volumes; treble, bass, presence; later middle control','Narrow tweed panels; dark grille; chrome top panel; script badge; black chicken-head knobs; leather strap'],
['Blonde / 6G8, 6G8-A','80 to 100 W; four 6L6GC/5881; six 12AX7/7025-family small tubes','Solid-state rectifier; two 12-inch speakers','Normal and Vibrato channels; tone controls; speed, intensity, presence','Blonde covering; oxblood or wheat grille; brown panel; flat script logo; white barrel knobs; strap handle'],
['Blackface Twin Reverb / AB763','85 W; four 6L6GC; four 12AX7/7025 plus two 12AT7','Solid-state rectifier; two 12-inch speakers','Two channels with bright switches; reverb; speed and intensity','Black covering; silver grille; black panel and skirted knobs; raised logo; black strap; tilt-back legs'],
['Silverface Twin Reverb','100 W in later standard versions; 135 W ultralinear from 1977; four 6L6GC; six small tubes as above','Solid-state rectifier; two 12-inch speakers','Earlier layout; later master volume and pull function','Black covering; silver/blue grille with later variations; silver panel; skirted knobs; logo revisions; strap handle']]),paras('Use the circuit designation as a comparison target for a technician, not a promise that the amplifier still follows the drawing. Repairs can change individual parts, and modifications can alter the operating circuit. A paper chart can also remain in a cabinet after a chassis swap. Record the label, chassis and installed components as separate pieces of evidence.','The output rating is another place where labels can mislead. A rear-panel power-consumption figure describes electricity drawn from the wall, not the audio power delivered to the speakers. Read the model’s documented output specification. Don’t turn a consumption marking into an advertising claim about amplifier wattage.')]),
section('dating','Date A Twin With Chart And Component Evidence','Readable Marks From Joe’s Archive',[paras(`Joe’s ${a(dating+'#amp-decoder','Fender amp decoder')} reads the two-letter ink stamp used on tube charts until about 1970. The first letter gives the year beginning with A for 1951; the second gives the month. Keep the stamp separate from the printed circuit designation. The original chart should be photographed in place so its relationship to the cabinet remains visible.`, `When that paper is absent or the ink can’t be read, move to the ${a(dating+'#tc-9','transformer and speaker source-date section')}. Compare several original components instead of choosing the oldest number you can find. The ${a('/fender-pot-codes/','pot-code guide')} supplies another reference for control markings. A component may predate final assembly, and a replaced part dates only itself.`),{type:'serials',items:[{serial:'MC',title:'March 1963 Tube-Chart Stamp',html:'<p>The ink stamp on Joe’s blonde Twin reads MC. Its printed 6G8-A designation identifies the circuit family. The production number elsewhere on the chart is a separate marking and isn’t used as the date.</p>',photo:ph.blondeChart},{serial:'606248',title:'A Component Date On The Choke',html:`<p>The choke photograph shows 125C1A above 606248. The first is the part designation; the second is the source-date stamp. Read it with the ${a(dating+'#tc-9','component-code reference')} and compare it with the chart and the remaining transformers before assigning an assembly period.</p>`,photo:ph.blondeChoke}]}]),
section('originality','Twin Originality Inspection','Eleven Areas To Document',[list([
['Power Transformer, Output Transformer And Choke','Record all three components, their mounting hardware and the way their leads enter the chassis. A matching period stamp helps, but solder work and extra mounting holes can reveal a later installation. Ask the technician to distinguish a replacement from a retained factory part.'],
['The Speaker Pair','Inspect each speaker individually. Compare labels, frame stamps and cone evidence, and record any recone. A pair that looks alike from behind may have different service histories. Correct speaker type, period and installation all contribute to the assessment.'],
['Filter Capacitors And Other Components','Request an interior service record showing which capacitors, resistors and wires changed. New filter capacitors can be maintenance; extensive circuit alterations need their own explanation. Avoid describing a serviced board as untouched simply because the amp remains handwired.'],
['The Paper Tube Chart','Check the chart’s model wording, printed circuit and stamped date separately. Photograph tears, missing corners and its attachment. A reproduction chart can copy the appearance, so the paper must agree with the rest of the cabinet and chassis evidence.'],
['Cabinet And Covering','Look for recovered surfaces, repaired joints and replacement baffles. Compare outside seams with safely visible inside edges. Light blonde covering can show wear clearly, while an attractive replacement can conceal the cabinet’s earlier condition.'],
['Grille Cloth And Fender Logo','Record the cloth pattern, aluminum trim where appropriate and logo style. New grille material and reproduction logos are available, so cosmetic agreement needs supporting evidence. Note unused holes or a logo moved to a different position.'],
['Faceplate And Knobs','Read all control labels, including master-volume and pull markings. Check whether controls match the chassis function. A replaced faceplate can change the apparent era while leaving the electrical design underneath unchanged.'],
['Handle And Carrying Hardware','Photograph the strap, end brackets, tilt-back legs and added casters. Replacement carrying hardware should be listed without trying to make it look older. The cabinet around its screws may also show damage or an earlier mounting arrangement.'],
['Reverb Tank And Footswitch','On a Twin Reverb, inspect the tank label, bag, leads and footswitch. Identify replacements explicitly. The earlier Twin’s lack of built-in reverb is part of its design, so use the model-specific equipment list.'],
['Back Panels','Compare the panels with the cabinet, including covering, screw holes and wear. Missing or newly made panels affect completeness. A rear view should show the entire opening rather than only the speaker labels.'],
['The Original Cover','Keep a surviving cover with the amp and photograph it separately. Distinguish an old cover with documented history from a modern reproduction. Its fit alone doesn’t establish when it was made or which amp it originally accompanied.']])]),
section('archive','Twin Photo Timeline','Joe’s Amplifier Archive',[{type:'archive',items:[{label:'Blonde Twin',title:'1963 Fender Twin',html:'<p>The white covering, brown panel, barrel knobs and two-speaker rear opening identify the visible family. The chart and choke photographs provide additional evidence from this same amplifier. No single front photograph certifies the condition of its hidden electrical parts.</p>',photos:[ph.blondeFront,ph.blondeControls,ph.blondeBack]},{label:'Blackface Twin Reverb',title:'1966 Fender Twin Reverb',html:'<p>The later panel carries reverb controls and bright switches. The rear photograph shows both speakers and the footswitch. Use these views to plan photographs of your own amp, keeping any replaced components identified in the description.</p>',photos:[ph.twinFront,ph.twinControls,ph.twinBack]}]}],'archive'),
section('service','Separate Routine Service From Structural Changes','Preserve A Clear Repair Record',[paras(`Filter-capacitor replacement, tube replacement and power-cord work should be documented as service. Transformer replacement, reconing, recovering and cabinet substitution create additional originality questions. Their effect on an estimate belongs in the ${a(link('twin','value'),'Twin value guide')}. A working amp can contain significant replacements, and an original-looking amp can require substantial electrical attention.`, 'Retain repair invoices and photographs taken before a change. If parts were removed, label them with their location and the reason for removal. A retained failed component is useful historical evidence, but it shouldn’t be put back into operation for appearance’s sake. Ask a qualified technician to assess the current circuit and electrical safety.'),cta('Have Joe Review Your Twin','Send the exterior, chart and component photographs with the repair history. Include uncertainties so the review can address them directly.')]),
section('references','Twin Technical References','Factory Records And Documented Examples',[refs([
['Fender 5C8 Factory Schematic','https://www.prowessamplifiers.com/schematics/fender/twin_5c8_schem.pdf','Original tube complement and early circuit layout.'],['Fender 5E8-A Factory Drawing','https://cdn.shopify.com/s/files/1/0604/9615/0624/files/Fender-Twin-5E8A-Schematic.pdf?v=1759173642','Low-power narrow-panel tube layout.'],['Fender 5F8-A Factory Drawing','https://el34world.com/charts/Schematics/Files/Fender/Fender_twin_5f8a.pdf','High-power narrow-panel tube layout.'],['Fender ’65 Twin Reverb Service Manual','https://schematicheaven.net/fenderamps/65_twin_reverb_%20manual.pdf','Factory PCB assembly details.'],['Fender ’68 Custom Twin Reverb','https://www.fender.com/products/68-custom-twin-reverb','Custom and Vintage labels and Celestion speaker identification.'],['Fender’s Twin History','https://www.fender.com/articles/behind-the-scenes/pristine-cleans-aggressive-overdrive-the-fender-twin-story','Model introductions, control changes, master volume and high-power development.'],['Blonde Twin Field Guide',fg('blonde-twin'),'6G8-family configuration, hardware and component references.'],['Blackface Twin Reverb',fg('blackface-twin-reverb'),'AB763 specification and physical features.'],['Silverface Twin Reverb',fg('silverface-twin-reverb'),'Later output and control variants.'],['Fender ’57 Custom Twin-Amp','https://www.fender.com/products/57-custom-twin-amp','Modern handwired model, pine cabinet and Eminence speakers.'],['Fender ’65 Twin Reverb Manual','https://www.fmicassets.com/Damroot/Original/10001/021730_gamp_manual_all_revE.pdf','Modern reissue identification, controls, tube complement and service safety.'],['Fender Tone Master Twin Reverb','https://www.fender.com/products/tone-master-twin-reverb','Digital architecture and modern rear-panel connections.']])])],faqs:[{q:'Can A Silverface Twin Reverb Have An AB763 Circuit?',a:'Early silverface examples can retain the earlier circuit. Cosmetic changes and electrical revisions didn’t all occur together. Confirm the actual chassis rather than assigning a circuit from the grille surround.'},{q:'Does A Master Volume Prove The Amp Was Modified?',a:'No. Fender introduced factory master-volume Twin Reverbs during the silverface period. Compare the control, faceplate and circuit with the correct version before calling it an added modification.'},{q:'Does Handwired Mean An Original Tweed Twin?',a:'No. Fender has produced handwired recreations. Modern model identification and component evidence must be checked alongside construction.'},{q:'Can I Date A Twin From Its Chassis Serial?',a:'Fender amp serial numbers aren’t reliable for finding the year. Use the tube-chart date stamp, original component codes and model features together.'}],closing:`<p>Describe the Twin’s generation, document its date evidence and list its repairs. Then use the ${a(link('twin','value'),'Twin value chart')} for the matching version. The ${a(era,'Fender era guide')} gives the broader visual context, and the ${a(comparison,'Princeton, Deluxe and Twin comparison')} explains their different playing roles.</p>`};

const deluxeAuth:ModelGuideData={...authBase('deluxe'),title:'Identify A Vintage Fender Deluxe Or Deluxe Reverb',seoTitle:'Fender Deluxe Reverb Identification: Tweed To Silverface',description:'Identify Fender Deluxe and Deluxe Reverb amps through 1980. Check 5E3, brownface and blackface features, reissues, date evidence and original parts.',eyebrow:'Deluxe Family · Tweed Through 1980',dek:'The Deluxe name spans several circuits. Start with the controls, then compare the cabinet, tube chart and installed components.',hero:ph.deluxeFront,glanceTitle:'Deluxe Identification',glance:[['Family Coverage','Tweed Deluxe through 1980 Deluxe Reverb'],['Typical Output','About 12 to 22 watts across these versions'],['Speaker Format','One twelve-inch speaker'],['Output Tubes','A pair of 6V6-family tubes']],intro:{html:`<p>A vintage Deluxe identification begins with one question: which Deluxe circuit is in the cabinet? The tweed 5E3, brown 6G3, blackface Deluxe and Deluxe Reverb differ in controls and electrical design. Their estimates appear in the ${a(link('deluxe','value'),'Deluxe value guide')}. This page works through the evidence behind that choice. Joe’s 1957 Deluxe, 1967 Deluxe Reverb and 1979 silverface example show the tweed, blackface and later silverface designs.</p>`,calloutTitle:'Read The Full Model Name',callout:'The blackface Deluxe without reverb is a separate model. Its missing reverb control is expected, and it shouldn’t be authenticated against a Deluxe Reverb equipment list.'},sections:[
section('original-or-reissue','Original Or Reissue? Check Construction And Labels','Modern Deluxe Families',[columns([
['’65 And ’68 Reverb Reissues','Fender’s ’65 Deluxe Reverb service documentation identifies printed-circuit-board assemblies. A technician can distinguish that construction from the original eyelet-board layout. The ’68 Custom uses Custom and Vintage channel labels and a Celestion G12V-70 speaker in its standard specification. Read those labels and the rear identification before dating an amp by a silver panel or aluminum trim.'],
['Handwired Recreations And Tone Master','The ’57 Custom Deluxe is a modern handwired tweed model, while the ’64 Custom Deluxe Reverb has handwired circuitry and effects on both channels. The ’64’s Normal and Bright channel names help distinguish that version. Tone Master Deluxe Reverbs use digital electronics and have modern rear connections, including USB and XLR. None of those families belongs in an original-era value row.']]),paras('The newer ’62 Deluxe also recreates a brownface appearance. Fender identifies that model as a 20-watt design with a twelve-inch Celestion speaker. Compare the full product identification and present parts with the original 6G3 specification. A brown panel and a vintage-style handle by themselves don’t establish 1960s production.','A modern speaker alone doesn’t prove the entire amplifier is a reissue: it may be a replacement in an old chassis. Conversely, a period speaker doesn’t authenticate the cabinet around it. Check the evidence as a group. For internal board inspection, use a qualified amp technician; dangerous charge can remain inside an unplugged amplifier.')]),
section('timeline','Deluxe Model Changes In Sequence','Cabinets And Circuit Families',[timeline([
['1948 To 1959','The Tweed Era','Tweed is the broad era label here for 1948 to 1959. Within the Deluxe family, TV-front and wide-panel cabinets preceded the narrow-panel 5E3. Model-specific records carry narrow-panel Deluxe production into 1960. That continuation is an exception within the model history, rather than a different boundary for the overall Fender era.'],
['1961 To 1963','Brown Deluxe 6G3','The brown Deluxe introduced a front-facing control panel and tremolo. Its two channels each have volume and tone controls, with speed and intensity for the effect. Brown covering, a brown panel and barrel knobs give the version a different visible identity from the preceding tweed cabinet.'],
['1963 To 1967','Blackface Deluxe And Deluxe Reverb','The blackface era includes both the Deluxe without reverb and the Deluxe Reverb. The AB763 Deluxe Reverb adds the reverb system and associated controls. Identify the model lettering before using the number of knobs or the cabinet’s appearance to make further comparisons.'],
['1967 To 1980','Silverface Deluxe Reverb','The silverface era brought a silver control panel and, early in the transition, aluminum grille trim. Later Deluxe Reverbs received a pull-boost feature. The model remained a two-6V6, single-twelve-inch combo; the Twin’s ultralinear power changes shouldn’t be assigned to the Deluxe. A black-panel return at the end of this period needs careful dating.']])],'dark'),
section('specifications','Deluxe Specifications By Circuit','Output, Tubes And Cosmetics',[spec([
['Tweed / 5E3','About 12 to 15 W in published ratings; two 6V6GT; one 12AY7 and one 12AX7','5Y3GT; one 12-inch Jensen P12R/P12Q among documented speakers','Instrument volume, microphone volume, shared tone','Narrow tweed panels; brown/oxblood grille; chrome top panel; small script badge; chicken-head knobs; leather handle'],
['Brown / 6G3','About 15 W; two 6V6GT; one 7025 and two 12AX7','GZ34; one 12-inch speaker, including Oxford 12K5','Two volume/tone channels; speed and intensity','Brown covering and faceplate; wheat grille; raised script logo; brown barrel knobs; leather strap'],
['Blackface Deluxe / AA763, AB763','22 W; two 6V6GT; three 12AX7/7025 and one 12AT7','GZ34; one 12-inch speaker','Normal and Vibrato channels; volume, treble, bass; speed and intensity','Black covering and panel; silver grille; skirted black knobs; logo details require model inspection; black strap'],
['Blackface Deluxe Reverb / AB763','22 W; two 6V6GT; four 12AX7/7025 and two 12AT7','GZ34; one 12-inch speaker, including Oxford 12K5','Normal volume/treble/bass; Vibrato channel adds reverb, speed, intensity','Black covering; silver grille; black panel and skirted knobs; raised Fender logo; black strap'],
['Silverface Deluxe Reverb / AA1270, AA1172','22 W; two 6V6GT; four 12AX7/7025 and two 12AT7','5U4GB on later examples; GZ34 on earlier versions; one 12-inch speaker','Reverb and tremolo layout; later pull boost','Black covering; silver/blue and later grille variations; silver panel; black skirted knobs; logo and trim changes']]),paras('The 5E3 is the narrow-panel circuit designation most owners encounter, but it doesn’t describe every tweed Deluxe ever built. Earlier Deluxes require their own schematic comparison. Treat a chart or seller’s circuit claim as a starting identification, then have the installed wiring checked if originality is uncertain.','Tube brands can change through ordinary service. The useful first check is the documented tube function and complement for that circuit, followed by the installed parts and repair record. This table isn’t an instruction to substitute rectifiers or output tubes. A technician should decide whether the present circuit and operating conditions are appropriate for the components fitted.')]),
section('five-e-three','Identify A 5E3 Without Relying On Tweed','The Panel And Chassis Together',[paras('A 5E3 presents a compact top control panel with two volume controls and one tone control. It has separate instrument and microphone input groups and no built-in reverb or tremolo. Those visible features narrow the family, but modern kits can reproduce them. A convincing identification requires the cabinet, chassis, board construction and dated components to agree.','Joe’s 1957 example retains a printed 5E3 chart. The photograph establishes that printed marking clearly. It doesn’t supply a readable two-letter production-date stamp, so this guide doesn’t decode one from that image. Keeping that limitation explicit is more useful than assigning a month from a blurred pencil mark.','The interior photograph also shows why “all original” needs a detailed inspection. Service parts are visible on the board. A technician’s report can establish what was changed and whether the wiring still follows the intended circuit. The name 5E3 describes a design; it doesn’t certify the age or originality of every component attached to it.'),{type:'serials',items:[{serial:'5E3',title:'A Circuit Code, With No Date Inferred',html:'<p>This printed designation is legible on Joe’s Deluxe tube chart. The photograph doesn’t support a complete date-stamp reading. The archive identifies the amp as a 1957 Deluxe, and that archive year is kept separate from what can be read from this label.</p>',photo:ph.tweedChart}]}]),
section('dating','Find The Date Evidence On A Deluxe','Charts, Transformers And Speakers',[paras(`A legible ink stamp on the original tube chart can be checked with Joe’s ${a(dating+'#amp-decoder','amp date decoder')}. That two-letter system begins with A for 1951 and was used until about 1970. The printed 5E3 or AB763 circuit designation and any handwritten production number are different kinds of marks. Keep them separate when sending photographs.`, `For a missing or damaged chart, follow the ${a(dating+'#tc-9','transformer and speaker source-date guidance')}. Look for agreement among components that appear original, with allowance for parts made before final assembly. The ${a('/fender-pot-codes/','pot-code page')} explains control markings. Fender amp serial numbers aren’t a useful year-finding system, even when a chassis number is clearly stamped.`, 'A cabinet and chassis assembled from different amplifiers can produce conflicting dates. Document the conflict rather than averaging the numbers into a guessed year. Original mounting holes, chart placement, transformer installation and repair records can help a technician decide which evidence belongs together. Ask for additional photographs if a seller supplies only a serial close-up.')]),
section('originality','Deluxe Originality Checklist','Inspect The Model You Have',[list([
['Transformers And Any Circuit-Specific Choke','Identify the power and output transformers, plus the choke when that circuit uses one. Photograph stamps and mounting changes. Don’t mark a 5E3 incomplete for lacking a component that isn’t part of its original circuit.'],
['Speaker Frame And Cone','Compare the speaker with the documented model and period. Record reconing separately from replacement of the complete speaker. The label, frame and cone each provide evidence, and they may have different histories.'],
['Capacitors, Resistors And Wiring','Have the circuit inspected for maintenance and modifications. Identify replaced filter capacitors, changed signal components and altered wiring in the report. The condition of old electrolytics is an electrical service question.'],
['Tube Chart And Printed Model','Read the entire chart and photograph its edges. Check that its model designation agrees with the chassis. A new label or a transplanted chassis requires a different explanation from a worn original chart.'],
['Cabinet, Baffle And Covering','Look inside accessible openings for repairs, additional speaker holes and replaced wood. Show recovered areas and seams. An original chassis in a new cabinet should be described with both facts included.'],
['Grille Pattern, Trim And Badge','Note replaced cloth, loose aluminum trim and a changed logo. These visible parts can be renewed without changing the chassis, so they can’t independently settle the amp’s age.'],
['Faceplate And Control Knobs','Check lettering, knob style and the actual functions. A Deluxe Reverb has a different control arrangement from the non-reverb Deluxe. Added switches or a mismatched faceplate deserve closer chassis inspection.'],
['Handle And Its Mounts','Inspect the strap and the cabinet around each bracket. A later handle is a replacement to disclose; enlarged holes or repairs beneath it may also affect the cabinet assessment.'],
['Tank, Cables And Footswitch','For a Deluxe Reverb, photograph the tank identification and the effect-switching accessories. Earlier Deluxes lack built-in reverb. Judge completeness against the correct model’s equipment.'],
['Rear Wood Panels','Confirm whether both expected panels survive and whether their material and wear match the cabinet. A replacement panel is easy to overlook if all photographs concentrate on the front grille.'],
['Cover And Retained Paperwork','Keep the cover, manual and repair records with the amplifier. Identify reproduction accessories as such. Earlier ownership photographs may show the amp before a cosmetic or electrical change.']])]),
section('archive','Deluxe Photo Timeline','Three Amps From Joe’s Archive',[{type:'archive',items:[{label:'Narrow-Panel Tweed',title:'1957 Fender Deluxe',html:'<p>The compact top panel, tweed cabinet and paper 5E3 chart show this version’s visible identity. The board photograph is included as condition evidence, with visible service parts, rather than as a claim that the circuit remains untouched.</p>',photos:[ph.tweedFront,ph.tweedControls,ph.tweedBoard]},{label:'Blackface Reverb',title:'1967 Fender Deluxe Reverb',html:'<p>The black control panel names the reverb model. Its rear view shows a single speaker and the cabinet opening. Compare the full control layout before assigning a similar-looking non-reverb Deluxe to this family.</p>',photos:[ph.deluxeFront,ph.deluxeBack]},{label:'Later Silverface',title:'1979 Fender Deluxe Reverb',html:'<p>The silver panel, blue model lettering and later cosmetic details can be compared with the blackface example above. These archive photographs identify the amp and its appearance; hidden component originality needs its own inspection.</p>',photos:[ph.silverFront,ph.silverControls,ph.silverBack]}]}],'archive'),
section('repairs','Record Service And Value-Changing Replacements','Keep The Inspection Useful',[paras(`Routine work can include filters, worn tubes and electrical safety repairs. Keep those repairs distinct from a changed transformer, replacement speaker, altered cabinet or recovering. The ${a(link('deluxe','value'),'Deluxe value page')} addresses how condition enters an appraisal. No fixed deduction here can replace inspection of the particular version.`, 'Ask for a written list of changes when an amp is serviced. A vague claim that it was “gone through” leaves the next owner unsure whether the work involved a few worn components or a different circuit. Preserve removed parts and photographs when practical, while keeping unsafe parts out of operation.'),cta('Send The Deluxe Evidence For Review','Include the full amp, chart, speaker and transformer photographs. Tell Joe what has been repaired and what is still uncertain.')]),
section('references','Deluxe Sources And Factory Documents','Technical References',[refs([
['Narrow-Panel Deluxe',fg('narrow-panel-tweed-deluxe'),'5E3 controls, speaker family, cosmetics and schematic link.'],['Brown Deluxe',fg('brownface-deluxe'),'6G3 specifications and cabinet features.'],['Blackface Deluxe',fg('blackface-deluxe'),'Non-reverb configuration and tube layout.'],['Blackface Deluxe Reverb',fg('blackface-deluxe-reverb'),'AB763 output, controls and hardware.'],['Silverface Deluxe Reverb',fg('silverface-deluxe-reverb'),'Rectifier, pull-boost and cosmetic revisions.'],['Fender ’65 Deluxe Reverb Service Manual','https://el34world.com/charts/Schematics/files/Fender/Fender_65_deluxe_reverb_reissue_sm.pdf','Factory printed-circuit-board documentation for reissue identification.'],['Fender ’57 Custom Deluxe','https://www.fender.com/products/57-custom-deluxe','Modern handwired tweed construction.'],['Fender ’64 Custom Deluxe Reverb','https://www.fender.com/products/64-custom-deluxe-reverb','Modern handwired model, channel names and effects on both channels.'],['Fender ’68 Custom Series Announcement','https://www.fender.com/newsroom/271377-fender-releases-68-custom-series-amplifiers/','Custom/Vintage channels and Celestion speaker specification.'],['Fender’s 2026 Model Announcement','https://www.fender.com/newsroom/270122-from-vintage-purists-to-down-tuned-strummers-fender-s-mid-year-drop-leaves-no-player-behind/','The modern ’62 Deluxe and its stated output and speaker.'],['Tone Master Deluxe Reverb','https://www.fender.com/products/tone-master-deluxe-reverb','Digital model and rear-panel features.']])])],faqs:[{q:'Does 5E3 Give The Year My Deluxe Was Built?',a:'It identifies a circuit design. Use a readable tube-chart date stamp or original component dates for production evidence, and check that the cabinet and chassis belong together.'},{q:'Did Fender Make A Blackface Deluxe Without Reverb?',a:'Yes. The non-reverb Deluxe is a separate model with its own control arrangement and equipment. It should be identified before comparing it with a Deluxe Reverb.'},{q:'Does A Silver Panel Mean The Deluxe Has The Twin’s High-Power Circuit?',a:'No. Changes to one Fender model shouldn’t be transferred to another from appearance alone. The Deluxe Reverb remained a different two-6V6, single-speaker design.'},{q:'Are New Filter Capacitors Evidence Of A Fake Amp?',a:'No. They can be ordinary service replacements. Document the work and assess the cabinet, chassis and remaining components separately.'}],closing:`<p>Match the Deluxe’s circuit family and controls, then reconcile the dates and repairs. The ${a(link('deluxe','value'),'Deluxe price guide')} provides the corresponding estimates. Read the ${a(era,'Fender era article')} for cosmetic context or the ${a(comparison,'Princeton, Deluxe and Twin comparison')} for a practical size and output comparison.</p>`};

const princetonAuth:ModelGuideData={...authBase('princeton'),title:'Fender Princeton And Princeton Reverb Identification',seoTitle:'Fender Princeton Reverb Guide: Identify And Date Your Amp',description:'Date and identify vintage Princeton and Princeton Reverb amps with tube-chart photos, circuit and speaker details, reissue checks and repair notes.',eyebrow:'Tweed Princeton To Silverface · Through 1980',dek:'A small tweed Princeton, a brown 6G2 and a Princeton Reverb need different identification checks. Follow the actual model and its date evidence.',hero:ph.princetonFront,glanceTitle:'Princeton Family Details',glance:[['Scope','Tweed models through 1980'],['Nominal Output','About 4 W tweed; 12 W later versions'],['Speaker','One 8-inch tweed; one 10-inch later'],['Output Tubes','One 6V6 in tweed; two in brown and reverb models']],intro:{html:`<p>The vintage Princeton family includes a small single-output-tube tweed amp, a larger brownface design with tremolo, and separate Princeton and Princeton Reverb models. Identify those differences before applying the ${a(link('princeton','value'),'Princeton value ranges')}. The front controls supply a quick first distinction; the chart, chassis and component dates refine it. Joe’s brown 1963 Princeton and blackface 1966 Princeton Reverb provide photographed examples, including readable tube-chart stamps from both amplifiers.</p>`,calloutTitle:'A Printed Year Can Name A Reissue',callout:'The ’65, ’68, ’64 Custom and ’62 signature names refer to modern model families. Read the full identification and construction evidence before treating a year in the name as a build date.'},sections:[
section('original-or-reissue','Original Or Reissue? Princeton Checks','Look Beyond The Black Or Brown Covering',[paras('The ’65 Princeton Reverb reissue uses a printed circuit board documented in Fender’s service drawing. A qualified technician can compare it with an original eyelet-board layout. Rear model identification and modern component dates provide additional evidence. A replaced modern speaker in an older amp must be distinguished from a complete modern reissue.','The ’68 Custom Princeton Reverb recreates early silverface styling, including the bright aluminum surround. Its standard Celestion TEN 30 speaker and modern model identification belong to that reissue specification. The surround alone doesn’t establish an original 1968 amplifier. Ask for the rear labels before making an age claim from a front photograph.','The ’64 Custom Princeton Reverb is a modern handwired model, so hand wiring by itself can’t prove 1960s manufacture. Fender’s ’62 Princeton Chris Stapleton Edition is another modern handwired recreation, with a twelve-inch Eminence speaker instead of the original brown Princeton’s ten-inch format. Those are useful physical distinctions, checked together with the complete model labeling.','Tone Master Princeton Reverbs are digital models with a rear USB port, XLR output and selectable power settings. The connections provide quick exclusion evidence for an original tube amp. Post-1980 Princeton redesigns also sit outside this guide. Keep those later products separate from the vintage circuits below, even when the Princeton name appears on both.')]),
section('timeline','How The Princeton Family Developed','Tweed, Brown And Reverb Circuits',[timeline([
['1948 To 1959','The Tweed Era And Small Princeton','The tweed era covers 1948 to 1959. The Princeton passed through TV-front, wide-panel and narrow-panel cabinets, with a single output tube and a small speaker. The narrow-panel 5F2-A is a distinct circuit with volume and tone controls. Model-specific price records include later tweed examples, so the broad era dates aren’t a substitute for individual identification.'],
['1961 To 1963','Brownface 6G2 Princeton','The brown 6G2 uses a pair of 6V6 output tubes, a ten-inch speaker and tremolo. Its four controls are volume, tone, speed and intensity. Joe’s brown Princeton shows that arrangement and the later date evidence discussed below. The larger circuit is a substantial change from the small tweed design.'],
['1963 To 1964','Transitional Black 6G2','Early black-covered Princetons can retain the 6G2 circuit and white barrel knobs. This transitional appearance is often called tuxedo styling. A black cabinet therefore doesn’t automatically establish the later treble-and-bass-control circuit. Read the controls and chart together.'],
['1964 To 1967','AA964 Princeton And Princeton Reverb','The later non-reverb Princeton has separate treble and bass controls. The Princeton Reverb adds reverb and uses its own expanded tube complement. The AA1164 schematic is a reference for that reverb circuit; printed tube-chart designations can differ, as Joe’s AA764-labeled example demonstrates.'],
['1967 To 1980','Silverface Appearance And Later Controls','Within the silverface era, the Princeton families adopted silver panels and early aluminum grille trim. Trim, grille and logo details changed over time. Later versions added a pull-boost function, and a black-panel return appears near the end of this scope. Reverb and non-reverb variants still need separate identification.']])],'dark'),
section('specifications','Princeton Specifications By Version','Small Amps With Different Circuits',[spec([
['Narrow Tweed / 5E2, 5F2, 5F2-A','About 4 W; one 6V6GT; one 12AX7','5Y3GT; one 8-inch speaker','Volume and tone; switch layout varies','Tweed; oxblood/gold grille; chrome top panel; script badge; black chicken-head knobs; leather handle'],
['Brown / 6G2','About 12 W; two 6V6GT; one 7025 and one 12AX7','5Y3GT; one 10-inch speaker','Volume, tone, speed and intensity','Brown covering and panel; wheat grille; brown barrel knobs; script logo; leather strap'],
['Transitional Black / 6G2','About 12 W; two 6V6GT; two 12AX7/7025-family small tubes','5Y3GT; one 10-inch speaker','Volume and tone; tremolo speed and intensity','Black covering and panel; light grille; white barrel knobs; transitional trim'],
['Blackface Princeton / AA964','About 12 W; two 6V6GT; two 12AX7/7025-family small tubes','GZ34; one 10-inch speaker','Volume, treble, bass, speed and intensity','Black covering; silver grille; black skirted knobs; early examples without grille logo; later raised logo'],
['Blackface Princeton Reverb / AA1164 Reference','12 W; two 6V6GT; three 12AX7/7025 and one 12AT7','GZ34; one 10-inch speaker','Volume, treble, bass, reverb, speed and intensity','Black covering and faceplate; silver grille; raised logo; black skirted knobs and strap'],
['Silverface Princeton Without Reverb / AA964 And Later Revisions','12 W; two 6V6GT; two 12AX7/7025-family small tubes','Early GZ34 or later 5U4GB; one 10-inch speaker','Volume, treble, bass, speed and intensity; later pull boost','Black covering; silver panel; blue/silver grille; early aluminum surround; black skirted knobs and strap'],
['Silverface Princeton Reverb','12 W; two 6V6GT; three 12AX7/7025 and one 12AT7','Earlier GZ34, later 5U4GB; one 10-inch speaker','Six-control reverb layout; later pull boost','Black covering; silver panel; blue/silver grille and later variants; early aluminum trim; black knobs and strap']]),paras('Early TV-front and wide-panel Princetons predate the narrow-panel circuit shown here. Identify their specific chassis before using a later schematic as a reference. The small speaker and single output tube distinguish the broad tweed family from the later push-pull designs, but they don’t settle every circuit revision.','A twelve-inch speaker in a vintage Princeton cabinet needs an explanation. It can indicate a conversion involving the baffle, while a modern signature model can use that size by design. Photograph the cabinet opening and speaker mount. Don’t infer a rare factory version from speaker diameter without supporting records.')]),
section('date-cards','Read The Chart Stamp Separately From The Circuit','Two Photographed Date Examples',[paras(`The ${a(dating+'#amp-decoder','Fender amp tube-chart decoder')} uses the two-letter ink stamp, with A representing 1951 in the year position. That system continued until about 1970 in Joe’s dating reference. Read the month letter carefully and preserve a full-resolution image. A printed circuit number and a handwritten production count should be recorded separately.`, 'The chart in Joe’s blackface Princeton Reverb is particularly useful because it contains both kinds of evidence. PE is the date stamp; AA764 is printed as the model designation. The printed designation doesn’t change the meaning of the ink stamp. A circuit inspection can compare the actual wiring with the appropriate schematic rather than assuming the paper gives a complete electrical description.'),{type:'serials',items:[{serial:'ML',title:'December 1963 On The Brown Princeton',html:'<p>The two-letter ink stamp reads ML on this chart. M is 1963 and L is December in the decoder. The production notation higher on the label is kept separate. The surrounding cabinet and components still need to support the date.</p>',photo:ph.brownChart},{serial:'PE',title:'May 1966 On The Princeton Reverb',html:'<p>P identifies 1966 and E identifies May. The chart also prints AA764 and a power-consumption figure. Neither of those is the date stamp, and wall-power consumption isn’t the amp’s audio output rating.</p>',photo:ph.princetonChart}]}]),
section('missing-chart','Dating A Princeton With Missing Paperwork','Cross-Check Original Components',[paras(`A missing chart shifts the investigation to the components and physical model. Joe’s ${a(dating+'#tc-9','transformer and speaker source-date reference')} explains those markings. Use the ${a('/fender-pot-codes/','pot-code guide')} for control codes where a technician can access them. Fender amp serial numbers aren’t dependable year indicators and shouldn’t override contradictory evidence from original parts.`, 'Take the latest credible original component date into account while allowing for stock that was made earlier and fitted later. A replacement speaker may be newer than the amplifier; an old spare installed later may be older. Identify originality before treating either code as a build boundary. This is why a collection of sharp photographs is more useful than one isolated stamp.','If the cabinet’s chart and the chassis evidence disagree, preserve the discrepancy. A chassis swap, replacement part or misread letter may explain it. A month should remain uncertain when the available ink is unclear. Don’t retouch a photograph or reconstruct a missing letter to make the date fit the preferred model year.')]),
section('originality','Princeton Parts And Cabinet Checklist','Document Each Area',[list([
['Power And Output Transformers, Plus Any Choke','Match the transformer set to the specific circuit. The 5F2-A omits the choke used in preceding narrow-panel versions, and the later Princeton circuits have their own layouts. Record actual parts and mounting evidence before calling anything missing.'],
['Speaker Type, Size And Cone','Photograph the complete speaker and its stamps. Check for reconing and baffle changes, particularly a conversion to a larger speaker. A vintage frame doesn’t by itself establish an untouched cone or original installation.'],
['Filter Capacitors And Signal Components','Ask the technician to list replaced parts and circuit alterations. A new capacitor can be necessary upkeep, while a changed circuit requires an additional description. Keep that record with the amplifier.'],
['Tube Chart And Its Attachment','Capture the model printing and ink stamp in separate close views, with one wider photograph showing the chart in place. Record missing paper or unclear letters without attempting to complete the code from expectation.'],
['Cabinet Wood And Covering','Examine repairs, seams and safely visible inner surfaces. Replacement cabinets and recovered originals need distinct descriptions. Photograph any added speaker cutout or altered baffle even when the front grille hides it.'],
['Grille, Trim And Logo','Check the material pattern, aluminum surround where present and grille-logo arrangement. Some non-reverb blackface Princetons had no grille logo. Compare the correct version before treating an empty grille as a missing part.'],
['Control Panel And Knobs','Count the controls and read their labels. The brown and transitional 6G2 use a single tone control; later versions have treble and bass. Added holes and mismatched knobs deserve a closer look.'],
['Handle And Brackets','Inspect the carrying strap and mounting points. A newer handle may be a practical replacement, but the installation and any repaired wood should be disclosed. Don’t judge cabinet condition solely from the grille view.'],
['Reverb Tank And Switching','The Princeton Reverb should be assessed with its tank, leads and footswitch. A non-reverb Princeton has a different equipment list. Identify replacement reverb parts and any operating fault separately.'],
['Back Panels And Screws','Document the complete rear enclosure. A replaced panel or missing section can affect both appearance and completeness. Compare material and wear without assuming that every old-looking screw is factory installed.'],
['Cover And Accompanying Records','Photograph a surviving cover, purchase paperwork and service receipts. Mark later accessories clearly. Documents are most useful when their identifying details can be connected to the amplifier being examined.']])]),
section('archive','Princeton Photo Timeline','Brownface And Blackface Examples',[{type:'archive',items:[{label:'Brown 6G2 Family',title:'1963 Fender Princeton',html:'<p>The front photograph shows the brown cosmetics and four-control layout. The rear view supplies the speaker and cabinet context for the chart photographed above. This is a non-reverb Princeton, so it should be compared with that model’s specification.</p>',photos:[ph.brownFront,ph.brownBack,ph.brownSpeaker]},{label:'Blackface With Reverb',title:'1966 Fender Princeton Reverb',html:'<p>The six front controls include reverb, and the rear view shows the single-speaker format. Its paper chart carries the readable PE stamp. These views show the cabinet, controls and chart; internal originality requires chassis photographs.</p>',photos:[ph.princetonFront,ph.princetonControls,ph.princetonBack]}]}],'archive'),
section('service','Preserve The Princeton’s Service History','Maintenance And Originality',[paras(`A serviced amplifier can still retain much of its original construction. Document filter replacement, tubes and power-cord work, then separately identify changes to transformers, speakers, baffles or covering. The ${a(link('princeton','value'),'Princeton value guide')} explains the condition questions behind an estimate. Keep the repair history specific enough that another person can understand the present configuration.`, 'Don’t open the chassis to obtain a code photograph without appropriate training. A qualified amp technician can make it safe and supply the necessary interior views. If the amp is untested, say so. Exterior photographs can begin the identification while electrical condition remains an open question.'),cta('Ask Joe To Review Your Princeton','Send the model view, tube chart and component photographs together. Include the history of any speaker, cabinet or circuit changes.')]),
section('references','Princeton Identification References','Documented Models And Reissues',[refs([
['Narrow-Panel Princeton',fg('narrow-panel-tweed-princeton'),'5E2, 5F2 and 5F2-A specifications and choke differences.'],['Brownface Princeton',fg('brownface-princeton'),'6G2 tubes, controls, speaker and cosmetics.'],['Blackface Princeton',fg('blackface-princeton'),'Transitional 6G2, AA964 and grille-logo differences.'],['Blackface Princeton Reverb',fg('blackface-princeton-reverb'),'Original reverb configuration.'],['Silverface Princeton Without Reverb',fg('silverface-princeton'),'Non-reverb controls, speaker, tubes and cosmetic revisions.'],['Silverface Princeton Reverb',fg('silverface-princeton-reverb'),'Later rectifier, control and cosmetic changes.'],['Original Princeton Schematics',fg('princeton-schematics'),'Factory circuit drawings, including 6G2 and AA1164.'],['Fender ’65 Princeton Reverb Service Drawing','https://www.gregcutshaw.com/Sweetwater%20Tweed%20Princeton%20Reverb/Fender-65-Princeton-Reverb-Schematic.pdf','Factory PCB assembly drawing for the reissue.'],['Fender ’68 Custom Series','https://www.fender.com/newsroom/271377-fender-releases-68-custom-series-amplifiers/','Modern Princeton specification and Celestion TEN 30 speaker.'],['Inside The ’64 Custom Princeton Reverb','https://www.fender.com/articles/parts-and-accessories/go-inside-the-64-custom-princeton-reverb','Modern handwired recreation.'],['Fender Chris Stapleton Princeton','https://www.fender.com/articles/parts-and-accessories/62-princeton-amp-chris-stapleton-edition','Modern twelve-inch Eminence speaker contrasted with the original ten-inch format.'],['Tone Master Princeton Reverb Manual','https://www.fmicassets.com/Damroot/Original/10003/OM_2274400000_Tone-Master-Princeton-Reverb_EU.pdf','Digital model, USB, XLR and power selector.']])])],faqs:[{q:'Why Does A Black Princeton Have White Knobs And One Tone Control?',a:'Transitional black-covered 6G2 Princetons retained the earlier control arrangement and white barrel knobs. Confirm the chart and circuit before assigning the later AA964 specification.'},{q:'Is AA764 The Date On A Princeton Reverb Chart?',a:'It is printed model or circuit information. On Joe’s photographed example, the separate PE ink stamp supplies the May 1966 date reading.'},{q:'Did Every Blackface Princeton Have A Grille Logo?',a:'No. Early AA964 non-reverb examples can lack one. Compare the correct model and period before treating an absent logo as damage.'},{q:'Can A Handwired Princeton Be Modern?',a:'Yes. Fender’s ’64 Custom Princeton Reverb and ’62 Chris Stapleton model are modern handwired amplifiers. Check their full identification and specifications.'}],closing:`<p>The correct model, a readable date record and a clear parts inventory make the ${a(link('princeton','value'),'Princeton value chart')} useful. The ${a(era,'Fender eras article')} places the cosmetics in context, while the ${a(comparison,'Princeton, Deluxe and Twin comparison')} addresses choosing an amp for playing.</p>`};

const eraArticle:ModelGuideData={...defaults,slug:'fender-amp-eras-tweed-brownface-blackface-silverface',kind:'article',category:['serial-number-dating-guides','Serial Number & Dating Guides'],title:'Tweed, Brownface, Blackface, Silverface: Fender Amp Eras',seoTitle:'Tweed, Brownface, Blackface, Silverface: Fender Amp Eras',description:'Tell vintage Fender amp eras apart by covering, grille, panel, knobs and circuit changes, with photos of Joe’s amps and links to dating and values.',eyebrow:'Vintage Fender Amplifiers · 1948 To 1980',dek:'A visual guide to the four era names, the model-specific exceptions, and the evidence that can date an individual amp.',hero:ph.tweedFront,glanceTitle:'Fender Era Dates',glance:[['Tweed','1948 to 1959'],['Blonde And Brownface','1959 to 1963'],['Blackface','1963 to 1967'],['Silverface','1967 to 1980']],secondaryActions:[{label:'Which Era Is Mine?',href:'#which-era'},{label:'Use The Date Decoder',href:dating+'#amp-decoder'}],intro:{html:`<p>Fender amp era names describe a recognizable combination of covering, grille and control-panel appearance. Tweed, blonde and brownface, blackface, and silverface are useful first categories when you’re looking at an unfamiliar amplifier. Joe’s ${a(dating,'Fender amp dating reference')} uses the boundaries shown here. Individual models changed on their own schedules, and electrical revisions didn’t always coincide with a new faceplate. Start with the visible features, then check the model and date evidence.</p>`,calloutTitle:'Era Is The First Identification Step',callout:'A covering color can narrow the search. It can’t authenticate the cabinet, identify every circuit revision or supply a dependable build year.'},assessmentNote:'These era descriptions help identify original Fender amplifiers. Reissues, replacement cabinets and changed cosmetic parts require additional checks.',faqSubtitle:'Fender Amp Eras',closingTitle:'Use The Era To Choose The Next Check',sections:[
section('which-era','Which Era Is Mine?','Compare The Visible Features',[{type:'table',caption:'Fender Amp Eras At A Glance',columns:['Era','Years','Covering','Grille','Faceplate','Knobs','Example Models'],rows:[['Tweed','1948 to 1959','Woven tweed','Brown or oxblood variations','Usually chrome, top mounted','Chicken-head styles','Deluxe, Princeton, Twin, Bassman'],['Blonde And Brownface','1959 to 1963','Blonde or brown vinyl','Oxblood and wheat variations','Brown, front facing','Brown or white barrel styles','Twin, Deluxe, Princeton, Super'],['Blackface','1963 to 1967','Black vinyl','Silver cloth; transitional variations','Black with light lettering','Usually black skirted; transitional white barrels','Twin Reverb, Deluxe Reverb, Princeton Reverb'],['Silverface','1967 to 1980','Black vinyl','Silver/blue and later pattern changes','Silver with colored lettering','Black skirted styles','Twin Reverb, Deluxe Reverb, Princeton Reverb']],note:'These are broad visual descriptions. Model-specific transitions, replaced parts and modern recreations can depart from the expected combination.'},paras('Read across a row instead of relying on a single feature. A black-covered cabinet can belong to a blackface or silverface amp, and both can carry a silver-looking grille. The faceplate provides a quick distinction, while its lettering and controls identify the model more precisely. A complete front photograph is usually the best first image to collect.','Photograph the rear next. It can show the speaker format, chassis arrangement and paper chart, as well as replacement parts that the front conceals. Keep uncertainty in the description when the cabinet and panel suggest different periods. A transitional production example and an amp assembled from mismatched parts require different explanations.')]),
section('tweed','Tweed: 1948 To 1959','Woven Covering And Changing Cabinets',[paras(`Tweed refers to the woven exterior material, with TV-front, wide-panel and narrow-panel cabinet forms inside the era. Those shapes provide more useful identification than the word tweed alone. Joe’s 1957 ${a(link('deluxe'),'Deluxe example')} shows the narrow-panel form, top controls and dark grille. Its 5E3 circuit designation identifies a particular design within the wider Deluxe history.`, 'The model names also cover very different sizes and electrical arrangements. A small tweed Princeton uses one output tube and an eight-inch speaker in its later narrow-panel form. The tweed Twin developed into a much larger two-speaker amplifier with several power revisions. Identifying both as tweed is accurate, but it leaves the model-level work undone.',`A surviving tweed surface can be stained, worn or darkened. Reproduction covering can also be aged. Inspect the seams and cabinet evidence rather than assigning age from color. The ${a(link('deluxe','value'),'Deluxe value guide')} separates the cabinet generations, while the ${a(link('twin','value'),'Twin price chart')} distinguishes the earlier Twin versions. Their separate rows show why one general “tweed amp value” is too broad.`, 'The era ends in 1959, while some individual models continued with tweed cosmetics beyond that boundary. The narrow-panel Deluxe is one documented example. Keep a model-specific continuation attached to that model instead of shifting the dates of the entire era.',`The <a href="/post/fender-bassman-authentication-guide/">Bassman identification guide</a> follows the change from a single-fifteen combo to four tens and separate cabinets, with corresponding <a href="/post/fender-bassman-value-guide/">Bassman value groups</a>. At the smaller end, the <a href="/post/fender-champ-authentication-guide/">Champ guide</a> distinguishes the Champion and later Champ designs, and the <a href="/post/fender-champ-value-guide/">Champ price chart</a> keeps their cabinet generations separate.`),{type:'photos',photos:[ph.tweedFront]}]),
section('brown-blonde','Blonde And Brownface: 1959 To 1963','Vinyl Covering And Front Controls',[paras(`Brown and blonde coverings identify a period with substantial differences among models. The brown ${a(link('princeton'),'Princeton 6G2')} has a small front panel with volume, tone, speed and intensity. Joe’s blonde Twin has a much broader panel and two speakers. The covering colors belong in the same broad era, but they don’t imply matching circuitry or output.`, 'Look at the grille and knobs as well as the cabinet. Oxblood and wheat-colored cloth appear in this period, and barrel-style knobs distinguish many examples from the later skirted black knobs. Those details are useful comparisons when original. A replaced grille, handle or knob set must be identified before it is used as dating evidence.',`The ${a(link('twin'),'Twin identification guide')} follows the brown/blonde family into the Twin Reverb. Its photographed 1963 tube chart carries a readable date stamp. That kind of evidence can support a narrower description than the covering alone. Brownface and blonde amp values still depend on the model, with the ${a(link('princeton','value'),'Princeton chart')} separating its brown 6G2 from the small tweed versions.`, 'These amps are sometimes discussed as a single transitional sound. A more useful listening comparison names the specific circuit and speaker arrangement. The controls and documented design tell you what is being compared; an era nickname leaves too much variation unresolved.',`The <a href="/post/fender-super-reverb-authentication-guide/">Super identification guide</a> compares Joe’s two brown examples with the later four-ten Super Reverb; their <a href="/post/fender-super-reverb-value-guide/">separate value entries</a> reflect those distinctions. The <a href="/post/fender-vibrolux-authentication-guide/">Vibrolux guide</a> also separates non-reverb models from the later reverb version, which has its own <a href="/post/fender-vibrolux-value-guide/">Vibrolux value group</a>.`),{type:'photos',photos:[ph.blondeFront]}],'dark'),
section('blackface','Blackface: 1963 To 1967','Black Panels And Reverb Models',[paras('Blackface describes the dark control panel with light lettering. Black vinyl and a silver grille commonly accompany it. Read the complete model name because reverb and non-reverb versions can look closely related. The Deluxe and Deluxe Reverb are separate models, as are the Princeton and Princeton Reverb. The front controls help distinguish each pair.','Circuit designations such as AB763 identify a documented family, but the paper label doesn’t prove every part inside still follows that drawing. Replaced components and circuit modifications need inspection. Likewise, an original circuit in a replacement cabinet should be described as that combination, with both identities stated.',`Joe’s blackface Princeton Reverb shows the six-control reverb arrangement and a dated chart. His 1967 Deluxe Reverb offers another scale of the same general appearance. The ${a(link('princeton'),'Princeton identification page')} explains its transitional non-reverb versions, including black-covered amps with earlier controls. Those exceptions are a reason to read the layout before assigning a specification.`, 'CBS bought Fender in January 1965, during the blackface era. The ownership change and the silverface appearance therefore weren’t simultaneous. A blackface amp can be CBS-era, and its production features must be evaluated by model. Broad “before CBS” descriptions should be checked against the date evidence instead of inferred from panel color.'),{type:'photos',photos:[ph.princetonFront]}]),
section('silverface','Silverface: 1967 To 1980','Trim, Grille And Circuit Revisions',[paras('Silverface amplifiers combine a silver-colored control panel with model-dependent lettering and grille changes. Early examples often have aluminum trim around the grille, commonly called drip edge. Later amps lose that surround, and grille and logo details continue to change. A piece of trim can be replaced, so its presence supports a comparison rather than an exact date by itself.','The drip-edge transition is useful because cosmetic and electrical changes overlapped. Some early silverface amps retain earlier circuits. A seller’s claim that an amp has a blackface circuit needs evidence from the chassis; the aluminum surround alone doesn’t establish it. The reverse assumption is also too broad: silver appearance doesn’t describe one uniform circuit across every model.',`The Twin Reverb received master-volume and later high-power revisions that don’t apply to the Deluxe Reverb or Princeton Reverb as a group. The ${a(link('deluxe'),'Deluxe guide')} and ${a(link('twin'),'Twin guide')} keep those histories separate. Joe’s 1979 Deluxe Reverb photograph shows a later silverface example without requiring the reader to infer a Twin specification from its panel color.`, 'A return to black panel cosmetics near the end of this scope adds another identification trap. An original later amp can have a black panel without belonging to the 1963 to 1967 era. Read the component dates and control arrangement before labeling it an earlier blackface model.'),{type:'photos',photos:[ph.silverFront]}],'dark'),
section('dates-and-values','Turn An Era Identification Into A Date And Value','Follow The Model Evidence',[paras(`Use Joe’s ${a(dating+'#amp-decoder','tube-chart date decoder')} for a readable two-letter ink stamp. The system starts with A for 1951 and was used until about 1970. If the paper is missing, consult the ${a(dating+'#tc-9','transformer and speaker code section')} and the ${a('/fender-pot-codes/','Fender pot-code guide')}. Fender amp serial numbers weren’t reliably sequential and aren’t useful for finding the year.`, 'Value comparisons also need the model. Earlier tweed Twins occupy a different market level from many later Twin Reverbs, but that doesn’t create a universal ranking for every Fender amplifier. A clean, original example and a heavily altered one can require very different assessments within the same era. Condition and configuration belong in the comparison alongside the date.',`The ${a(link('deluxe','value'),'Deluxe estimates')}, ${a(link('princeton','value'),'Princeton estimates')} and ${a(link('twin','value'),'Twin estimates')} provide model-specific starting ranges. For playing needs, the ${a(comparison,'Princeton Reverb, Deluxe Reverb and Twin Reverb comparison')} considers headroom, speakers and carrying weight. Those practical differences can matter more to a player than owning a particular faceplate color.`),cta('Send Joe A Front And Rear View','Include the model lettering, chart and any known repairs. The era can usually be narrowed before a more detailed inspection is arranged.')]),
section('references','Sources For Fender Era Changes','Era Dates And Model Records',[refs([['Joe’s Fender Amp Dating Reference',dating,'The four era boundaries and dating method.'],['Fender’s Twin History','https://www.fender.com/articles/behind-the-scenes/pristine-cleans-aggressive-overdrive-the-fender-twin-story','CBS timing and the distinction between cosmetic and electrical changes.'],['Narrow-Panel Deluxe',fg('narrow-panel-tweed-deluxe'),'Model-specific continuation beyond the broad tweed boundary.'],['Blackface Princeton',fg('blackface-princeton'),'Transitional 6G2 controls and cosmetics.'],['Silverface Deluxe Reverb',fg('silverface-deluxe-reverb'),'Later panel, grille, control and cosmetic-return details.']])])],faqs:[{q:'Can A Blackface Amp Be A CBS-Era Fender?',a:'Yes. CBS acquired Fender in 1965, inside the 1963 to 1967 blackface era. Panel color alone doesn’t establish pre-CBS manufacture.'},{q:'Does Drip Edge Identify A Specific Circuit?',a:'No. The aluminum grille surround is a cosmetic feature. Early silverface electrical changes need to be checked against the actual model and chassis.'},{q:'Can Replaced Covering Hide The Original Era?',a:'Yes. A recovered cabinet may retain an older chassis. Compare the panel, cabinet construction, chart and component dates, and describe the replacement.'}],closing:`<p>Use the visible era to narrow the model search, then let the amplifier’s own evidence refine the identification. The ${a(dating+'#amp-decoder','date decoder')} and model guides provide the next checks. For an amp you’re considering selling, ${a('/sell-an-amplifier-or-effect/','send Joe its photographs and history')} before changing parts or cosmetic material.</p>`};

const compareArticle:ModelGuideData={...defaults,slug:'princeton-reverb-vs-deluxe-reverb-vs-twin-reverb',kind:'article',category:['guitar-gear-and-tone','Guitar Gear & Tone'],title:'Princeton Reverb Vs. Deluxe Reverb Vs. Twin Reverb',seoTitle:'Princeton Reverb Vs. Deluxe Reverb Vs. Twin Reverb',description:'Compare original Princeton Reverb, Deluxe Reverb and Twin Reverb amps for headroom, recording, gig volume, carrying weight and vintage price ranges.',eyebrow:'Original Blackface And Silverface Amps',dek:'Choose by the clean volume you need, the speaker format you prefer and the amplifier you can comfortably move.',hero:ph.deluxeFront,glanceTitle:'The Main Differences',glance:[['Princeton Reverb','12 W; one 10-inch speaker'],['Deluxe Reverb','22 W; one 12-inch speaker'],['Blackface Twin Reverb','85 W; two 12-inch speakers'],['Comparison Scope','Original vintage models through 1980']],secondaryActions:[{label:'Compare The Specifications',href:'#comparison'},{label:'Identify The Era',href:era}],intro:{html:'<p>The Princeton Reverb is the smallest of these three vintage combos, the Deluxe Reverb adds output and a twelve-inch speaker, and the Twin Reverb provides substantially more clean output through two twelve-inch speakers. Start with the volume your playing requires and how you’ll transport the amp. Then compare the individual examples. Speaker replacements, service condition and circuit revisions can change what you hear from two amplifiers carrying the same model name.</p>',calloutTitle:'Compare Original Amps With Original Amps',callout:'The table describes vintage configurations. Modern ’65, ’68 Custom and Tone Master models have their own specifications and shouldn’t supply the weight or value for an older amplifier.'},assessmentNote:'Playing recommendations are starting points for an audition. The condition, speakers and circuit of an individual vintage amplifier can change the result.',faqSubtitle:'Choosing A Vintage Fender Amp',closingTitle:'Audition The Amp At The Volume You Need',sections:[
section('comparison','Vintage Fender Reverb Amp Comparison','Blackface Reference Configurations',[{type:'table',caption:'Original Blackface Models: Output, Speakers, Weight And Value',columns:['Model','Output','Power Tubes','Speakers','Weight','Best For','Value Range'],rows:[['Princeton Reverb','12 W','Two 6V6','One 10-inch','28 lb documented example','Compact recording and lower-volume use',price('princeton','Blackface','Princeton Reverb')],['Deluxe Reverb','22 W','Two 6V6','One 12-inch','37 lb documented example','A portable starting point for rehearsal and gigs',price('deluxe','Blackface','Deluxe Reverb')],['Twin Reverb','85 W','Four 6L6GC','Two 12-inch','62 lb documented example','Higher clean-volume requirements',price('twin')],['<a href="/post/fender-vibrolux-authentication-guide/">Vibrolux Reverb</a>','35 W','Two 6L6GC','Two 10-inch','40 lb documented example','Two ten-inch speakers in a smaller combo',ampPrice('fender-vibrolux-4')],['<a href="/post/fender-super-reverb-authentication-guide/">Super Reverb</a>','40 W','Two 6L6GC','Four 10-inch','60 lb documented example','Four-speaker coverage and stage use',ampPrice('fender-super-reverb-11')]],note:`Weights describe individual documented vintage examples, not guaranteed factory weights: ${a('https://www.ggjaguar.com/princrev.htm','1966 Princeton')}, ${a('https://www.ggjaguar.com/dlxrev.htm','1966 Deluxe')}, ${a('https://www.creamcitymusic.com/vintage-1966-blackface-fender-twin-reverb-2x12-tube-combo-amp/','1966 Twin')}, ${a('https://www.ggjaguar.com/vluxrev.htm','1967 Vibrolux')} and ${a('https://www.ggjaguar.com/superrev.htm','1967 Super')}. Output figures are nominal model ratings. Values reproduce the excellent-original blackface rows in the linked guides below. The Vibrolux value uses the 1964 to 1967 group; the Super value uses the 1963 to 1964 Fender Electric group. The Super weight example is a separate 1967 amp.`},paras(`For the complete price groups and condition assumptions, use the ${a(link('princeton','value'),'Princeton value guide')}, ${a(link('deluxe','value'),'Deluxe value guide')} and ${a(link('twin','value'),'Twin value guide')}. The single range for each model above is its blackface reference, so it shouldn’t be applied automatically to a later silverface example.`, 'Weight can change with speakers, transformers, cabinet work and accessories. Ask for the actual amplifier to be weighed if carrying it is a deciding factor. A measurement taken from a current reissue’s specification sheet doesn’t establish the weight of a vintage amp with different parts.')]),
section('headroom','Headroom And The Clean Sound You Need','Try Your Loudest Playing First',[paras('Clean headroom is the room an amplifier has before the sound becomes more distorted at the level you’re using. The Twin’s much higher nominal output makes it the starting candidate when clean volume is the main requirement. The Princeton is the first one to try when smaller size and lower output suit the job. The Deluxe sits between them in this comparison.','That order doesn’t mean every guitar and speaker will produce the same result. Bring the guitar you’ll use, including its hottest pickup setting, and play as hard as the performance requires. Listen for whether the attack stays clear at the needed volume. Set the tone controls for the sound you want instead of comparing identical knob numbers on different circuits.','For pedal use, decide where you want distortion to originate. If the amplifier needs to stay clean while pedals supply the gain, audition that clean level with the pedals connected. If you want the amplifier itself to overdrive, check the volume at which you like that sound. A pleasing overdriven sound may be too loud or too quiet for the intended room.','Treat a weak or noisy example as an inspection question before forming an opinion about the entire model. Worn tubes, speaker problems or circuit changes can affect the audition. Ask what service has been completed and whether the amp follows its original specification. The purchase is for that individual amplifier in its present state.')]),
section('gigging','Volume At Rehearsal And Onstage','Band Level And Microphone Support',[columns([
['Princeton And Deluxe At A Gig','A Princeton can be a useful choice when the required stage volume is modest or a microphone carries the sound through the PA. Test its clean level against the actual band. The Deluxe offers more nominal output and a larger speaker, making it a sensible next comparison when the Princeton runs out of the clean sound you need. Neither model should be chosen solely from a promise that it will handle every drummer.'],
['Twin, Vibrolux And Super Options','The Twin is a strong candidate for a loud clean foundation. The Vibrolux and Super offer different speaker formats and output levels, so include them if the two-twelve-inch Twin feels too large or you prefer ten-inch speakers. Listen at the required stage level. The Super’s four-speaker cabinet also changes the carrying problem, even when its nominal wattage is lower than the Twin’s.']]),paras('Set up the audition as close as possible to the intended stage arrangement, including microphone and monitor support.','Silverface Twins require particular care in this discussion. Later standard and ultralinear versions have different output specifications from the blackface reference in the table. A master-volume control also changes the available control arrangement. The word silverface doesn’t identify one circuit, and the Princeton or Deluxe shouldn’t inherit the Twin’s specifications because their panels share a color.')]),
{type:'photo-band',photos:[ph.princetonFront,ph.twinFront],quote:'1966 Princeton Reverb And 1966 Twin Reverb'},
section('recording','Recording With A Princeton, Deluxe Or Twin','Choose The Sound At The Microphone',[paras('For recording, begin with the required sound and the room’s acceptable volume. A Princeton is an easy first audition when you want a compact combo and a single ten-inch speaker. A Deluxe changes both the output level and speaker format. A Twin remains useful when you want its clean response and two-speaker arrangement, even if the session never approaches its full available output.','Place the microphone and listen back before deciding that a larger amp records better. The sound at a microphone close to a speaker can differ from what you hear standing across the room. Try each amplifier in the same recording setup, then make deliberate changes in position. Keep guitar, performance and recording level reasonably consistent during the comparison.','Check background hum, rattles and intermittent reverb at the settings you’ll record. Ask about service history and have a technician investigate faults before relying on the amp for a session.','Built-in reverb and tremolo should be auditioned separately from the dry sound. Listen through the useful control range and try the footswitch if it’s included. Record any effect fault separately from your preference for its sound.',`For another small recording option, the <a href="/post/fender-champ-authentication-guide/">Champ and Vibro Champ guide</a> explains their simpler circuits, with <a href="/post/fender-champ-value-guide/">Champ values</a> by version. A <a href="/post/fender-bassman-authentication-guide/">Bassman</a> offers a different combo or separate-cabinet format; its <a href="/post/fender-bassman-value-guide/">value chart</a> distinguishes complete sets from heads alone.`)]),
section('portability','Weight, Cabinet Size And Everyday Transport','Measure Your Actual Route',[paras('The documented examples show a substantial carrying difference between a Princeton and a Twin. Cabinet dimensions and the way the load sits in your hands matter as well. Before buying, consider stairs, doorways, the vehicle opening and the distance from parking to the stage. An amp that fits comfortably in a rehearsal room can still be inconvenient on that route.','Check the handle and mounts before lifting. Casters help on level surfaces, but stairs and loading into a car still require a lift.','Speaker substitutions can materially change the load. The Twin weight in the table comes from a documented 1966 example with period-correct Jensen C12N speakers. It isn’t a promise for a Twin with different speakers. Ask for the present weight and a rear photograph together so the measurement can be connected to its actual configuration.',`The <a href="/post/fender-vibrolux-value-guide/">Vibrolux value guide</a> and <a href="/post/fender-super-reverb-value-guide/">Super Reverb value guide</a> supply the other two table ranges. Their <a href="/post/fender-vibrolux-authentication-guide/">Vibrolux identification</a> and <a href="/post/fender-super-reverb-authentication-guide/">Super identification</a> pages distinguish the earlier non-reverb models from the versions compared here.`)]),
section('price','Price The Version And Its Condition','Use The Matching Value Guide',[paras('A smaller amplifier doesn’t automatically cost less in the vintage market. The blackface ranges above come from separate model entries and reflect different collector and player demand. Begin with the correct version, then inspect originality and service needs. The size that suits your playing and the version that commands the highest collector price may lead to different choices.','Look beyond the initial purchase figure. A speaker replacement, missing reverb equipment or major cabinet work changes the condition assessment, while an unserviced amp may need electrical attention. Ask for a clear repair history and arrange an inspection where needed. Don’t treat a seller’s “all original” statement as a guarantee of safe operation.','Silverface alternatives deserve their own chart lookup. Their lower or higher asking prices can’t be judged from the blackface row alone, and the early trim, master-volume or boost distinctions need correct identification. Preserve the model’s actual features in the description instead of treating an alteration toward an earlier circuit as equivalent to an untouched earlier amplifier.'),cta('Compare The Specific Amps You’re Considering','Send Joe the model names, photos and known changes. An appraisal can separate the price question from the playing preferences you’ll decide in an audition.')]),
section('identify','Confirm The Model Before Making The Choice','Originality And Date Evidence',[paras(`The ${a(link('princeton'),'Princeton identification guide')} distinguishes non-reverb, reverb and transitional models. The ${a(link('deluxe'),'Deluxe identification page')} covers the 5E3 and later Deluxe families, while the ${a(link('twin'),'Twin identification page')} follows the major Twin Reverb revisions. Each includes modern reissue checks so a familiar-looking new amp doesn’t enter an original-vintage comparison.`, `For broad cosmetic clues, read the ${a(era,'tweed, brownface, blackface and silverface article')}. A readable chart stamp can be checked with the ${a(dating+'#amp-decoder','date decoder')}; transformer and speaker evidence provides another route when the chart is absent. Keep the date finding separate from the listening test. A correct year doesn’t decide which amp will suit your room.`)]),
section('references','Comparison Specification Sources','Original Models And Measured Examples',[refs([['Blackface Princeton Reverb',fg('blackface-princeton-reverb'),'12-watt, two-6V6 and single-ten-inch specification.'],['Blackface Deluxe Reverb',fg('blackface-deluxe-reverb'),'22-watt, two-6V6 and single-twelve-inch specification.'],['Blackface Twin Reverb',fg('blackface-twin-reverb'),'85-watt, four-6L6GC and two-twelve-inch specification.'],['Greg Gagliano’s Vibrolux Reverb','https://www.ggjaguar.com/vluxrev.htm','Documented 1967 example: 35 watts, two 6L6GC, two ten-inch speakers and 40 pounds.'],['Greg Gagliano’s Super Reverb','https://www.ggjaguar.com/superrev.htm','Documented 1967 example: 40 watts, two 6L6GC, four ten-inch speakers and 60 pounds.']])])],faqs:[{q:'Is A Princeton Reverb Loud Enough For A Band?',a:'It depends on the required clean level, the band and microphone support. Try it at the actual rehearsal volume. If it distorts before reaching the clean level you need, compare a Deluxe or a higher-output model.'},{q:'Is A Twin Reverb Too Loud For Recording?',a:'It can be recorded below full output. The useful question is whether it produces the sound you want at the room’s acceptable volume, including any amplifier overdrive you require.'},{q:'Does The Deluxe Reverb Always Cost Less Than A Twin?',a:'No. Vintage values depend on the model, production group and condition. Compare the correct rows in the value guides rather than assuming price follows wattage or cabinet size.'},{q:'Can I Use Modern Reissue Weights For Vintage Amps?',a:'Use the actual vintage amp’s weight. Different speakers, cabinets and transformers can change it, and current reissue specifications describe different products.'}],closing:`<p>Choose a candidate from its output and speaker format, then audition the particular amp and check its carrying weight. For a condition-based estimate, use the linked model value guides or ${a('/free-appraisal/','send Joe your amp photographs')}. If you’re selling an amplifier you no longer use, see ${a('/sell-an-amplifier-or-effect/','how to sell an amp to Joe')}.</p>`};

// BEGIN AMP PR 2
// PR 2 content is appended to fender-amps.ts after its private editorial checks.
const pairLink=(family:string,kind='authentication')=>`/post/fender-${family}-${kind}-guide/`;
const bassBlackListing='https://reverb.com/item/81558022-fender-bassman-1960s-blackface';
const bassOxbloodListing='https://reverb.com/item/93427883-fender-bassman-1961-blonde-oxblood';
function ampPrice(id:string){const r=values.find(r=>r.id===id);if(!r)throw Error('Missing amp value '+id);return `${money(r.low)} to ${money(r.high)}`;};
const ampChart=(family:string):GuideBlock=>({type:'table',valueChart:true,caption:'Joe’s Estimated Values: Excellent, Original Amplifiers',columns:['Model','Years','Configuration','Estimated Value'],rows:values.filter(r=>r.family===`fender-${family}`).map(r=>[r.model,r.years,r.configuration,`${money(r.low)} to ${money(r.high)}`]),note:'U.S. dollars. Original cover where applicable. Condition, repairs and replacement parts affect an individual appraisal. Overlapping dates identify distinct entries. Modern reissues are excluded.'});
const ampValueBase=(family:string)=>({...defaults,slug:`fender-${family}-value-guide`,kind:'value' as const,closingTitle:'Get Your Amp Appraised',faqSubtitle:'Original Fender Amp Values',secondaryActions:[{label:'See The Price Chart',href:'#values'},{label:'Check Your Model',href:pairLink(family)}] as [{label:string;href:string},{label:string;href:string}]});

const bassmanValue:ModelGuideData={...ampValueBase('bassman'),title:'Vintage Fender Bassman Values By Model',seoTitle:'Vintage Fender Bassman Value Guide: Tweed To Silverface',description:'Find vintage Fender Bassman values for tweed combos and blonde, blackface and silverface heads, with cabinet, speaker and service notes from Joe.',eyebrow:'Tweed Combos And Original Piggyback Amps',dek:'Match the cabinet, circuit and included equipment before putting a value on a vintage Bassman.',hero:ph2.bassTweedFront,glanceTitle:'Bassman Values At A Glance',glance:[['1959 To 1960 Tweed 4x10',ampPrice('fender-bassman-6')],['1963 To 1964 Blonde Set',ampPrice('fender-bassman-10')],['1965 To 1966 Head Only',ampPrice('fender-bassman-14')],['Condition Basis','Excellent, original examples']],intro:{html:`<p>A 1959 to 1960 tweed 4x10 Fender Bassman is estimated at ${ampPrice('fender-bassman-6')} in excellent, original condition. A 1965 to 1966 blackface head alone falls in a separate group at ${ampPrice('fender-bassman-14')}. The ${a(pairLink('bassman'),'Bassman identification guide')} explains how to establish that difference. A complete piggyback set also includes a speaker cabinet, so an estimate for the head shouldn’t be compared directly with an estimate for both pieces.</p>`,calloutTitle:'What Comes With The Bassman?',callout:'List the head, cabinet, speakers, mounting hardware, covers and removed parts. The appraisal starts with that inventory.'},sections:[
section('values','Bassman Values From Tweed To Silverface','Match All Four Columns',[ampChart('bassman'),paras('Choose a row by its full description. The early single-fifteen combos, two-input tweed four-tens and later four-input versions have separate entries. Some blonde and blackface groups include head-only estimates. A cabinet bought separately years later needs to be described as a separate cabinet, even when its covering matches the head.','The chart doesn’t assign a range to every production change. The first four-ten transition, some early black-panel variations, the Bassman 135 and an unmatched late Bassman 10 need individual review. Send photographs if your amp falls between descriptions. These figures don’t cover a ’59 reissue, Bassman LTD or a post-1980 Bassman with a familiar name. The period solid-state entry identifies a different vintage product from the tube heads.')]),
section('tweed-condition','What Matters On A Tweed Bassman','Four Speakers And One Cabinet',[paras('For a tweed four-ten Bassman, a rear photograph is as important as the front. Four matching-looking speaker labels can hide a mixed set of dates or replacement cones. Record each speaker separately. If two original speakers remain and two were changed, that is useful information an appraiser can evaluate. Describing the entire set as “vintage Jensen” leaves too much unanswered.','The cabinet deserves close attention around the bottom and the speaker baffle. Water exposure, damaged joints and replacement wood affect the assessment even when the outer tweed looks presentable. Show the inside surfaces that can be seen without removing the chassis. A repaired original cabinet and a new reproduction cabinet should be described differently. Keep photographs taken before any restoration.','A fresh tweed covering can disguise the extent of earlier damage. Don’t recover a worn Bassman simply to make it look better before an appraisal. An owner may prefer a tidy working amp, while a collector may place more weight on surviving factory material. Joe can assess the present covering and discuss what a proposed repair would change.','The early single-fifteen Bassman has its own construction and price group. Converting a later cabinet to hold one fifteen-inch speaker doesn’t create that early model. If the back opening, control arrangement or mounting holes don’t agree with the description you inherited, provide clear pictures of those areas before choosing a value row.')]),
{type:'photo-band',photos:[ph2.bassTweedFront,ph2.bassBlondeFront],quote:'1959 And 1963 Fender Bassman Amplifiers'},
dark('piggyback','Valuing A Head And Cabinet Together','Check Each Piece',[paras('A blonde Bassman head can survive in excellent condition while its original cabinet is missing. The head-only row accounts for that situation where a separate entry is available. Adding any old Fender cabinet doesn’t automatically justify the complete-set figure. The cabinet’s age, speaker configuration, covering and history need to fit the set being appraised.',`Joe’s ${a(bassOxbloodListing,'1961 blonde Bassman listing')} describes a set with dark oxblood grille cloth and its original 1x12 tone-ring cabinet. Later blonde examples use lighter wheat-colored cloth. Photograph the grille on both pieces and disclose any replacement fabric; color, weave, condition and the surviving cabinet all belong in the appraisal.`, 'Photograph the piggyback mounting hardware and any unused holes. A missing screw is a smaller issue than a cabinet modified to fit a different head, but both belong in the description. If the pieces have been together for as long as you remember, say that. Family ownership can establish a useful history without proving that Fender shipped that head and cabinet together.','Covers are easy to separate from an amp during a move. Check storage areas before selling and photograph each cover next to the piece it fits. A head cover and a cabinet cover aren’t interchangeable accessories. Torn original material may still help document the set; a modern replacement should be identified as such.',`Joe’s ${a(bassBlackListing,'1960s blackface Bassman listing')} describes a head and discloses a replacement blue pilot-light jewel. That is a useful example of recording a small cosmetic change alongside the larger questions about transformers, circuit work and the cabinet included in a sale. The listing gives a decade, so an exact production year still needs supporting evidence.`, 'For a blackface or silverface Bassman, record the exact model name and all controls. A higher output number doesn’t by itself imply a higher collector value. The correct chart entry depends on which version you own, what accompanies it and what has changed. A head fitted into a custom combo cabinet requires an appraisal of that altered configuration.')]),
section('changes','Transformers, Speakers And Circuit Changes','Describe The Present Amp',[columns([
['Transformer History','Ask for clear markings on the power transformer, output transformer and choke. A replacement may be necessary to keep the amp usable, but it changes the originality record. An old-looking transformer isn’t enough: its identity and installation need to make sense for that circuit. Include any invoice explaining a replacement or rewind.'],
['Speaker Condition','A speaker can retain its old frame and label after reconing. Tell Joe about that work, including which of the four speakers received it. A cabinet loaded with recent speakers may suit regular playing, but the original-speaker estimate needs adjustment. Photograph retained speakers separately and say why they were removed.']]),paras('Bassman circuits are often discussed by their printed codes. An owner’s claim that a later amp was converted to an earlier circuit doesn’t make it an original earlier production example. Provide the technician’s description of the work. Changed wiring, controls and transformer specifications can affect both its appeal and the amount of work required to understand it.','The cost of a modification isn’t a reliable measure of the amount it adds to a sale. A useful master volume, effects loop or custom cabinet may appeal to a particular player and narrow the group of originality-focused buyers. Describe the result accurately instead of adding the repair bill to a chart figure. Removed factory parts should stay with the amp when possible.')]),
section('service','Service Records And An Untested Bassman','Condition Beyond The Covering',[paras('Routine electrical maintenance needs a specific record. “Recapped” might mean replacement filter capacitors, or it might describe much more extensive work. Ask which parts changed and retain the invoice. A clear chassis photograph from the technician can show the difference without asking an owner to open the amplifier.','An amp that has been stored for decades shouldn’t be powered up just to prove it works for an appraisal. Explain when it was last used and any known symptoms. A qualified technician can evaluate its electrical condition. Useful photographs and an honest untested description give Joe a starting point without creating a new repair problem.','Wear from use, missing hardware and electrical faults should be listed separately. A clean front panel doesn’t resolve a damaged transformer, and a working demonstration doesn’t establish that the speakers or cabinet are original. The appraisal considers those facts together. There isn’t a single percentage deduction that covers every serviced or modified Bassman.')]),
section('appraisal','Photographs For A Bassman Appraisal','Include Both Pieces Of A Piggyback Set',[list([
['Front And Full Controls','Photograph the entire combo or both pieces of the set. Add a square view of the control panel, including the input count and any model number or added control.'],
['Back And Cabinet Interior','Show the rear panels, cabinet opening and speaker arrangement. For a closed cabinet, use existing service photographs or ask a technician for access; don’t remove the amplifier chassis yourself.'],
['Tube Chart And Chassis','Send the paper label where it is attached, plus any technician-supplied circuit pictures. Include a damaged or partial label without trying to clean or retouch its printing.'],
['Transformer Stamps','Keep each full stamped line in view and identify its location. A close-up alone can leave the appraiser unable to tell which transformer it belongs to.'],
['Every Speaker','Provide one label and frame-code photograph per speaker. Number the positions in your message so a mixed set can be assessed accurately.'],
['Hardware And Service Paperwork','Show covers, mounting hardware, retained components and invoices. A standard vintage Bassman has no built-in reverb tank to inventory; identify any added reverb equipment separately.']]),paras(`For production evidence, use Joe’s ${a(dating+'#amp-decoder','tube-chart date decoder')} or the ${a(dating+'#tc-9','transformer and speaker code section')}. Readable control markings can be compared with the ${a('/fender-pot-codes/','pot-code guide')}. Fender amp serial numbers don’t reliably supply the year.`),cta('Get A Bassman Estimate From Joe','Send the photographs you have and list what comes with the amp. Include known alterations and any parts you still have in storage.')])
],faqs:[{q:'Is A Bassman Head Worth The Same As A Complete Set?',a:'A matching cabinet and its speakers need to be accounted for. Use a head-only entry when one is listed, and describe any separately acquired cabinet.'},{q:'Does Recovering A Bassman Increase Its Value?',a:'Fresh covering changes the originality assessment. Ask for an appraisal before cosmetic restoration; the result depends on the amp and its present condition.'},{q:'Can I Price A Bassman LTD With The Tweed Rows?',a:'No. The LTD and other modern reissues require their own appraisal. These estimates apply to the original vintage versions listed.'}],closing:`<p>The most useful Bassman estimate starts with the correct version and a complete inventory. Revisit the ${a(pairLink('bassman'),'Bassman authentication guide')} if the head, cabinet or controls don’t match the description. The ${a(era,'Fender amp eras article')} provides broader visual context. You can ${a('/free-appraisal/','request an appraisal')} or read about ${a('/sell-an-amplifier-or-effect/','selling your amplifier to Joe')}.</p>`};
const superValue:ModelGuideData={...ampValueBase('super-reverb'),title:'Vintage Fender Super And Super Reverb Values',seoTitle:'Vintage Fender Super Reverb Value Guide: Original Amps',description:'Compare vintage Fender Super and Super Reverb values, with separate tweed, brownface and reverb entries, original photos, and condition notes from Joe.',eyebrow:'Early Super Amps To Silverface Reverb Models',dek:'Original Super and Super Reverb estimates, with separate entries for cabinet generations and later controls.',hero:ph2.superBlackFront,glanceTitle:'Super Family Price Groups',glance:[['1963 To 1964 Super Reverb',ampPrice('fender-super-reverb-11')],['1965 To 1967 Super Reverb',ampPrice('fender-super-reverb-12')],['1962 To 1963 Brown Super',ampPrice('fender-super-reverb-10')],['Scope','Original versions through 1980']],intro:{html:`<p>A 1963 to 1964 blackface Fender Super Reverb is estimated at ${ampPrice('fender-super-reverb-11')}, while the 1965 to 1967 group is ${ampPrice('fender-super-reverb-12')}. Both assume excellent, original condition. Earlier tweed and brownface Super amps have separate values. Use the ${a(pairLink('super-reverb'),'Super and Super Reverb identification guide')} to establish the model before comparing prices. The two-speaker Super and four-speaker Super Reverb share a family name, but their equipment and value groups differ.</p>`,calloutTitle:'Count The Speakers And Read The Name',callout:'A brown Super without reverb belongs in its own group. Don’t apply a Super Reverb estimate simply because a seller shortened the name to “Super.”'},sections:[
section('values','Super And Super Reverb Price Chart','Original Models By Configuration',[ampChart('super-reverb'),paras('The earliest V-front entry begins in 1947, a model-specific exception preceding the site’s broad tweed-era boundary. Later rows distinguish wide-panel and narrow-panel Supers, brown-covering details and the Super Reverb’s control changes. Dates overlap where different listed configurations were sold within the same period. Match the description as well as the year.','The late return to a black panel around 1980 has no separate estimate here. A late silverface amp with changed controls also needs closer identification before a row is applied. The historical solid-state Super Reverb entry is separate from the tube model. Modern ’65 reissues, Tone Master amps and the recent ’62 Super are excluded from these vintage figures.')]),
section('early-super','The Earlier Super Has Its Own Market','Cabinet Shape And Surviving Material',[paras('A V-front Super’s cabinet construction is part of its identity. An appraisal should show the whole front, the sides and the rear opening so repairs can be understood in context. A new cabinet built around an old chassis needs that qualification. A photograph of the logo alone provides little help with a structure that has been rebuilt.','Tweed Super values depend on matching the cabinet generation and electrical version. A narrow-panel cabinet doesn’t establish the power-tube configuration hidden inside it. Have a technician document the circuit if its identity is uncertain. The appraisal should account for the amp that survives today, including a converted circuit or a replaced transformer set.','Keep any original speaker frames with the amplifier, even if a repairer installed newer speakers for regular use. Their present condition and repair history still need to be described. Two empty frames aren’t the same inventory as two functioning original speakers, and an original label doesn’t establish that a cone is untouched.','Brownface Super photographs reveal distinctions that a listing may overlook. Joe’s 1960 example has pinkish covering and a dark grille, while his 1962 example has a wheat-colored grille. Those are useful points of comparison for an appraisal. They don’t prove another amp’s originality, and a grille replacement should be disclosed even when the replacement pattern looks appropriate.','Check the handle mounts, rear panels and cabinet corners on an early Super. These are places where wear and repairs can disappear in an attractive front photograph. If the cabinet was refinished or recovered, provide the date of the work and any earlier images. That history helps separate surviving factory material from later restoration.')]),
{type:'photo-band',photos:[ph2.superPinkFront,ph2.superBrownFront],quote:'1960 And 1962 Fender Super Amplifiers'},
dark('four-speakers','Four Speaker Positions To Account For','Super Reverb Condition',[paras('A Super Reverb appraisal needs four speaker records. Take a broad rear view first, then photograph each basket, label and readable frame stamp. Identify upper left, upper right, lower left and lower right in the message. That simple inventory prevents a single original speaker from being mistaken for an original set.','A mixed set may have been assembled deliberately for a preferred sound, or it may reflect repairs over many years. Describe what is known. If the owner before you supplied spare speakers, include photographs of those too. Don’t assume that a loose vintage speaker came out of this particular amp just because it was stored with it.','The large baffle and cabinet have to support all four speakers. Added mounting holes, a replacement baffle, cracks and moisture damage affect the assessment. Heavier replacement speakers may also have changed how the amp was handled and transported. Show the bottom and casters if present, including any holes left by earlier hardware.','A cabinet cut down to two speakers, a converted head and a complete factory combo are different appraisal cases. The work may have made an amplifier easier to carry, but it changes what a buyer is receiving. Explain the alteration before comparing it with the excellent-original range. Keep any original cabinet parts that accompanied the conversion.')]),
section('blackface-silverface','Using The Correct Reverb Model Entry','Controls And Originality',[columns([
['Blackface Groups','The blackface chart separates the early Fender Electric group from the later Fender Musical Instruments group. Read the faceplate, then confirm the production evidence. A substituted panel can carry desirable wording without making the rest of the amplifier an earlier example. Include a clear photograph of the complete panel and the paper chart.'],
['Silverface Revisions','Silverface entries distinguish early examples and later master-volume versions. Added controls, disconnected boost functions and circuit conversions need to be documented. A later amp changed toward blackface specifications still began as a later amp. The appraisal should preserve that distinction, even if the change sounds good to its present owner.']]),paras(`The ${a(comparison,'Princeton, Deluxe and Twin comparison')} includes the Super Reverb’s speaker format and output beside other vintage choices. That helps with the playing decision. Value also depends on condition and completeness, so a specification match doesn’t establish that two Super Reverbs should sell for the same amount.`, 'For an inherited amp, an uncertain date is easier to work with than an unsupported exact year. Send the evidence you have. If the two-letter chart stamp has faded, transformer and speaker markings may help establish a production window. A serial number alone won’t resolve that question, and cosmetic features can span more than one year.')]),
section('reverb-and-repairs','Reverb Equipment And Repair History','Account For What Was Changed',[paras('A Super Reverb includes more equipment than the earlier non-reverb Super. Show the tank, its label, cables and footswitch where available. A replacement tank may work well while changing the originality report. A missing footswitch should be disclosed; a newly bought switch should be identified as a replacement accessory.','Transformer changes need their own explanation. Record the power transformer, output transformer and choke, plus any technician’s notes about a failure or replacement. Matching-looking metal covers don’t establish matching specifications. If the original part remains in a box, say whether it failed and whether any attempt was made to repair it.','Replacing aging filter capacitors is different from replacing the entire circuit board or rewiring the amp to another specification. Ask for an itemized service record. The phrase “fully restored” doesn’t tell an appraiser which components survived. A clear account of the work is useful whether the amp is being sold as a collector example or a working stage amplifier.','An unknown electrical history is a reason to describe the amp as untested and arrange a qualified inspection. Don’t switch it on solely to make an appraisal video. Keep the cover, old photographs, ownership documents and repair invoices together. Each may answer a question that exterior photographs leave open.')]),
section('appraisal','Send These Super Amp Views','A Complete Condition Record',[list([
['Front And Faceplate','Include the model wording, all controls, grille and cabinet edges. Add a close view of master-volume or pull-switch markings when present.'],
['Full Rear Opening','Show both or all four speakers, the back panels and the cable routing. Photograph missing panels and altered cabinet openings without cropping them away.'],
['Chart And Circuit','Send a legible image of the attached paper chart. Ask a qualified technician for interior circuit images; an unplugged amplifier can still contain dangerous stored voltage.'],
['Transformer Markings','Photograph the complete markings on each large transformer and the choke, preserving enough surrounding detail to identify the component.'],
['Individual Speaker Views','Record every speaker label and frame code. Tell Joe which speakers were replaced or reconed, and include any retained original set.'],
['Tank, Footswitch And Cover','On a Super Reverb, add the tank label and effects footswitch. On an earlier Super, show its applicable tremolo switch and accessories without treating the absence of factory reverb as a defect.']]),paras(`Joe’s ${a(dating+'#amp-decoder','chart-stamp decoder')} and ${a(dating+'#tc-9','component dating section')} explain the production clues. For readable control dates, use the ${a('/fender-pot-codes/','pot-code reference')}.`),cta('Have Joe Review Your Super Amp','Send the model details, condition photographs and repair history. Mention any speakers or accessories that will be included.')])
],faqs:[{q:'Does Every Super Amp Have Four Speakers?',a:'No. The earlier Super uses two ten-inch speakers; the vintage tube Super Reverb uses four. Identify the model before choosing a value row.'},{q:'Do Four Vintage Speakers Prove An Original Set?',a:'Each speaker’s identity, date evidence and repair history need inspection. A group of old speakers can have been assembled after the amplifier was made.'},{q:'Is A Blackface Conversion Priced As An Original Blackface Amp?',a:'A converted later amp retains its production identity. Disclose the circuit work and use an individual appraisal rather than the untouched earlier-model estimate.'}],closing:`<p>Separate the model question from the condition report, then account for every speaker and accessory. The ${a(pairLink('super-reverb'),'Super authentication page')} covers the construction and date checks. For another two-ten Fender, see the ${a(pairLink('vibrolux','value'),'Vibrolux value guide')}. Joe offers ${a('/free-appraisal/','free amp appraisals')} and can discuss ${a('/sell-an-amplifier-or-effect/','buying your vintage amplifier')}.</p>`};
const vibroluxValue:ModelGuideData={...ampValueBase('vibrolux'),title:'Vintage Fender Vibrolux And Vibrolux Reverb Values',seoTitle:'Vintage Fender Vibrolux Value Guide: Reverb And Earlier',description:'See vintage Fender Vibrolux and Vibrolux Reverb values by version, with original amp photos and practical notes on speakers, covering and repairs.',eyebrow:'Tweed, Brownface And Reverb Versions',dek:'Separate estimates for the single-speaker Vibrolux and the later two-ten Vibrolux Reverb.',hero:ph2.vibroTweedFront,glanceTitle:'Vibrolux Price References',glance:[['1956 To 1961 Tweed',ampPrice('fender-vibrolux-1')],['1961 To 1962 Brown',ampPrice('fender-vibrolux-2')],['Blackface Vibrolux Reverb',ampPrice('fender-vibrolux-4')],['1971 To 1980 Silverface',ampPrice('fender-vibrolux-7')]],intro:{html:`<p>An original blackface Fender Vibrolux Reverb is estimated at ${ampPrice('fender-vibrolux-4')} in excellent condition. The earlier tweed Vibrolux is a different amplifier, with an estimate of ${ampPrice('fender-vibrolux-1')}. Start with the ${a(pairLink('vibrolux'),'Vibrolux identification guide')} if the exact version is uncertain. One ten-inch speaker, one twelve-inch speaker and two ten-inch speakers appear in different parts of this family; each configuration needs the correct chart entry.</p>`,calloutTitle:'Vibrolux And Vibro Champ Are Different',callout:'Check the full model name on the faceplate. A Vibro Champ belongs in the Champ family and needs its own value guide.'},sections:[
section('values','Vibrolux Values By Version','Excellent, Original Condition',[ampChart('vibrolux'),paras('These ranges distinguish the tweed Vibrolux, brown one-twelve model, black non-reverb model and Vibrolux Reverb. The year groups describe the listed versions, including overlaps around model changes. If the chassis and cabinet point to different groups, have the identity reviewed before applying a price. A cabinet color alone doesn’t settle the matter.','An original transition example from 1967 or the black-panel return around 1980 may require a separate appraisal because there isn’t an isolated row for every transition. A period solid-state Vibrolux Reverb requires its own identification and individual appraisal. Modern Custom Vibrolux Reverb and ’68 Custom amps are outside these ranges.')]),
section('early-vibrolux','Why The Earlier Vibrolux Needs Its Own Estimate','Single-Speaker Versions',[paras('The tweed Vibrolux combines its own cabinet, speaker and tremolo equipment. Its value shouldn’t be borrowed from a tweed Deluxe merely because both are small Fender combos with similar covering. Keep the actual model name in an appraisal request, and photograph all of the controls. A worn or missing faceplate can make that basic identification harder.','Original covering matters on a tweed example. Show the rear seams, corners and underside, where replaced material may be more apparent than it is on the front. A darkened finish over the tweed should be mentioned if you know it was added later. Avoid cleaning or refinishing a worn cabinet to make it appear more original before an assessment.','The brown Vibrolux has a single twelve-inch speaker. A correct appraisal includes that speaker’s condition, the baffle and any changes made to fit a replacement. If a larger speaker or a different cabinet has been installed, describe the modification directly. The model’s original format remains relevant even when an owner prefers the altered sound.','Joe’s 1961 brownface photos include the speaker frame and rear opening. Those views are useful examples of what to send. They allow an appraiser to connect a close-up stamp with the speaker installed in the amp, rather than receiving an isolated number with no context. A readable code is evidence to evaluate alongside the rest of the cabinet.','The black non-reverb Vibrolux is another separate case. Joe’s 1964 example has one twelve-inch speaker and an AA763 paper chart. The absence of a reverb tank on that model is expected. It shouldn’t be treated as an incomplete Vibrolux Reverb or assigned the later model’s price merely because the cabinet wears black covering.')]),
{type:'photo-band',photos:[ph2.vibroBrownFront,ph2.vibroBlackFront],quote:'1961 And 1964 Fender Vibrolux Amplifiers'},
dark('reverb-pair','Assessing A Vibrolux Reverb Speaker Pair','Two Tens, Two Condition Records',[paras('For a Vibrolux Reverb, document both ten-inch speakers. A pair can look similar from across the room while containing different models, dates or cone repairs. Send each label and frame stamp, plus a full rear view that shows which side each occupies. If the speakers changed together, include the repair record or purchase information.','One replaced speaker doesn’t erase the amp’s identity, but the excellent-original estimate needs to reflect the change. A surviving factory speaker and a later companion are a different offering from a complete original pair. If you kept the removed speaker, tell Joe whether it was damaged, reconed or simply replaced to suit a preference.','A changed baffle can affect the assessment beyond the speakers themselves. Look for additional cutouts, non-factory mounting arrangements and repairs around the studs. Don’t remove speakers just to obtain an appraisal photo if you aren’t comfortable handling them. Existing service images or a technician’s inspection can provide the necessary detail.','The reverb tank and footswitch form another part of the inventory. Photograph the tank label and explain any replacement. A functioning reverb effect doesn’t establish that the tank, cables and switch are the original equipment. Conversely, a missing footswitch doesn’t by itself identify an electrical fault inside the amplifier.')]),
section('cosmetics','Cabinet Wear And Changed Cosmetics','Make The Condition Visible',[columns([
['Grille, Logo And Panel','A replacement grille or logo can improve the appearance while changing the collector assessment. Show the entire grille, its edges and any surviving older material. On a silverface example, include the surrounding trim if fitted. A substituted black panel should be disclosed; it doesn’t turn the amplifier into a factory blackface version.'],
['Handle And Back Panels','Handle wear, changed mounting hardware and missing rear panels should appear in the appraisal photographs. New panels may fit neatly while differing from the original construction. An old handle kept after replacement is worth documenting, but don’t use a damaged strap to carry the amplifier simply to preserve its appearance.']]),paras('A recovered cabinet, replacement cabinet and repaired original cabinet are three different descriptions. Say which work was done and who performed it when that is known. If the history is uncertain, photograph the seams, interior surfaces and mounting points without making an originality claim. Uncertainty can be investigated; an inaccurate “all original” description creates avoidable confusion.','An original cover can be overlooked because it is torn or stored separately. Include it in the inventory, along with any footswitch, paperwork or removed parts. A recently purchased protective cover has a useful purpose, but should be identified as a modern accessory. Don’t assume every accessory in the same storage box originally belonged to this amp.')]),
section('repairs','How Repairs Affect A Vibrolux Appraisal','Separate Maintenance From Alteration',[paras('The power transformer, output transformer and choke should be checked individually. If one was replaced, identify which one and provide the visible markings. The reason for replacement also helps. A failure repaired with a suitable part is different from a broader conversion intended to change the amp’s output or response.','Filter-capacitor, tube and power-cord work belongs in the service record. The bill should make clear whether the repair restored ordinary operation or changed the circuit. “Serviced” doesn’t establish either outcome without details. Preserve the technician’s photographs and any list of parts removed; they can answer questions that the current exterior cannot.','A Vibrolux stored for a long period may need inspection before use. Describe its last known operation and any noise, weak output or other symptoms. Avoid turning an unknown amp on to demonstrate it for a buyer. The appraisal can begin with photographs, and a qualified technician can address electrical condition.','Don’t apply a fixed deduction to every serviced Vibrolux. The significance of a replacement depends on the model, the rest of the amp and the buyer’s priorities. Likewise, the expense of a repair doesn’t necessarily add the same amount to the resale estimate. Joe needs the condition record before narrowing the range for your example.')]),
section('appraisal','Vibrolux Appraisal Photo List','Make The Model And Changes Clear',[list([
['Front And Model Lettering','Show the cabinet and a straight-on view of the full control panel. Keep “Reverb” visible when it is part of the model name.'],
['Rear Panel And Speaker Layout','Capture the complete back, including the one- or two-speaker arrangement. Show missing panels, extra holes and replaced hardware.'],
['Paper Chart And Technician Photos','Photograph the label in place. If chassis access is needed, use a qualified technician; unplugging an amp doesn’t remove all stored electrical hazards.'],
['Power And Output Transformers','Send legible markings with enough surrounding detail to identify each part. Add the choke where the circuit uses one.'],
['Speaker Labels And Stamps','For a single-speaker Vibrolux, document that speaker fully. For a Reverb model, send separate views of both tens and describe any reconing.'],
['Effects Equipment And Accessories','Include the tank label on a Vibrolux Reverb and the applicable footswitch. Add the cover, repair papers and any retained original components.']]),paras(`Date evidence can be checked with the ${a(dating+'#amp-decoder','tube-chart decoder')}, the ${a(dating+'#tc-9','transformer and speaker dating section')} and the ${a('/fender-pot-codes/','pot-code guide')}. A Fender amp serial number isn’t a reliable year lookup.`),cta('Ask Joe About Your Vibrolux','Share clear photos and what you know about the amp’s history. List the accessories and spare parts that will accompany it.')])
],faqs:[{q:'Is A Vibrolux Without Reverb Missing Equipment?',a:'Several original Vibrolux versions were built without reverb. Identify the model and control layout before treating a missing tank as a condition problem.'},{q:'Are Vibrolux And Vibro Champ Values Interchangeable?',a:'No. They are different amplifier families. A Vibro Champ is covered in the Champ value guide.'},{q:'Can A Replaced Speaker Be Accounted For?',a:'Yes. Provide the present speaker’s details and explain what changed. An individual appraisal can assess the pair or single-speaker configuration that actually remains.'}],closing:`<p>Start with the exact Vibrolux version, then document the cabinet, speakers and repair history. The ${a(pairLink('vibrolux'),'Vibrolux authentication guide')} gives the identification checks. If the panel says Vibro Champ, use the ${a(pairLink('champ','value'),'Champ and Vibro Champ values')} instead. Send Joe a ${a('/free-appraisal/','free appraisal request')} when you have the identifying views together.</p>`};
const champValue:ModelGuideData={...ampValueBase('champ'),title:'Vintage Fender Champ And Vibro Champ Values',seoTitle:'Vintage Fender Champ Value Guide: Tweed And Vibro Champ',description:'Find vintage Fender Champ and Vibro Champ values by version, with original tweed photos and practical notes on speakers, cabinets, repairs and appraisal.',eyebrow:'Champion, Tweed Champ And Vibro Champ',dek:'Small Fender amps have several distinct value groups. Identify the cabinet, speaker and controls before choosing a range.',hero:ph2.champ59Front,glanceTitle:'Champ Family Values',glance:[['1956 To 1964 Tweed 5F1',ampPrice('fender-champ-3')],['1965 To 1967 Champ',ampPrice('fender-champ-6')],['Blackface Vibro Champ',ampPrice('fender-champ-11')],['Basis','Excellent, original condition']],intro:{html:`<p>A vintage tweed 5F1 Fender Champ from the chart’s 1956 to 1964 group is estimated at ${ampPrice('fender-champ-3')}. A blackface Vibro Champ has a different estimate of ${ampPrice('fender-champ-11')}. The ${a(pairLink('champ'),'Champ and Vibro Champ identification guide')} helps sort the versions before you apply either range. Both figures assume excellent, original condition. A replaced speaker, altered cabinet or uncertain circuit can change the appraisal even when the amplifier still sounds good.</p>`,calloutTitle:'One Small Cabinet, Several Possible Models',callout:'Read the model lettering and count the controls. Champion 600, tweed Champ, Champ and Vibro Champ aren’t interchangeable price descriptions.'},sections:[
section('values','Champ And Vibro Champ Value Chart','Match The Full Model Description',[ampChart('champ'),paras('The chart distinguishes Champion 800 and Champion 600 models from the later Champ. It also separates the two black-covered 1964 configurations: an earlier-style 5F1 cabinet and the newer AA764 cabinet. A black exterior alone doesn’t settle which entry applies. Photographs of the controls and rear opening usually establish the next identification step.','The later silverface Vibro Champ group needs an individual appraisal here. Its reference entry extends beyond this guide’s 1980 cutoff, so no shortened value row has been created. The listed silverface Champ rows remain separate. Modern Champion 600 reissues, ’57 Customs, EC Vibro-Champs and newer reverb models aren’t included in these figures.')]),
section('tweed','What Supports A Tweed Champ Estimate','Cabinet, Circuit And Speaker',[paras('The tweed Champ’s small size makes it easy to photograph thoroughly. Include all four sides, the top controls and the back. A close view of the tweed’s wear can show whether the material has been patched, painted or replaced. Don’t clean a fragile surface aggressively before sending pictures. Details that seem untidy can help an appraiser understand what survives.','A repaired original cabinet should be described by the repair. For example, a replaced bottom panel or repaired handle mount tells Joe more than “restored.” A complete reproduction cabinet is another condition entirely, even if the original chassis was installed inside it. Keep old pictures and receipts that show when cabinet work occurred.','The speaker opening matters on a Champ. An owner may have installed a larger speaker or cut the baffle to make room for one. That change can affect the cabinet and mounting arrangement as well as the speaker itself. Show the entire baffle from the rear wherever it is visible. Don’t rely on the diameter named in an old sales receipt.','The 5E1 and 5F1 entries need their own identification. A technician can compare the actual circuit with its drawing if the label is missing or the amp has been modified. “Tweed Champ” is a useful family description, but it isn’t detailed enough to justify every chart range. A printed circuit name on a replacement label also needs supporting evidence.','Joe’s 1956 and 1959 examples provide views of the controls, cabinet and internal parts. They show the sort of record an appraisal needs. They don’t certify another amp that resembles them. If your Champ has a changed handle or a new speaker, include that information with the images instead of trying to find an archive photo that looks identical.')]),
{type:'photo-band',photos:[ph2.champ56Front,ph2.champ59Front],quote:'1956 And 1959 Fender Champ Amplifiers'},
dark('champ-vibro','Champ And Vibro Champ Appraisals','The Extra Controls Matter',[paras('A blackface or silverface Vibro Champ has tremolo controls that the ordinary Champ lacks. A seller may shorten either model to “Champ,” so the photograph should show the complete front panel. A missing or replaced faceplate can leave the model name uncertain. In that case, chassis documentation and the control layout become more useful than the seller’s shorthand.','The Vibro Champ’s additional circuit also needs a condition description. If the tremolo doesn’t operate, state that plainly. The fault may need routine repair, but its cause shouldn’t be guessed from a photograph. A working tremolo demonstration likewise doesn’t establish that every associated component is factory original. Include service notes when available.','Neither original model has built-in reverb. A separate reverb pedal or an added tank should be listed as additional equipment or a modification. A modern amp with “Vibro Champ Reverb” on its panel belongs to a different appraisal. Similar silver trim doesn’t make the modern model fit an original silverface range.','For late examples, look beyond the panel color. A replaced black faceplate can make an amp appear earlier, and a factory transition can make visual shorthand confusing. Send the paper chart and readable component markings. Joe can consider those alongside the cabinet, speaker and control arrangement before deciding which production group is supported.')]),
section('parts','A Single Speaker Can Change The Assessment','Keep A Record Of Replacements',[columns([
['Speaker And Output Transformer','There is only one speaker to document, so a replacement affects the entire speaker inventory. Photograph the label, frame and any legible stamp. An older frame may have been reconed; include that history. The output transformer also deserves its own identification, especially when a repair accompanied a speaker change.'],
['Power Transformer And Wiring','A replacement power transformer can be appropriate service work and still matter to a collector. Keep its invoice and any removed component. Changes made to accommodate a different transformer, added controls or a different power tube should be described by the technician who performed them.']]),paras('The current tubes are consumable parts. A group of desirable old tubes doesn’t establish that the surrounding amplifier is original, and replacing a worn tube doesn’t make the cabinet a reproduction. An appraisal should distinguish those facts. Avoid treating every changed part as equally important simply because all of them are inside the same small box.','A cabinet recover, altered baffle and changed transformer together need more than a generic “serviced” description. Each affects a different aspect of the amp. Conversely, a documented filter-capacitor replacement doesn’t imply that its speaker and cabinet were changed too. Clear records keep a necessary repair from being confused with a much broader rebuild.')]),
section('preparation','Before Selling Or Restoring A Champ','Describe What You Know',[paras('An inherited Champ may come with a cover, an old receipt, spare tubes or a speaker stored elsewhere. Photograph those items separately and explain their connection to the amp. A cover that has always been in the family provides useful history, but an appraiser still needs to see whether it fits this cabinet and how it is constructed.','Don’t add a restoration bill to the chart estimate as though every repair produces an equal increase in resale value. Some work makes an amp usable; other work changes its appeal to a particular buyer. If you are considering a cosmetic restoration, ask for an appraisal in its present state first. That gives you a clearer basis for deciding what work to commission.','If the amplifier’s electrical history is unknown, tell Joe when it was last used. There is no need to switch it on solely to make an appraisal video. A qualified technician can assess its condition and supply interior photographs when required. The initial review can begin with exterior pictures and an accurate account of storage and known problems.')]),
section('appraisal','Six Views For A Champ Appraisal','Small Details Should Stay Readable',[list([
['Complete Front','Show the cabinet edges, grille, badge and all controls. Include the word Vibro if it appears, plus any added knob or switch.'],
['Rear And Back Panel','Photograph the whole opening and both rear panels where fitted. Make damaged wood, extra holes and replaced screws visible.'],
['Tube Chart And Chassis','Include the label in place and a closer readable view. Interior circuit photographs should come from a qualified technician, since unplugged amps can retain dangerous voltage.'],
['Transformer Markings','Send the full markings and a wider image locating each transformer. Say whether an invoice records a rewind or replacement.'],
['Speaker Label And Frame','Show the basket, label and code without disconnecting the speaker. Note reconing, replacement or a changed mounting arrangement.'],
['Accessories And Repair History','Add the cover and retained parts. No factory reverb tank is expected on these original Champs; identify any separate or added reverb equipment.']]),paras(`For a surviving two-letter stamp, start with Joe’s ${a(dating+'#amp-decoder','tube-chart decoder')}. Missing labels call for the ${a(dating+'#tc-9','speaker and transformer evidence')} described on his dating page. The ${a('/fender-pot-codes/','Fender pot-code article')} covers control markings. Serial numbers alone aren’t reliable year evidence.`),cta('Have Joe Review Your Champ','Send clear front and rear photographs, the available labels and a description of known work. Include the accessories that will stay with it.')])
],faqs:[{q:'Does A Vibro Champ Always Have A Higher Value Than A Champ?',a:'Use the matching model and year group. Condition and changes can outweigh a simple comparison between model names.'},{q:'Are All Small Tweed Fender Amps Champs?',a:'No. Read the controls and identify the cabinet and circuit. The Princeton and other small Fender models have their own guides and value groups.'},{q:'Should I Replace A Worn Handle Before An Appraisal?',a:'Photograph it first and describe its condition. Retain an old handle if a safe replacement is needed for use.'},{q:'Why Is My Later Vibro Champ Missing From The Chart?',a:'The available reference groups that version with years beyond 1980. Joe can appraise it individually without inventing a narrower chart range.'}],closing:`<p>A Champ estimate is most useful when the model and the repair history are clear. Check the ${a(pairLink('champ'),'Champ authentication guide')} for cabinet and circuit distinctions, or compare the earlier ${a(link('princeton'),'Princeton family')} if the model name is uncertain. The ${a(era,'Fender amp eras article')} explains the broader appearance changes. Send your photographs for a ${a('/free-appraisal/','free appraisal')} when you’re ready to discuss the amp.</p>`};

const ampAuthBase=(family:string)=>({...defaults,slug:`fender-${family}-authentication-guide`,kind:'authentication' as const,closingTitle:'Identify Your Amp With Joe',faqSubtitle:'Original Fender Amplifier Identification',secondaryActions:[{label:'Check Originality',href:'#originality'},{label:'See Estimated Values',href:pairLink(family,'value')}] as [{label:string;href:string},{label:string;href:string}]});
const factory=(name:string)=>'https://el34world.com/charts/Schematics/files/Fender/'+name+'.pdf';
const bassHistory='https://www.fender.com/articles/parts-and-accessories/going-low-the-history-of-the-bassman';
const champHistory='https://www.fender.com/articles/parts-and-accessories/indispensable-undeniable-the-legacy-of-the-champ';
const bassmanAuth:ModelGuideData={...ampAuthBase('bassman'),title:'How To Identify A Vintage Fender Bassman',seoTitle:'Fender Bassman Identification: 5F6-A, Blonde And Dating',description:'Identify an original Fender Bassman by its cabinet, circuit, tubes and dated parts. Compare Joe’s tweed and blonde photos, then check for reissues.',eyebrow:'Original Bassman Combos And Heads Through 1980',dek:'A 5F6-A combo and a silverface Bassman head need different checks. Start with the format, then match the circuit.',hero:ph2.bassTweedFront,glanceTitle:'Bassman Identification At A Glance',glance:[['Scope','1952 through 1980 originals'],['Rated Output','About 26 to 135 watts by version'],['Speaker Formats','1x15, 4x10 and separate cabinets'],['Tube Families','5B6: octal preamp; 5F6-A: 12AY7/12AX7; later: 7025/12AT7']],intro:{html:`<p>An original Fender Bassman can be a tweed combo, a blonde piggyback set or a later blackface or silverface head. Identify that format before consulting the ${a(pairLink('bassman','value'),'Bassman value chart')}. Joe’s 1959 combo and 1963 6G6-B photographs show two versions that share the name while differing in cabinet, controls and rectification. This guide follows the original family through 1980 and uses factory drawings to separate the principal circuits.</p>`,calloutTitle:'The Circuit Name Is Only One Piece Of Evidence',callout:'A 5F6-A label or a handwired board can be reproduced. Cabinet construction, dated components and the actual wiring must support the identification.'},sections:[
section('reissues','Original Or Reissue?','Check The Construction And Model Markings',[columns([
['’59 Bassman Reissue And LTD',`Fender’s ${a(factory('Fender_bassman_59_rev_e'),'’59 reissue service drawing')} identifies control and main printed circuit boards. That differs from the original 5F6-A eyelet-board layout. The ${a('https://www.fender.com/products/59-bassman-ltd','LTD specification')} lists a lacquered tweed pine cabinet, four Jensen P10R speakers and a rubber dogbone handle. Those present-day parts can resemble older designs, so their appearance alone doesn’t authenticate a 1959 amp.`],
['Later Bassman Names',`The ${a(factory('Fender_bassman60'),'Bassman 60 service document')} identifies the much later PR421 model. Fender’s history also places the Bassman 20 and solid-state Compact after this guide’s cutoff. Read the complete rear model identification. Don’t place an unfamiliar Bassman into a 1960s group merely because it has black covering or a low serial number.`]]),paras('Ask a technician to photograph board construction if exterior labels leave the question open. A modern handwired replacement board or a complete replica can follow an old drawing closely. Hand assembly establishes how something was built, not when it was built. The same caution applies to an aged cabinet fitted with modern transformers.','A new speaker inside an old cabinet is evidence of a changed speaker. It doesn’t, by itself, make the entire amplifier a reissue. Record the parts separately and look for agreement among the chassis, cabinet and component dates. If those groups disagree, describe the amp as needing further identification rather than forcing one date onto everything.')]),
dark('timeline','Bassman Changes Across The Fender Eras','Broad Eras, Then Model-Specific Details',[{type:'timeline',items:[
{date:'1948 To 1959: Tweed',title:'Single Fifteen To Four Tens',html:`<p>The Bassman itself arrived in 1952. Fender’s history describes the TV-front 1x15, the 1953 wide-panel cabinet and the first 4x10 in 1954. Later four-input 5F6 and 5F6-A versions add the middle control. Tweed Bassman production continued into 1960, a model-specific overlap.</p>`},
{date:'1959 To 1963: Blonde And Brownface',title:'The Separate Head And Cabinet',html:`<p>The blonde Bassman changes to piggyback construction. The 6G6 uses a GZ34 rectifier; the 6G6-B drawing uses diodes. Joe’s ${a(bassOxbloodListing,'1961 blonde and oxblood Bassman')} provides an early example with a 1x12 tone-ring cabinet.</p><p>Oxblood is the dark maroon grille cloth used on early blonde Bassmans. ${a(bassHistory,'Fender’s model history')} places the change to lighter wheat-colored cloth in late 1962. Check the weave, attachment and replacement history alongside the covering, knobs and dated chassis. Cloth color helps identify the appearance; component evidence is needed to establish the amp’s year.</p>`},
{date:'1963 To 1967: Blackface',title:'AA864 And AB165 Are Different Circuits',html:`<p>The black-covered head loses the blonde version’s presence control and gains channel switches. AA864 and AB165 share the broad format but differ internally. A surviving earlier chart doesn’t guarantee that the chassis follows that earlier drawing.</p><p>Joe’s archived ${a(bassBlackListing,'1960s blackface Bassman head')} is another example from this period. Its listing records a replacement blue pilot-light jewel and gives no exact year or circuit designation. Keep those limits when comparing it with a claimed AA864 or AB165.</p>`},
{date:'1967 To 1980: Silverface',title:'More Names And Higher Output',html:'<p>The silver-panel family includes Bassman 50, 70, 100 and 135 heads and the four-ten Bassman 10 combo. Later high-power versions use ultralinear output stages. Factory master-volume controls and rear output markings help narrow the version before a technician checks it.</p>'}
]}]),
section('specs','Bassman Circuits And Tube Complements','Read The Exact Drawing For The Chassis',[{type:'table',caption:'Principal Original Bassman Configurations',columns:['Version','Output / Speakers','Rectifier And Full Tube Set','Controls And Appearance'],rows:[
['Early 5B6, 1x15','About 26 W; Jensen P15N 1x15','5U4G; 2x5881; 1x6SC7 and 1x6SL7GT','Volume, Tone, two inputs; wide-panel tweed, brown grille, block badge, chicken-head knobs, leather handle'],
['5E6-A 4x10','About 40 W; four ten-inch speakers','2x5U4G; 2x6L6G; 2x12AY7 and 1x12AX7','Two volumes, Treble, Bass, Presence; two inputs; narrow-panel tweed'],
['5F6-A 4x10','About 45 W; Jensen tens','GZ34; 2x5881; 1x12AY7 and 2x12AX7','Four inputs; two volumes, Treble, Middle, Bass, Presence; dark grille, chrome top panel, chicken-head knobs'],
['Blonde 6G6 / 6G6-B','About 50 W; separate 1x12 or 2x12 cabinets by version','6G6: GZ34; 6G6-B: diodes. Both: 2x5881 and 4x7025','Bass and Normal channels with Volume, Treble, Bass; Presence; brown panel and light covering; later cosmetic transitions'],
['Blackface AA864 / AB165','50 W; commonly 2x12 cabinet','Diodes; 2x6L6GC, 3x7025 and 1x12AT7','Bass Deep and Normal Bright switches; separate Volume, Treble, Bass; black panel and covering, silver grille, skirted knobs, black strap'],
['Bassman 10','50 W or later 70 W drawing; sealed 4x10 combo','Diodes; 2x6L6GC, 2x7025 and 1x12AT7','Normal and Studio channels, Master Volume; black cabinet, silver panel, silver/blue grille'],
['Bassman 70','70 W; separate cabinet','Diodes; 2x6L6GC, 3x7025 and 1x12AT7','Bass and Normal channels, Master Volume; ultralinear output transformer; silver panel'],
['Bassman 100 / 135','100 / 135 W; commonly 4x12 cabinet','Diodes; 4x6L6GC, 2x7025 and 1x12AT7','Master Volume; 135 uses ultralinear output stage; black cabinet and silver panel']
],note:'7025 is the low-noise 12AX7-family designation used in the drawings. Ratings identify designs, not a measured guarantee for a particular serviced amp. Cabinet pairings varied; record the actual cabinet.'},paras(`The ${a(factory('Fender_bassman_5f6a'),'5F6-A layout')} shows the eyelet board and socket order. Compare it with the ${a(factory('Fender_bassman_ab165'),'AB165 schematic')} before describing a later head as electrically equivalent. Fender’s ${a(bassHistory,'Bassman history')} supplies the model and cabinet sequence; individual factory drawings control the tube counts in this table.`, 'A solid-state rectifier in a tube Bassman isn’t the same thing as the separately marketed period solid-state Bassman. Rectification is one function in the power supply. The tube heads listed above still have valve preamp and output stages. A vintage all-transistor example belongs to its own model group and shouldn’t be judged by the tube socket checklist.')]),
section('five-f-six','What To Check On A Claimed 5F6-A','Controls, Board And Cabinet',[paras('Begin with the top panel. Joe’s 1959 Bassman has four inputs, two channel volumes and separate treble, middle, bass and presence controls. The rear view shows the four-speaker format. These visible features are consistent with the late tweed family, but the same arrangement is copied by later amps. A front photograph is the start of identification.','The original drawing calls for a GZ34 rectifier and a pair of 5881 output tubes. Tubes installed during servicing may carry different markings, so a mismatch needs explanation rather than an immediate conclusion about the whole chassis. A technician should identify the circuit and determine whether the installed parts suit it. Don’t substitute tubes merely to make a photograph match a chart.','Joe’s board photograph contains newer blue service capacitors among older components. That visible work prevents a casual “untouched” claim. It doesn’t erase the identity of the chassis. The useful description states which circuit it follows, what remains and what a technician replaced. Keep that level of detail when an amp has been converted or rebuilt.'),{type:'photos',photos:[ph2.bassTweedControls,ph2.bassTweedBoard]}]),
section('dating','Dating A Bassman From Readable Evidence','Chart Printing And Component Stamps',[paras(`Use Joe’s ${a(dating+'#amp-decoder','tube-chart decoder')} for the two-letter ink stamp used until about 1970. Its year sequence starts with A for 1951. Printed 5F6-A or 6G6-B text names a circuit and isn’t a date stamp. Fender serial numbers aren’t reliable year locators, even when a stamped number looks neatly sequential.`, `When the ink or paper is missing, collect several ${a(dating+'#tc-9','transformer and speaker source-date codes')}. The ${a('/fender-pot-codes/','pot-code reference')} can support the control inspection. Parts can wait in stock before assembly; a replacement part can be much newer than its chassis. The proposed production window should explain the surviving original group.`),{type:'serials',items:[{serial:'220947',title:'A Readable Speaker Stamp',html:`<p>All six digits are visible on a speaker in Joe’s 1959 Bassman. Keep this frame photograph with the full rear view, then use the ${a(dating+'#tc-9','component-code section')} to interpret it. One speaker stamp doesn’t date the other three speakers or certify their cones.</p>`,photo:ph2.bassTweedSpeaker},{serial:'6G6-B',title:'Printed Circuit Identification',html:'<p>This designation is legible on Joe’s 1963 blonde Bassman chart. The faded ink stamp isn’t clear enough for a dependable two-letter reading, so no month is assigned from it. The archive year and the readable circuit printing remain separate observations.</p>',photo:ph2.bassBlondeChart}]}]),
section('originality','Eleven Bassman Originality Checks','Have A Technician Handle Chassis Access',[list([
['Transformers And Choke','Match the power and output transformers to the exact circuit, then document the choke where fitted. Photograph the full stamps and mounting hardware. Extra holes, adapters or spliced leads merit a technician’s explanation. A correctly rated replacement can function well without being the factory part.'],
['Speakers','Inventory every basket, label and frame code. Four tens in a tweed combo need four records; a piggyback cabinet needs its own record independent of the head. Reconing preserves some speaker components and replaces others, so describe that work specifically.'],
['Capacitors And Other Components','Ask which filter and signal capacitors were changed. The board should be compared with the relevant drawing, including bias and feedback circuitry on later heads. New parts are visible in Joe’s tweed board photograph; they’re documented as service history.'],
['Tube Chart','Show the whole paper label where it is attached, including damage and adhesive edges. Read the printed model separately from ink stamps. A replacement chart can reproduce the correct design name while providing no evidence of when the amplifier was assembled.'],
['Cabinet And Covering','Inspect the combo’s baffle and rear opening or both piggyback cabinets. Changes to speaker openings, new wood and recovering should be identified. A blonde head and cabinet with similar material may have been paired later.'],
['Grille And Logo','Compare the grille weave, mounting and badge attachment with the version being claimed. Reproduction material can be visually convincing. Look for evidence around the reverse of the baffle when a technician has it accessible, rather than judging only the clean front.'],
['Faceplate And Knobs','Record input count, channel wording and every control. A black panel with white knobs can be a transition detail that needs corroboration. A substituted panel or added master-volume hole changes the evidence; don’t infer a circuit solely from its lettering.'],
['Handle','Photograph the handle, brackets and surrounding wood. A safe replacement may be sensible for use, especially on a heavy combo. Preserve the old handle if it survives and disclose new mounting holes or reinforcement.'],
['Reverb Equipment And Footswitch','The standard original Bassman versions discussed here don’t have built-in reverb or tremolo. A tank, footswitch socket or added effects control calls for a modification explanation or a separate accessory description.'],
['Back Panels','Show panel edges, screw positions and ventilation openings. A closed speaker cabinet and a partially open combo are different constructions. Replacement rear panels shouldn’t be used to infer the original speaker arrangement without further evidence.'],
['Covers','Check each surviving cover against the piece it fits. Photograph the stitching, openings, lettering and wear. A later protective cover is useful equipment, but it doesn’t establish that a head and cabinet left the factory together.']
])]),
section('service','Service History And Originality','Keep The Repair Description Specific',[paras(`Replacing exhausted filter capacitors or a damaged cord can be routine maintenance. Replacing a transformer, rebuilding a cabinet or converting the circuit changes other parts of the originality assessment. The ${a(pairLink('bassman','value'),'Bassman value guide')} explains how to prepare those details for pricing. It’s more useful to name the work than to call an amp simply “all original except service.”`, 'An old amplifier can retain hazardous voltage after it is unplugged. Leave chassis removal and electrical testing to a qualified amp technician. Request dated photographs and an itemized repair record. An owner can still supply the outside views, visible labels and ownership history without reaching into the circuitry.')]),
section('archive','Bassman Photo Timeline','Two Original Amps From Joe’s Archive',[{type:'archive',items:[{label:'Late Tweed Combo',title:'1959 Fender Bassman',html:'<p>The top controls and four-speaker rear view belong to the same archived combo. Its speaker stamp and board photographs add evidence that a front view cannot provide. Visible service components are retained in the record.</p>',photos:[ph2.bassTweedFront,ph2.bassTweedBack,ph2.bassTweedSpeaker]},{label:'Blonde Piggyback',title:'1963 Fender Bassman',html:'<p>The light-covered set has a readable 6G6-B paper chart. Compare the rear and chassis views with the tweed combo’s construction. The images document this example; they don’t establish that every similar head and cabinet is a factory pair.</p>',photos:[ph2.bassBlondeFront,ph2.bassBlondeBack,ph2.bassBlondeBoard]}]}],'archive'),
section('references','Bassman Reference Documents','Factory Drawings And Model History',[refs([
['Fender Bassman History',bassHistory,'Model introductions, cabinet changes and later names.'],['Early Bassman Field Record',fg('wide-panel-tweed-bassman'),'5B6 rating, octal tube set and exterior details.'],['Fender 5E6-A Drawing',factory('Fender_bassman_5e6a'),'Two rectifier tubes and the earlier four-ten layout.'],['Fender 6G6-B Drawing',factory('Fender_bassman_6g6b'),'Blonde head tube complement and diode rectification.'],['Fender Bassman 70 Drawing',factory('Fender_bassman70'),'Ultralinear output stage and tube set.'],['Fender Bassman 100 Drawing',factory('Fender_bassman_100'),'100-watt output stage and complete tube set.'],['Fender Bassman 135 Drawing',factory('Fender_bassman_135'),'135-watt ultralinear output stage and complete tube set.']
]),cta('Send Joe Your Bassman Identification Photos','Include the whole set, panel lettering, paper chart and visible speaker codes. Technician photographs can resolve questions about the circuit.')])
],faqs:[{q:'Does 5F6-A On A Tube Chart Prove A 1959 Bassman?',a:'No. It names a circuit design. The chassis, cabinet, component dates and actual wiring need to agree, and modern replicas can use the same designation.'},{q:'Is Every Blonde Bassman Tube Rectified?',a:'No. The 6G6 drawing uses a GZ34, while the 6G6-B uses diodes. Identify the circuit instead of inferring the rectifier from the covering.'},{q:'Can I Use The Serial Number To Find Its Year?',a:'Fender amp serial numbers aren’t reliable for that purpose. Use a readable tube-chart stamp and supporting dated components.'},{q:'Does A Replaced Filter Capacitor Make The Amp A Reissue?',a:'It records service work. A reissue is a later manufactured amplifier, which requires a different identification from a serviced original.'}],closing:`<p>Start with the cabinet format, then confirm the controls, circuit and dated parts. The ${a(pairLink('bassman','value'),'Bassman price guide')} keeps complete sets and heads alone separate. For related combos, see the ${a(pairLink('super-reverb'),'Super identification guide')} and the ${a(era,'Fender eras article')}. Joe can review your evidence through the ${a('/free-appraisal/','free appraisal form')}.</p>`};
const super70='https://schematicheaven.net/fenderamps/cbs_70w_mstrvol_pullsw_super-pro-bmstr_rev.pdf';
const super45='https://schematicheaven.net/fenderamps/cbs_45w_mstrvol_pullsw_super-pro-bmstr_rev.pdf';
const superAuth:ModelGuideData={...ampAuthBase('super-reverb'),title:'Vintage Fender Super And Super Reverb Identification',seoTitle:'Fender Super Reverb Guide: Circuits, Speakers And Dates',description:'Identify vintage Fender Super and Super Reverb amps with circuit tables, original brownface photos, speaker codes, silverface checks and reissue clues.',eyebrow:'Two-Speaker Super To Four-Speaker Super Reverb',dek:'The Super name spans several cabinet and circuit generations. Speaker count is a useful first check, followed by the controls and chassis.',hero:ph2.superPinkFront,glanceTitle:'Super Family Identification',glance:[['Coverage','Original family through 1980'],['Output Range','About 15 to 70 watts by design'],['Speakers','Super: 2x10; Super Reverb: 4x10'],['Tube Changes','Tweed 6V6 or 6L6; brown/reverb 6L6 family; full sets below']],intro:{html:`<p>The original brownface Fender Super is a two-ten combo with harmonic tremolo and no built-in reverb. The blackface Super Reverb has four tens and a spring-reverb circuit. That difference comes before any price comparison in the ${a(pairLink('super-reverb','value'),'Super family value guide')}. Joe’s archive includes a pinkish 1960 Super, a 1962 brown Super and a 1965 Super Reverb, allowing you to compare the cabinets and rear openings directly.</p>`,calloutTitle:'Read The Whole Model Name',callout:'Super, Super Reverb and Super Twin identify different amplifiers. A seller’s shortened description needs a full panel photograph.'},sections:[
section('reissues','Original Or Reissue?','Modern Super Models Have Specific Tells',[columns([
['’65 Super Reverb',`The modern ${a(factory('Fender_65_super_reverb'),'’65 Super Reverb service diagram')} includes a combined printed circuit board carrying the controls and electronic components. The original AB763 uses an eyelet-board layout. Fender’s ${a('https://www.fender.com/products/65-super-reverb','current specification')} also identifies four Jensen P10R speakers and a birch-plywood cabinet. New speakers can be fitted to an old amp, so confirm the chassis construction too.`],
['Tone Master And ’62 Super',`A ${a('https://www.fender.com/products/tone-master-super-reverb','Tone Master Super Reverb')} has digital amplification and modern rear controls, including output attenuation and an XLR line output. The newer ${a('https://www.fender.com/products/62-super-amp','’62 Super')} recreates brown cosmetics but lists two Celestion Custom ten-inch speakers. Its model documentation and modern components distinguish it from an original brown Super.`]]),paras('Handwiring doesn’t establish a vintage production date. A newly built tweed Super-style amp can use a traditional board and an old schematic. Ask for the maker’s identity, the chassis markings and the age of the major components. A replacement cabinet can also reproduce the outline of a V-front or narrow-panel amp.','Use photographs of the front and rear together. A familiar grille may conceal a different chassis, while a modern replacement speaker can sit inside an otherwise old amplifier. The identification should explain both situations. Don’t open the chassis to investigate; a qualified technician can supply the board photographs needed for that comparison.')]),
dark('timeline','The Super Family Across Four Eras','Cabinet And Circuit Changes',[{type:'timeline',items:[
{date:'1948 To 1959: Tweed',title:'V-Front, Wide Panel And Narrow Panel',html:'<p>The Super’s earliest V-front group begins in 1947, before the broad tweed period. Its angled front gives way to flatter wide-panel and narrow-panel cabinets. The narrow-panel family includes a 6V6 design as well as 6L6 versions; tweed production overlaps into 1960.</p>'},
{date:'1959 To 1963: Blonde And Brownface',title:'The Brown Super',html:'<p>The Super changes to a front control panel, two channels and harmonic tremolo. Early pinkish covering and dark grille material differ from the later brown-and-wheat combination. Joe’s 1960 and 1962 photographs show those appearances.</p>'},
{date:'1963 To 1967: Blackface',title:'Super Reverb And Four Tens',html:'<p>The Super Reverb adds spring reverb and a four-speaker cabinet. AB763 documentation identifies the blackface circuit, with optical tremolo and a GZ34 rectifier. Check the exact panel wording and paper chart together.</p>'},
{date:'1967 To 1980: Silverface',title:'Trim, Master Volume And Higher Power',html:'<p>Early silver-panel examples have aluminum grille trim. Later versions add a master volume and pull switch, and the late 70-watt design uses diode rectification and an ultralinear output transformer. A black-panel return near the end of the period requires date evidence.</p>'}
]}]),
section('specs','Super Specifications By Circuit','The Tube Count Changes With The Design',[{type:'table',caption:'Representative Original Super And Super Reverb Circuits',columns:['Circuit / Family','Rating And Speakers','Full Tube Complement / Rectifier','Controls And Cabinet Details'],rows:[
['Early 5C4 Super','Early family about 15 W; 2x10','2x6L6G, 3x6SC7 and 5U4G; drawing notes later miniature-tube revision','Two volumes and Tone; V-front/early tweed context, brown grille, block badge, chicken-head knobs, leather handle'],
['5E4-A Narrow-Panel Super','6V6 version; 2x10','2x6V6GT, 2x12AY7, 1x12AX7 and 5U4GA','Two volumes, Treble, Bass, Presence; tweed, dark striped grille, script badge'],
['5F4 Narrow-Panel Super','About 30 W; Jensen P10R/P10Q 2x10','2x6L6G, 1x12AY7, 2x12AX7 and 5U4G','Four inputs; two volumes and three tone/presence controls; top chrome panel'],
['Brown 6G4-A Super','About 40 W; 2x10','2x5881, 4x7025, 2x12AX7 and GZ34','Normal/Vibrato channels, Volume/Treble/Bass, Speed, Intensity, Presence; brown panel, barrel knobs, brown strap'],
['Blackface AB763 Super Reverb','About 40 W; 4x10','2x6L6GC, 3x7025, 1x12AX7, 2x12AT7 and GZ34','Normal/Vibrato, Bright switches, Reverb, Speed, Intensity; Vibrato Middle; black covering/panel, silver grille, skirted knobs, black strap'],
['Silverface 45-Watt Master-Volume Design','45 W; 4x10','2x6L6GC, 3x7025, 1x12AX7, 2x12AT7 and 5U4GB','Master Volume with pull switch as drawn; silver panel and silver/blue grille; later grille lacks aluminum surround'],
['Late 70-Watt Super Reverb','70 W; 4x10','2x6L6GC, 3x7025, 1x12AX7 and 2x12AT7; diode rectifier','Master Volume/pull switch; ultralinear transformer; rear line/recording output and hum-balance control']
],note:'The 6V6 drawing is titled 5E4-A. The 5C4 layout explicitly notes a later 12AY7/12AX7 revision. Match the actual drawing and chassis; the broad family name doesn’t supply a complete tube specification.'},paras(`The ${a(factory('Fender_super5e4_g_ee'),'5E4-A factory schematic')} clearly labels two 6V6GT output tubes. The ${a(factory('Fender_super_5f4'),'5F4 drawing')} calls for 6L6G tubes. A tweed cabinet therefore can’t answer the power-tube question by itself. The ${a(factory('Fender_super_reverb_ab763_schematic'),'AB763 Super Reverb drawing')} separately documents the reverb model.`, `Fender’s ${a(super45,'45-watt master-volume drawing')} still has a 5U4GB rectifier. The ${a(super70,'70-watt drawing')} shows diode rectification and output-transformer screen connections. A master-volume knob alone doesn’t distinguish these two designs. Look at the rear markings and have the circuit identified before assigning an output version.`, 'A period solid-state Super Reverb also exists in the value chart. Its all-transistor circuitry belongs to a separate product. The tube complements above must not be applied to it. Likewise, the higher-powered Super Twin is outside this model pair even though its name begins with the same word.')]),
section('brown-super','Brown Super Details In Joe’s Photographs','Two Tens And Harmonic Tremolo',[paras('The 1960 Super’s pinkish covering can look brown in some lighting. The front and rear photographs are more useful than a color name alone: the cabinet has two ten-inch speaker positions, a front control panel and no reverb knob. The 1962 example has the later wheat-colored grille seen in this archive. Compare those features without assuming that a similar color guarantees original covering.','The 6G4-A circuit uses a more elaborate harmonic tremolo arrangement than the later blackface optical tremolo. Its full small-tube complement matters when identifying a chassis. A technician can check that arrangement against the drawing and determine whether a previous owner altered it. A tremolo that sounds unfamiliar may need diagnosis; sound alone won’t identify a circuit revision.','The original brown Super’s two-speaker format also separates it from a Super Reverb placed in a smaller custom cabinet. If a blackface chassis has been rehoused, the resulting amp can still be useful, but the cabinet conversion belongs in its description. Photograph the full panel rather than identifying the model from the number of visible speaker cones alone.'),{type:'photos',photos:[ph2.superPinkBack,ph2.superBrownBack]}]),
section('dating','Read The Super’s Codes In Context','Two Examples From The Archive',[paras(`Start with the two-letter chart stamp when it survives. Joe’s ${a(dating+'#amp-decoder','Fender amplifier decoder')} uses A for 1951 in the year position and covers stamps used until about 1970. A printed circuit code is a separate kind of information. Fender amp serials don’t reliably establish the production year.`, `Next collect the ${a(dating+'#tc-9','speaker and transformer markings')}, keeping all four speakers separate on a Super Reverb. A single changed speaker may have a much later date than the other components. The ${a('/fender-pot-codes/','control-pot reference')} adds another check when those markings are safely documented by a technician.`),{type:'serials',items:[{serial:'220014',title:'A Speaker Code On The 1960 Super',html:'<p>The six-digit frame stamp is readable in Joe’s photograph. Any trailing mark is excluded from the transcription. Compare the component code with the cabinet and other dated parts; it is evidence about this speaker, not a complete production certificate for the amplifier.</p>',photo:ph2.superPinkSpeaker},{serial:'AB763',title:'The Super Reverb’s Printed Circuit',html:'<p>The chart clearly prints AB763 on this 1965 Super Reverb. Its faded date-stamp letters are too faint to read reliably.</p>',photo:ph2.superBlackChart}]}]),
section('originality','Eleven Checks For An Original Super','Record The Cabinet And Circuit Together',[list([
['Transformer Set','Identify the power and output transformers and the choke. A late ultralinear output transformer differs from the earlier design. Ask the technician to compare part numbers, mounting and wiring with the correct schematic, especially when a seller describes an amp as “blackfaced.”'],
['Two Or Four Speakers','Record each speaker’s location and markings. An old label can survive a recone, and a mixed set can include several different production periods. Keep a wide rear image with the close-ups so the records stay tied to their positions.'],
['Capacitors And Circuit Parts','Have the board inspected for maintenance and modifications. The reverb driver, tremolo and master-volume wiring deserve attention as well as the power supply. A service invoice should state which components were replaced and whether the circuit was changed.'],
['Paper Tube Chart','Photograph the chart’s edges and the surrounding cabinet surface. Separate circuit printing from inked date letters. The AB763 example here demonstrates why a readable model designation can coexist with a date stamp that remains undeciphered.'],
['Cabinet And Covering','Inspect the large Super Reverb baffle and the cabinet joints. A two-speaker conversion, new baffle or replacement shell changes the construction record. On an early Super, the V-front or panel style must also agree with the chassis generation.'],
['Grille Cloth And Badge','Check the cloth across the whole baffle, including its attachment where visible. Aluminum drip-edge trim identifies an appearance, not the circuitry behind it. Added trim, replacement cloth or a substituted badge needs to be recorded independently.'],
['Control Panel And Knobs','Photograph Normal and Vibrato controls, bright switches and any master-volume or pull marking. The original brown model has a different layout. A disabled pull switch remains evidence of the version and later work, even when the owner never uses it.'],
['Handle And Carrying Hardware','Inspect the handle mounts and any tilt-back legs or casters fitted to the cabinet. Extra holes and reinforced wood may explain a repair. Cosmetic originality should be documented separately from whether the handle is safe to carry.'],
['Reverb Tank And Footswitch','A Super Reverb should be assessed with its tank, bag, cables and switching equipment. The earlier non-reverb Super has no factory tank to lose. Photograph labels and connectors rather than treating any functioning replacement as original equipment.'],
['Rear Panels','Look at the panel shape, material and mounting positions. Missing or newly fabricated pieces can hide a cabinet alteration. A broad rear photograph should include all speaker positions, the chassis edge and the lower cabinet.'],
['Protective Cover','Show the cover next to the amp, then photograph its seams and wear. The fit should agree with the cabinet generation. A modern cover supplied with an older amp should be described as a later accessory.']
])]),
section('service','Servicing A Super Without Losing Its History','Keep Removed Parts Identified',[paras(`A filter-capacitor replacement can be necessary maintenance. Changing the output transformer or replacing the four-speaker cabinet affects different parts of the originality assessment. The ${a(pairLink('super-reverb','value'),'Super and Super Reverb values')} page explains how those facts enter an appraisal. Don’t describe a circuit conversion as an earlier factory build.`, 'If a technician removes components, ask for photographs and a written description of the work. Retained parts should be labeled by location and condition. A failed old transformer in a box remains historical evidence, but its presence doesn’t make the installed replacement original. Leave electrical testing and chassis access to the technician; stored voltage can remain after unplugging.')]),
section('archive','Super Photo Timeline','Brown And Blackface Examples',[{type:'archive',items:[{label:'Early Brownface Appearance',title:'1960 Fender Super',html:'<p>The pinkish cabinet, dark grille and two-speaker rear view show the earlier Super format. The speaker close-up supplies the readable code used above.</p>',photos:[ph2.superPinkFront,ph2.superPinkBack]},{label:'Later Brown Super',title:'1962 Fender Super',html:'<p>The wheat grille contrasts with the 1960 example. The rear view shows its two ten-inch speakers.</p>',photos:[ph2.superBrownFront,ph2.superBrownBack]},{label:'Blackface Reverb Model',title:'1965 Fender Super Reverb',html:'<p>The taller cabinet, reverb controls and four ten-inch speakers distinguish this 1965 Super Reverb from the earlier two-speaker Supers. Its AB763 tube chart is pictured in the dating section.</p>',photos:[ph2.superBlackFront,ph2.superBlackControls,ph2.superBlackBack]}]}],'archive'),
section('sources','Sources For Super Identification','Factory Drawings And Field Records',[refs([
['V-Front Super Field Record',fg('v-front-super'),'Early cabinet form, speaker format and approximate rating.'],['Fender 5C4 Layout',factory('Fender_super_5c4'),'Socket layout and documented miniature-tube revision.'],['Narrow-Panel Super Field Record',fg('narrow-panel-tweed-super'),'Cabinet, controls and 5F4 rating.'],['Fender Brown Super 6G4-A',factory('Fender_super_6g4a'),'Harmonic tremolo and full valve arrangement.'],['Fender Super Reverb Owner’s Manual','https://www.fmicassets.com/Damroot/Original/10001/OM_leg_gtramp_Super_Reverb_1976.pdf','70-watt rating, master-volume pull switch and rear controls.'],['Silverface Super Reverb Field Record',fg('silverface-super-reverb'),'Grille trim, speakers and later cosmetic details.']
]),cta('Get Help Identifying Your Super','Send a full front and rear view, the tube chart and readable speaker codes. Include a technician’s circuit report if the amp has been altered.')])
],faqs:[{q:'Is A Brown Super A Super Reverb Without Its Tank?',a:'No. The original brown Super is a distinct two-speaker model without built-in reverb. Identify its controls and circuit before calling equipment missing.'},{q:'Does A Master Volume Prove A 70-Watt Super Reverb?',a:'No. Fender documented a 45-watt master-volume version too. The rectifier, transformer and rear markings help distinguish the designs.'},{q:'Is Every Narrow-Panel Super A 6L6 Amp?',a:'The 5E4-A factory schematic specifies 6V6GT output tubes. The 5F4 specifies 6L6G, so identify the particular circuit.'},{q:'Can Drip-Edge Trim Date My Super Reverb Exactly?',a:'It narrows the cosmetic style. Use the chart and original component evidence to establish a production window, especially if trim or cloth has changed.'}],closing:`<p>The strongest identification connects the model lettering, speaker format, circuit and dated components. Continue to the ${a(pairLink('super-reverb','value'),'Super family price chart')} once those agree. The ${a(comparison,'vintage Fender amp comparison')} places the Super Reverb beside smaller combos, while the ${a(pairLink('vibrolux'),'Vibrolux identification guide')} covers the related two-ten reverb model. Send uncertain details to Joe with your photographs.</p>`};
const vibroluxAuth:ModelGuideData={...ampAuthBase('vibrolux'),title:'Identify Your Vintage Fender Vibrolux Or Vibrolux Reverb',seoTitle:'Fender Vibrolux Guide: Reverb Models And Originality',description:'Identify vintage Fender Vibrolux and Vibrolux Reverb models using Joe’s tweed, brownface and blackface photos, factory circuits, date codes and parts.',eyebrow:'Tweed Vibrolux To Silverface Vibrolux Reverb',dek:'The family changes from a single speaker to a pair of tens. Check for reverb controls before deciding which model you have.',hero:ph2.vibroBlackFront,glanceTitle:'Vibrolux Versions At A Glance',glance:[['Scope','1956 through 1980 originals'],['Output','About 10 to 40 watts, tube versions'],['Speaker Changes','Tweed 1x10; brown/black 1x12; Reverb 2x10'],['Power Tubes','Tweed: 2x6V6; later: 2x6L6']],intro:{html:`<p>A vintage Fender Vibrolux without reverb is a complete model in its own right. The tweed version has one ten-inch speaker; brownface and early blackface versions use a single twelve. The Vibrolux Reverb moves to two tens. Confirm those distinctions before using the ${a(pairLink('vibrolux','value'),'Vibrolux value guide')}. Joe’s 1959, 1961 and 1964 archive examples show three non-reverb versions, including a clear NC date stamp on the 1964 amp.</p>`,calloutTitle:'Vibrolux Isn’t An Abbreviation For Vibro Champ',callout:'The Vibrolux family uses a pair of output tubes. The smaller Vibro Champ is a separate single-output-tube design covered in the Champ guide.'},sections:[
section('reissues','Original Or Reissue?','Look Beyond The Silver Or Black Panel',[columns([
['’68 Custom Vibrolux Reverb',`Fender’s ${a('https://www.fmicassets.com/Damroot/Original/10001/OM_2275000000_68_Custom_Vibrolux_Reverb.pdf','’68 Custom manual')} names the channels Custom and Vintage. It specifies two Celestion TEN 30 speakers and reverb and tremolo on both channels. Those labels differ from the original Normal/Vibrato arrangement. The manual’s rear diagram also shows a detachable IEC power connection. These are practical clues before any chassis inspection.`],
['Custom Vibrolux Reverb',`The ${a(factory('Fender_custom_vibrolux_manual'),'1995 Custom Vibrolux service manual')} documents printed circuit-board construction and cream control knobs. That is a later product with a familiar name. The original AA964 drawing uses an eyelet-board layout. A technician can compare the construction when the rear identification or cabinet has been changed.`]]),paras('Some modern components deliberately reproduce older appearances. Fender’s ’68 Custom documentation even names Schumacher transformers, so a familiar transformer maker alone cannot establish a 1960s date. Read the full markings and identify the model as a whole. A speaker brand is useful evidence only when its actual model and production period are considered.','A handwired replica can also follow an early Vibrolux circuit. Handwiring is a construction method, not an age test. Conversely, replacement speakers in an original amp don’t automatically make it a modern reissue. Separate the chassis identity from the age and condition of each replaceable component.','The period all-transistor Vibrolux Reverb is another possible source of confusion. Its factory manual shows an angled control arrangement and identifies solid-state construction. It shouldn’t be confused with a tube amp that merely has diode rectification. The tube specifications below apply only to the named tube circuits.')]),
dark('timeline','How The Vibrolux Changed','Four Eras, Several Distinct Models',[{type:'timeline',items:[
{date:'1948 To 1959: Tweed',title:'The Small 5F11 Vibrolux',html:'<p>The Vibrolux begins within this era in 1956 and continues in tweed into the next broad era. Its 5F11 design uses two 6V6 output tubes, a single ten-inch speaker and tremolo. A top-mounted panel carries Volume, Tone, Speed and Depth.</p>'},
{date:'1959 To 1963: Blonde And Brownface',title:'Brown 6G11 And 6G11-A',html:'<p>The brown Vibrolux grows to a single twelve-inch speaker and 6L6 output tubes. Normal and Bright channels have separate tone controls. The front panel and brown cosmetics differ substantially from the tweed model, although neither has built-in reverb.</p>'},
{date:'1963 To 1967: Blackface',title:'Non-Reverb AA763, Then Reverb AA964',html:'<p>The early blackface Vibrolux still has one twelve-inch speaker. The Vibrolux Reverb adds a tank, reverb control and two ten-inch speakers. Joe’s 1964 AA763 example belongs to the non-reverb model.</p>'},
{date:'1967 To 1980: Silverface',title:'Vibrolux Reverb With Later Details',html:'<p>Silver-panel versions retain the compact two-ten format. Early aluminum grille trim gives way to a plain surround, and later examples add a pull-boost function. The late black-panel return needs component dates to distinguish it from the original blackface period.</p>'}
]}]),
section('specs','Vibrolux Circuits And Specifications','A Single Twelve And Two Tens Are Different Versions',[{type:'table',caption:'Original Tube Vibrolux Specifications',columns:['Version','Output / Speaker','Tubes And Rectifier','Controls / Cosmetics'],rows:[
['Tweed 5F11','About 10 W; 1x10','2x6V6GT, 2x12AX7 and 5Y3GT','Volume, Tone, Speed, Depth; three inputs; tweed, dark striped grille, top chrome panel, chicken-head knobs and leather handle'],
['Brown 6G11-A','About 35 W; 1x12 Oxford','2x6L6GC, 2x7025, 2x12AX7 and GZ34','Normal/Bright Volume, Treble, Bass; Speed and Intensity; brown panel/covering, wheat grille, barrel knobs and brown handle'],
['Blackface Vibrolux AA763','About 35 W; 1x12','2x6L6GC, 2x7025, 1x12AX7, 1x12AT7 and GZ34','Normal/Vibrato with Bright switches; Speed and Intensity; black panel and covering, silver grille, black skirted knobs and strap'],
['Blackface Vibrolux Reverb AA964','35 W; 2x10 Jensen C10Q or Oxford 10L5','2x6L6GC, 3x7025, 1x12AX7, 2x12AT7 and GZ34','Normal/Vibrato, Bright switches, Reverb, Speed, Intensity; no Middle control; blackface cosmetics'],
['Silverface Vibrolux Reverb AA270','35 to 40 W family; 2x10 Oxford or CTS','2x6L6GC, 3x7025, 1x12AX7, 2x12AT7 and 5U4GB','Normal/Vibrato, Bright switches and reverb/tremolo controls; silver panel, silver/blue grille, early aluminum trim; later pull boost']
],note:'These are circuit-specific sets, not instructions to replace tubes. The full 6G11-A schematic contains two 7025 and two 12AX7 tubes. Later service substitutions need a technician’s assessment.'},paras(`Compare the ${a(factory('Fender_vibrolux_aa763'),'AA763 non-reverb schematic')} with the ${a(factory('Fender_vibrolux_reverb_aa964_layout'),'AA964 reverb layout')}. The latter has six small tubes plus two output tubes and a rectifier. The earlier non-reverb blackface model has four small tubes. That difference survives beyond the cabinet’s similar black appearance.`, `The ${a(factory('Fender_vibrolux_reverb_aa270_schem'),'AA270 drawing')} retains tube rectification. Don’t assign the larger Super Reverb’s late high-power specifications to a Vibrolux simply because both amps have silver panels. The ${a(pairLink('super-reverb'),'Super Reverb identification guide')} covers that separate development.`)]),
section('non-reverb','Recognizing The 1964 Non-Reverb Vibrolux','The Archive Example Has One Twelve',[paras('Joe’s 1964 Vibrolux is useful because its black panel can invite an incomplete description. The faceplate says Vibrolux-Amp and the controls lack a Reverb knob. Its rear view shows a single twelve-inch speaker. The paper chart prints AA763. These observations fit the non-reverb model rather than a Vibrolux Reverb missing a speaker and tank.','The NC stamp provides a second, independent kind of evidence: it identifies a month and year under the Fender tube-chart dating system. It doesn’t certify the speaker cone, capacitors or every other component. Keep the date finding separate from an originality claim. An amplifier can be correctly identified as a 1964 model while containing later service parts.','A cabinet changed from one twelve to two tens needs closer inspection. Extra mounting holes or a new baffle can explain the current speaker arrangement. The chassis controls and actual wiring remain essential. A conversion should be described by its starting model and modifications, without assigning a factory reverb identity from the speaker count.','The brown 1961 example supplies another comparison. Its panel calls the second channel Bright, and its speaker photograph shows both an Oxford model marking and a source-date stamp. Those details help locate it in the earlier family. The dark brown cabinet alone would not distinguish all possible brown Fender models.'),{type:'photos',photos:[ph2.vibroBlackFront,ph2.vibroBlackBack]}]),
section('dating','Date Stamps On Joe’s Vibrolux Amps','Read The Characters Before Decoding',[paras(`The ${a(dating+'#amp-decoder','tube-chart date decoder')} reads a two-letter ink stamp, with A representing 1951 in the year position. Joe’s reference describes its use until about 1970. Fender serial numbers aren’t dependable year codes. Photograph a stamp sharply enough that each letter can be checked, and don’t replace uncertain characters with the year you expect.`, `For missing or damaged charts, use the ${a(dating+'#tc-9','speaker and transformer dating section')}. Record all transformers and both speakers on a reverb model. A newer replacement part establishes its own age, while the remaining original components may support the amplifier’s production window. The ${a('/fender-pot-codes/','pot-code page')} covers readable control markings.`),{type:'serials',items:[{serial:'NC',title:'March 1964 On The AA763 Chart',html:'<p>The stamp is legible on Joe’s non-reverb Vibrolux: N corresponds to 1964 and C to March. AA763 is printed separately as the circuit designation. The handwritten production notation isn’t used to calculate the date.</p>',photo:ph2.vibroBlackChart},{serial:'465-149',title:'An Oxford Speaker Stamp',html:'<p>The 1961 brown Vibrolux speaker photograph shows 465-149 and the separate model marking 12M6-1. Preserve both in the record. Interpret the source-date line with Joe’s component-code guide and compare it with the other original parts.</p>',photo:ph2.vibroBrownSpeaker}]}]),
section('originality','Eleven Vibrolux Originality Checks','Match Each Part To The Right Model',[list([
['Power, Output And Choke','The tweed 6V6 circuit and later 6L6 circuits require different transformer specifications. Have each installed part identified from its complete marking and mounting. A transformer that looks old may still be a later replacement or belong to a different amp.'],
['Speaker Or Speaker Pair','First establish whether the version calls for one ten, one twelve or two tens. Then inspect the actual frame, label and cone history. On a Vibrolux Reverb, document both positions even if one speaker appears to be a matching replacement.'],
['Electrical Components','Ask for a record of filter-capacitor service and other replaced components. The tremolo and reverb circuits deserve their own inspection. A new part may be ordinary maintenance; extensive rewiring or an added control requires a fuller explanation.'],
['Tube Chart And Stamp','Compare the printed model with the chassis and photograph the ink stamp at full resolution. The NC card above illustrates a complete reading. A label copied from another amp could carry plausible lettering without belonging to the cabinet being inspected.'],
['Woodwork And Covering','Look for altered speaker openings, replaced baffles and fresh covering around the edges. A re-covered brown amp and a newly built brown cabinet are different conditions. Preserve any photographs that show the work before new material concealed it.'],
['Cloth And Fender Logo','Check the grille pattern, attachment and badge position. Drip-edge trim can be removed or added. A familiar silver-and-blue weave helps identify a style, but its material and installation still need to be assessed for originality.'],
['Faceplate And Knob Set','Read the channel names and all control labels. Reverb lettering separates important models, while Custom/Vintage labels identify a modern family. Replaced knobs are common enough that their appearance must be checked alongside the panel and chassis.'],
['Handle And Mounts','Photograph the strap, end brackets and cabinet surface around them. A replacement fitted through existing holes leaves a different record from a handle requiring new holes or reinforced wood. Retain the removed part if it accompanies the amplifier.'],
['Tank And Footswitch','Inventory these on a Vibrolux Reverb. The non-reverb Vibrolux still has tremolo switching to consider, but no factory reverb tank. Show connectors and labels so a later compatible accessory can be distinguished from the original equipment.'],
['Back Panels','Record missing panels, new screws and replacement wood. The rear opening should agree with the cabinet version. Take a broad view before close-ups so a technician can see how the chassis, speaker and panel edges relate.'],
['Cover','A surviving cover should fit the specific cabinet. Photograph its front, seams and openings, plus any maker’s markings. An old cover stored with an amp is useful context, but its age and fit need their own evaluation.']
])]),
section('service','Service And Value Are Separate Questions','Describe Repairs Without Erasing The Model',[paras('A Vibrolux can need new filter capacitors while retaining its cabinet, transformers and speakers. A changed power transformer or a replacement cabinet affects a different part of the originality record. Avoid using “serviced” as a description for every possible alteration. An itemized invoice lets an appraiser understand the actual work.','Tremolo and reverb faults require diagnosis rather than a guess about their cause. Have a qualified technician inspect an amplifier with uncertain electrical condition, and leave chassis removal to that person. Dangerous stored voltage can remain after the power cord is unplugged. Exterior photographs and visible labels are enough to begin an identification request.',`Once the version is established, the ${a(pairLink('vibrolux','value'),'Vibrolux value page')} provides separate groups for the single-speaker and reverb models. Keep any removed speakers or transformers identified by location and condition. A retained failed part is historical evidence, even though it no longer performs its original job.`)]),
section('archive','Vibrolux Photo Timeline','Three Non-Reverb Versions',[{type:'archive',items:[{label:'Tweed 5F11 Family',title:'1959 Fender Vibrolux',html:'<p>The top panel and compact cabinet precede the later front-panel designs. The rear and board views show the construction of this archived example. They’re included as inspection material, without claiming that every installed component is untouched.</p>',photos:[ph2.vibroTweedFront,ph2.vibroTweedBack,ph2.vibroTweedBoard]},{label:'Brown Single-Twelve Model',title:'1961 Fender Vibrolux',html:'<p>The brown covering, front controls and single speaker distinguish this version from the tweed example. Its Oxford markings appear in the dating cards. This amp has no built-in reverb.</p>',photos:[ph2.vibroBrownFront,ph2.vibroBrownBack,ph2.vibroBrownSpeaker]},{label:'Blackface Without Reverb',title:'1964 Fender Vibrolux',html:'<p>The AA763 chart and NC stamp support a specific non-reverb identification. Compare the one-twelve rear view with the two-ten specification of a Vibrolux Reverb before using either model’s value group.</p>',photos:[ph2.vibroBlackFront,ph2.vibroBlackBack,ph2.vibroBlackChart]}]}],'archive'),
section('references','Vibrolux Sources And Drawings','Original Circuit Documents',[refs([
['Fender 5F11 Schematic',factory('Fender_vibrolux_5f11_schem'),'Tweed circuit, tremolo, controls and complete tube set.'],['Fender 6G11-A Schematic',factory('Fender_vibrolux_6g11_a'),'Brown circuit and the four small tubes.'],['Brown Vibrolux Field Record',fg('brownface-vibrolux'),'Rating, speaker and exterior details.'],['Blackface Vibrolux Reverb Field Record',fg('blackface-vibrolux-reverb'),'AA964 era, rating and original speaker choices.'],['Silverface Vibrolux Reverb Field Record',fg('silverface-vibrolux-reverb'),'Grille changes, rating range, pull boost and late panel change.'],['Fender Solid-State Vibrolux Manual','https://www.fmicassets.com/Damroot/Original/10001/OM_leg_gtramp_Vibrolux_Reverb_Solid_State.pdf','A separate transistor model with angled control styling.']
]),cta('Let Joe Check Your Vibrolux Photos','Include the model lettering, speaker arrangement, tube chart and known repair history. Mention whether any removed parts or original accessories remain.')])
],faqs:[{q:'Did Fender Make A Blackface Vibrolux Without Reverb?',a:'Yes. The AA763 non-reverb model uses a single twelve-inch speaker. Joe’s 1964 example and readable NC chart stamp are shown here.'},{q:'Is A Vibrolux Reverb The Same As A Vibro Champ?',a:'No. They have different circuits, output stages and speaker arrangements. The Vibro Champ belongs to the smaller Champ family.'},{q:'Does Silverface Mean The Amp Is A Modern ’68 Custom?',a:'No. Original silverface models and the later ’68 Custom share some styling. Custom/Vintage channel labels, modern rear connections and component evidence help distinguish them.'},{q:'Can An NC Stamp Prove Every Component Is From 1964?',a:'It dates the chart under the original stamp system. Speakers, transformers and service parts still require separate inspection.'}],closing:`<p>Use the full model name, controls and speaker arrangement to establish the version, then test the proposed date against the surviving evidence. The ${a(pairLink('vibrolux','value'),'Vibrolux value chart')} is the next step once that identity is clear. For the smaller similarly named amp, see the ${a(pairLink('champ'),'Champ and Vibro Champ guide')}. Joe’s ${a(era,'Fender eras article')} provides the wider visual comparison.</p>`};
const champAuth:ModelGuideData={...ampAuthBase('champ'),title:'Vintage Fender Champ And Vibro Champ Identification',seoTitle:'Fender Champ And Vibro Champ: Identify And Date Your Amp',description:'Identify vintage Fender Champion 600, Champ and Vibro Champ amps with Joe’s original examples, circuit details, speaker checks and blackface/silverface photos.',eyebrow:'Champion 600, Tweed Champ And Later Originals',dek:'A simple control panel can still belong to several generations. Cabinet shape, tube layout and the chart distinguish the original Champ family.',hero:ph2.champ56Front,glanceTitle:'Champ Family At A Glance',glance:[['Original Coverage','1948 through 1980'],['Output','About 4 to 6 watts by version'],['Speaker','One six-inch or eight-inch speaker'],['Tube Sets','Early: 6SJ7/6V6/5Y3; later: 12AX7/6V6/5Y3; Vibro adds 12AX7']],intro:{html:`<p>An original Fender Champ is a small single-output-tube amplifier. The tweed 5F1 has a volume control and no built-in tremolo or reverb; the later Vibro Champ adds Speed and Intensity controls. Use those features to establish the model before reading the ${a(pairLink('champ','value'),'Champ and Vibro Champ values')}. Joe’s photographs show a 1949 Champion 600, 1956 and 1959 tweed Champs, a 1965 blackface Vibro Champ and a 1968 drip-edge Vibro Champ. The 1959 chart carries a readable IB date stamp.</p>`,calloutTitle:'A 5F1 Circuit Can Be New',callout:'Fender’s modern ’57 Custom Champ is handwired too. A circuit name, eyelet board or tweed covering doesn’t establish an original 1950s production date.'},sections:[
section('reissues','Original Or Reissue?','Several Modern Champs Copy Earlier Styling',[columns([
['’57 Champ, ’57 Custom And EC Vibro-Champ',`Fender’s ${a('https://www.fender.com/products/57-custom-champ','’57 Custom specification')} describes a handwired 5F1 with a Weber eight-inch speaker and a 12AY7 preamp tube. Its modern manufacture shows why handwiring alone is insufficient. Fender’s ${a(champHistory,'Champ history')} identifies the EC Vibro-Champ by its EC grille badge, added tremolo-speed control and output attenuator. The original 5F1 has neither tremolo control nor attenuator.`],
['Champion 600 And Vibro Champ Reverb',`The modern Champion 600 introduced in 2007 closely copies the earlier two-tone appearance. Fender’s history identifies its revised preamp and internal speaker-output jack. The ${a('https://www.fender.com/products/68-custom-vibro-champ-reverb','’68 Custom Vibro Champ Reverb')} is easier to distinguish: it has a ten-inch Celestion TEN 30 and digital hall reverb. A reverb control and larger stock speaker don’t match an original silverface Vibro Champ.`]]),paras('Read any rear product label and compare the entire amplifier with the documentation for that exact model. A replacement label or recovered cabinet can make the outside less conclusive. Have a technician document the board, transformers and tube sockets if the identification remains uncertain. Modern vintage-style components should be evaluated by their actual markings.','The XD and X2 families add modern voicing or effects controls and fall outside this original-amp guide. Rivera-era Champ II and Super Champ models are also later exclusions. The familiar Champ name was used for several different products, so it shouldn’t be treated as a continuous specification from the 1940s onward.','A replaced speaker in an old Champ is a condition finding, not automatic evidence that the whole amp is new. The reverse is also true: fitting an old speaker into a newer reproduction doesn’t create an original vintage amplifier. Identify the chassis and cabinet, then record the age of the installed parts individually.')]),
section('champion-600','The Original Champion 600','1949 To 1953: Two-Tone TV Front',[paras(`Fender introduced the Champion 600 in mid-1949, replacing the Champion 800’s eight-inch speaker with a six-inch speaker while retaining the early four-watt circuit. Its brown and cream covering surrounds a small TV-front grille opening. Two inputs and a single Volume control sit on the angled rear panel. The wide-panel tweed cabinet followed in 1953, before the later narrow-panel Champ familiar to many players. See ${a(champHistory,'Fender’s Champ history')} for that sequence.`,`Joe’s ${a('https://reverb.com/item/71880693-fender-champion-600-1949','1949 Champion 600')} shows the two-tone cabinet, rear controls and paper labels. The listing records a few replaced capacitors, a three-prong cord and a worn handle. Those details belong in this example’s condition description.`,'The 1949 model predates the two-letter tube-chart dating system described below. Identify it from the complete construction and supporting component evidence. A later Champion 600 reissue can share the two-tone appearance; compare the chassis and rear connections as well as the covering.'),{type:'photos',photos:[ph2.champion49Front,ph2.champion49Back,ph2.champion49Label]}]),
dark('timeline','Champ Changes Across The Fender Eras','This Family Skips A Brownface Redesign',[{type:'timeline',items:[
{date:'1948 To 1959: Tweed',title:'Champion 800, Champion 600 And Champ',html:'<p>The Champion 800 begins in 1948 with an eight-inch speaker. The two-tone Champion 600 follows with a six-inch speaker. Wide-panel and narrow-panel Champ cabinets come later, and the 5E1/5F1 circuits use a miniature 12AX7 preamp tube.</p>'},
{date:'1959 To 1963: Blonde And Brownface',title:'The Champ Keeps Its Tweed Form',html:'<p>The broad Fender era changes, but this model continues in its narrow-panel form into 1964. Don’t expect a brownface Champ counterpart merely because other Fender families received brown cabinets and front controls.</p>'},
{date:'1963 To 1967: Blackface',title:'The New Champ And Vibro Champ',html:'<p>In 1964 the Champ adopts the larger front-panel cabinet and AA764 design with Treble and Bass controls. The Vibro Champ adds tremolo. Black-covered examples of the earlier cabinet form also require separate identification.</p>'},
{date:'1967 To 1980: Silverface',title:'Silver Panels, Familiar Small-Amp Format',html:'<p>The Champ family’s silver-panel change occurs in 1968, a model-specific transition within the broader silverface era. Both models retain a single eight-inch speaker. The 1980 owner’s manual still shows the Champ’s three controls and the Vibro Champ’s two additional tremolo controls.</p>'}
]}]),
section('specs','Original Champ Specifications','One Output Tube Throughout These Versions',[{type:'table',caption:'Champ And Vibro Champ Circuit Guide',columns:['Version','Power / Speaker','Full Tube Set','Controls And Exterior'],rows:[
['Champion 800 / 600','About 4 W; 800: 1x8; 600: 1x6','Early circuit family: 1x6SJ7, 1x6V6 and 1x5Y3','Single Volume; TV-front form; Champion 600 uses two-tone covering; compare exact early construction'],
['Wide-Panel 5C1 Champ','About 4 W; 1x6','1x6SJ7, 1x6V6GT and 1x5Y3GT','Volume with power switch; tweed, brown cloth, block badge, chicken-head knob, flat leather handle'],
['Narrow-Panel 5E1 / 5F1','About 5 W; early 1x6, later 1x8','1x12AX7, 1x6V6GT and 1x5Y3GT','Two inputs and Volume; 5E1 has a choke, 5F1 does not; tweed and dark striped cloth, top chrome panel, script badge, leather handle'],
['Blackface AA764 Champ','About 6 W; 1x8 Oxford 8EV','1x12AX7, 1x6V6GT and 1x5Y3GT','Volume, Treble, Bass; black covering/panel, silver grille, skirted knobs, black strap; early examples lack a grille badge'],
['AA764 Vibro Champ','About 6 W; 1x8','2x12AX7, 1x6V6GT and 1x5Y3GT','Volume, Treble, Bass, Speed, Intensity; blackface or later silverface appearance'],
['Silverface Champ','6 W in the 1980 manual; 1x8','1x12AX7, 1x6V6GT and 1x5Y3GT','Three tone/volume controls; silver panel, silver/blue grille, black cabinet, skirted knobs and black handle']
],note:'The miniature preamp tube and extra Vibro Champ tube are useful identification clues. Power-consumption figures on labels aren’t audio-output ratings. Tube substitutions should be evaluated by a qualified technician.'},paras(`The ${a(factory('Fender_champ_5e1_schem'),'5E1 schematic')} shows the power-supply choke. The ${a(factory('Fender_champ_5f1_schem'),'5F1 schematic')} uses a resistor in that part of the supply. Both specify the same basic three-tube set, so counting tubes alone cannot distinguish them.`, `Compare the separate ${a(factory('Fender_champ_aa764_schem'),'AA764 Champ')} and ${a(factory('Fender_vibro_champ_aa764'),'AA764 Vibro Champ')} drawings. The repeated AA764 designation doesn’t make them identical: the Vibro Champ includes the additional tremolo circuitry and tube. Read the model name on the drawing as well as its code.`)]),
section('five-f-one','Reading A Tweed Champ’s Construction','The Cabinet And Circuit Must Agree',[paras('Joe’s 1956 Champ has a compact chrome top panel. Its single control makes the format recognizable, but that layout has been copied in many later amplifiers. The rear view supplies the cabinet opening and speaker context that a front picture lacks. A technician’s board photograph then helps establish which circuit actually occupies the cabinet.','On the 1959 example, the paper chart clearly prints 5F1. Its inked IB stamp can be decoded separately. The handwritten production entry on the same paper is another mark with a different purpose; it is not used here as a date. A photograph that includes the whole chart keeps those distinctions visible to another reader.','An old chart can survive inside a cabinet after a chassis or speaker change. Look for agreement between the paper, the construction and the dated parts. If the chart and current circuit differ, record both findings. Avoid removing or cleaning a fragile paper label in an attempt to make it more readable.','A larger replacement speaker may require a changed baffle or new mounting holes. That work can be difficult to see from the front because the grille remains in place. A rear view helps identify the alteration without assuming that every eight-inch speaker indicates a factory eight-inch cabinet. The exact condition needs inspection.','The narrow-panel Champ also overlaps the broader blackface transition. Black covering over an older-style cabinet doesn’t make it the later front-panel AA764. The value guide has separate 1964 entries for those forms. Establish cabinet and controls first, then use component evidence to narrow its date.'),{type:'photos',photos:[ph2.champ56Controls,ph2.champ56Board]}]),
section('dating','Date A Champ With Its Chart And Components','The IB Stamp Is Readable',[paras(`Joe’s ${a(dating+'#amp-decoder','Fender tube-chart decoder')} uses two inked letters on charts through about 1970. The first follows the year sequence beginning with A for 1951; the second identifies the month. Fender amplifier serial numbers don’t provide a reliable year, so the chassis serial should remain an inventory identifier rather than the main dating method.`),{type:'serials',items:[{serial:'IB',title:'February 1959 On Joe’s 5F1 Champ',html:'<p>The image clearly shows I followed by B. In the tube-chart date table, I is 1959 and B is February. The printed 5F1 text identifies the circuit family. The handwritten production number is left out of the date interpretation.</p>',photo:ph2.champ59Chart}]},paras(`If the chart has disappeared, move to the ${a(dating+'#tc-9','transformer and speaker code section')}. Keep full component markings in the photograph instead of copying only the final digits. The ${a('/fender-pot-codes/','pot-code guide')} provides another reference when control markings can be documented safely.`, 'Compare the dates of parts that appear original to the chassis. A replacement speaker may postdate the amp by decades, while original parts can predate final assembly. One especially old component doesn’t make the whole amplifier that old. A useful identification states the supported production window and names any evidence that remains unresolved.')]),
section('originality','Eleven Checks For A Vintage Champ','A Small Amp Still Needs A Complete Record',[list([
['Transformers And Choke Where Fitted','Document the power and output transformers separately. The 5E1 drawing includes a choke; the 5F1 does not, so absence alone isn’t a fault. A technician should check specifications, mounting and lead connections before a part is described as original.'],
['The Single Speaker','Show the label, frame, cone and mounting wherever visible. A six-inch or eight-inch diameter helps identify the version, but a baffle alteration can change that evidence. Record reconing and replacements instead of assuming an old basket means an untouched speaker.'],
['Capacitors And Resistors','Ask for a circuit photograph and an itemized service record. Replacement filter capacitors can be necessary maintenance. Added gain stages, altered tone controls or a substantially rebuilt board need a different description from a simple repair.'],
['Tube Chart','Preserve the chart in place, including damaged areas. A printed circuit designation, ink date stamp and handwritten production notation should be transcribed separately. A missing chart increases reliance on the cabinet, chassis and component evidence.'],
['Cabinet And Covering','Inspect the bottom, corners and baffle for changed wood. Look at the covering around the control opening and rear panels, where restoration may be easier to see. A repainted or recovered cabinet should be described without guessing what lies beneath it.'],
['Grille And Logo','Compare the cabinet generation before calling a badge missing. Early blackface Champs can lack a grille logo. Cloth and badges can also be replaced, so their condition needs to be considered alongside mounting evidence and the rest of the cabinet.'],
['Faceplate And Knobs','Count the controls and read their names. One volume knob suggests the earlier simple format; Treble and Bass identify the later control arrangement, and Speed and Intensity distinguish the Vibro Champ. Added holes or switches should be photographed closely.'],
['Handle','The handle and its mounts can be worn or replaced even when the cabinet survives. Show any extra holes, different brackets or repaired wood. Keep the older piece with the amplifier if it was removed for safe carrying.'],
['Effects And Footswitch','Original Vibro Champs have tremolo; ordinary Champs don’t. Neither original model in this guide has built-in reverb. Identify any tremolo footswitch and added effects equipment separately, and photograph the connection rather than guessing from a loose pedal.'],
['Rear Panel Pieces','Check the size, covering and attachment of each panel. A missing piece may expose more of the chassis, while a new panel can conceal a cabinet modification. The overall rear image should show the speaker and panel arrangement together.'],
['Cover And Loose Parts','Photograph the cover beside the cabinet and record any removed components. An accessory can be useful without being original to the amp. Family history or an old receipt adds context, but the physical item still needs its own assessment.']
])]),
section('service','Service Work On A Small Tube Amp','Condition Is More Than Whether It Plays',[paras('A quiet demonstration can establish that an amp operates at that moment. It doesn’t establish the age of its speaker, the condition of its filter capacitors or the originality of its transformer set. A qualified technician can evaluate those questions and document the work required. Don’t open the chassis yourself; these small amps can retain dangerous voltage after unplugging.','Keep routine maintenance distinct from changes to the design. Replacing worn tubes or failed filter capacitors differs from enlarging the speaker opening, fitting a new transformer or adding controls. An amp can remain useful after any of those changes, but its originality description needs to follow what actually happened.',`The ${a(pairLink('champ','value'),'Champ value guide')} explains what to send for an appraisal once the version is known. Retain the repair invoice and label any old parts that accompany the amplifier. There’s no need to describe a serviced amp as untouched to give an appraiser an accurate and useful history.`)]),
section('archive','Champ Photo Timeline','Tweed, Blackface And Drip Edge',[{type:'archive',items:[{label:'Mid-1950s Tweed',title:'1956 Fender Champ',html:'<p>The control, rear and board photographs provide several views of one small amplifier. The archive year is retained; no unclear date stamp is decoded from this example. The interior image is condition evidence rather than an instruction to open another amp.</p>',photos:[ph2.champ56Front,ph2.champ56Back,ph2.champ56Board]},{label:'Dated 5F1 Example',title:'1959 Fender Champ',html:'<p>This cabinet’s chart provides the readable IB stamp shown above. Its front and rear photographs keep the label in the context of the complete amp. They don’t certify all components as original simply because the paper date is legible.</p>',photos:[ph2.champ59Front,ph2.champ59Back,ph2.champ59Chart]},{label:'Blackface With Tremolo',title:'1965 Fender Vibro Champ',html: `<p>Joe’s ${a('https://reverb.com/item/100841502-fender-vibro-champ-1965-blackface','1965 blackface example')} shows the front controls, single-speaker rear layout, circuit board and AA764 tube chart. Volume, Treble and Bass are joined by Speed and Intensity for tremolo. Compare that five-control panel with the single Volume control on the earlier tweed Champ. The printed AA764 designation identifies the circuit family; the listing supplies this example’s 1965 date.</p>`,photos:[ph2.vibroChamp65Front,ph2.vibroChamp65Back,ph2.vibroChamp65Board,ph2.vibroChamp65Chart]},{label:'Early Silverface With Aluminum Trim',title:'1968 Fender Vibro Champ',html: `<p>The silver panel and aluminum surround on Joe’s ${a('https://reverb.com/item/63721946-fender-vibro-champ-1968-drip-edge','1968 drip-edge Vibro Champ')} show the early silverface appearance. The five controls retain the separate tremolo Speed and Intensity adjustment. Its rear photograph shows the installed Warehouse replacement speaker. The loose speaker is the original supplied with the amp; Joe’s listing says it needs a recone. Keep that distinction when comparing the photos with factory specifications.</p>`,photos:[ph2.vibroChamp68Front,ph2.vibroChamp68Controls,ph2.vibroChamp68Back,ph2.vibroChamp68Speaker]}]}],'archive'),
section('references','Champ Identification References','History, Factory Drawings And Original Specifications',[refs([
['Joe’s 1949 Champion 600','https://reverb.com/item/71880693-fender-champion-600-1949','Two-tone cabinet, rear controls and disclosed service work.'],['Joe’s 1965 Blackface Vibro Champ','https://reverb.com/item/100841502-fender-vibro-champ-1965-blackface','Front, rear, chassis and tube-chart photographs.'],['Joe’s 1968 Drip-Edge Vibro Champ','https://reverb.com/item/63721946-fender-vibro-champ-1968-drip-edge','Silverface appearance and replacement/original speaker distinction.'],['Fender Champ History',champHistory,'Champion origins, the 1964 redesign and later model exclusions.'],['Wide-Panel Champ Field Record',fg('wide-panel-tweed-champ'),'5C1 tube set, rating and cabinet details.'],['Narrow-Panel Champ Field Record',fg('narrow-panel-tweed-champ'),'5E1/5F1 sequence, speaker sizes and black-covered transition.'],['Blackface Champ Field Record',fg('blackface-champ'),'AA764 controls, eight-inch speaker and early grille-logo details.'],['Fender Champ And Vibro Champ Manual','https://www.fmicassets.com/Damroot/Original/10001/OM_leg_gtramp_Vibro_Champ_1980.PDF','1980 six-watt rating and separate control layouts.']
]),cta('Send Your Champ Photos To Joe','Show the front, rear, paper chart and visible speaker markings. Include what you know about repairs, storage and any parts kept with the amplifier.')])
],faqs:[{q:'Is Every Handwired 5F1 An Original Fender Champ?',a:'No. Modern Fender models and replicas can be handwired. The chassis, cabinet, markings and dated components need to support vintage manufacture.'},{q:'What Separates A Champ From A Vibro Champ?',a:'The original Vibro Champ adds tremolo circuitry, another 12AX7 and Speed and Intensity controls. The regular Champ lacks those features.'},{q:'Did An Original Silverface Vibro Champ Have Reverb?',a:'No. The later ’68 Custom Vibro Champ Reverb is a different model with reverb and a ten-inch speaker.'},{q:'Can I Date A Champ From Its Serial Number?',a:'Use its tube-chart stamp and supporting original component codes. Fender amp serial numbers aren’t reliable year identifiers.'}],closing:`<p>Identify the cabinet and controls, then compare the chart and circuit before narrowing the date. The ${a(pairLink('champ','value'),'Champ and Vibro Champ price guide')} keeps the different versions separate. If the panel says Vibrolux, use the ${a(pairLink('vibrolux'),'Vibrolux guide')} instead. The ${a(era,'Fender amp eras article')} explains why the Champ’s long-running tweed form can overlap other families’ cosmetic changes.</p>`};

